TURATH_CHUNK(14,[{"num":2800,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ:  أَوْصَانِي حَبِيبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثٍ، لَنْ أَدَعَهُنَّ مَا عِشْتُ: بِصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَصَلَاةِ الضُّحَى، وَبِأَنْ لَا أَنَامَ حَتَّى أُوتِرَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (722) عن هارون بن عبدالله ومحمد بن رافع، قالا: حدثنا ابن أبي فُدَيك، عن الضحاك بن عثمان، عن إبراهيم ابن عبدالله بن حُنين، عن أبي مُرَّة مولى أمِّ هانئ، عن أبي الدرداء فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أداء صلاة الوتر قبل النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (722).","chapter_en":"What has been narrated about performing Witr before sleeping","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["Abu al-Darda’ said: “My beloved (the Prophet ﷺ) advised me with three things that I will not leave as long as I live: fasting three days of every month, praying Duha, and not sleeping until I have prayed Witr.”"]}},"tuhfa":{},"full":1,"rep":[2926,4449],"tks":"صحيح: رواه مسلم (722)."},{"num":2801,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: أَوْصَانِي حَبِيبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلاَثَةٍ لاَ أَدَعُهُنَّ إِنْ شَاءَ اللَّهُ تَعَالَى أَبَدًا. أَوْصَانِي بِصَلاَةِ الضُّحَى، وَبِالْوِتْرِ قَبْلَ النَّوْمِ، وَبِصِيَامِ ثَلاَثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ."],"takhrij":"صحيح: رواه النسائي (2404) عن علي بن حجر، قال: حدثنا إسماعيل، حدثنا محمد بن أبي حرملة، عن عطاء بن يسار، عن أبي ذرٍّ فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أداء صلاة الوتر قبل النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by al-Nasa’i (2404), Ibn Khuzaymah (1083), and Ahmad (21518).","chapter_en":"What has been narrated about performing Witr before sleeping","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["Abu Dharr al-Ghifari said: “My beloved (the Prophet ﷺ) advised me with three things that I will never leave, Allah willing: Duha prayer, Witr before sleeping, and fasting three days of every month.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2924],"tks":"صحيح: رواه النسائي (2404). وابن خزيمة (1083)، والإمام أحمد (21518)."},{"num":2802,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  أَوْتِرُوا قَبْلَ أَنْ تُصْبِحُوا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (754) عن أبي بكر بن أبي شيبة، حدثنا عبدالأعلى بن عبد الأعلى، عن معمر، عن يحيى بن أبي كثير، عن أبي نضرة، عن أبي سعيد فذكره. ثم رواه مسلم من وجه آخر عن يحيى بن أبي كثير قال: أخبرني أبونضرة العَوَقِيُّ-وهو المنذر بن مالك بن قَطْعَة-أن أبا سعيـد أخبرهم، أنهم سألوا النبي صلى الله عليه وسلم عن الوتر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من المبادرة لأداء صلاة الوتر قبل طلوع الفجر، ومن تعمَّد تأخيره حتى طلع الفجر فلا وتر له","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (754).","chapter_en":"Hastening to perform Witr before Fajr rises; and whoever deliberately delays it until Fajr has risen has no Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":9,"content":{"translation":{"en":["Abu Sa‘id al-Khudri narrated that the Prophet ﷺ said: “Pray Witr before you reach morning (before Fajr comes in).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (754) ."},{"num":2803,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَدْرَكَ الصُّبْحَ وَلَمْ يُوتِرْ، فَلَا وِتْرَ لَهُ."],"takhrij":"صحيح: أخرجه ابن خزيمة (1092)، وابن حبان (2408)، والحاكم (1125) كلهم من طريق هشام، عن قتادة، عن أبي نضرة، عن أبي سعيد.. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من المبادرة لأداء صلاة الوتر قبل طلوع الفجر، ومن تعمَّد تأخيره حتى طلع الفجر فلا وتر له","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: recorded by Ibn Khuzaymah (1092), Ibn Hibban (2408), and al-Hakim (301–302/1).","chapter_en":"Hastening to perform Witr before Fajr rises; and whoever deliberately delays it until Fajr has risen has no Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":9,"content":{"translation":{"en":["Abu Sa‘id narrated that the Prophet ﷺ said: “Whoever reaches Fajr without having prayed Witr, then there is no Witr for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه ابن خزيمة (1092)، وابن حبان (2408)، والحاكم (1125)."},{"num":2804,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  بَادِرُوا الصُّبْحَ بِالْوِتْرِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (750) من طريق ابن أبي زائدة، أخبرني عاصم الأحول، عن عبدالله بن شقيق، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من المبادرة لأداء صلاة الوتر قبل طلوع الفجر، ومن تعمَّد تأخيره حتى طلع الفجر فلا وتر له","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (750).","chapter_en":"Hastening to perform Witr before Fajr rises; and whoever deliberately delays it until Fajr has risen has no Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar narrated that the Prophet ﷺ said: “Beat (the coming of) Fajr with Witr.” (i.e., perform Witr before Fajr arrives.)"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (750)."},{"num":2805,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا طَلَعَ الْفَجْرُ، فَقَدْ ذَهَبَ كُلُّ صَلاَةِ اللَّيْلِ وَالْوِتْرُ، فَأَوْتِرُوا قَبْلَ طُلُوعِ الْفَجْرِ."],"takhrij":"حسن: رواه الترمذي (469) عن محمود بن غيلان، حدثنا عبد الرزاق، أخبرنا ابن جريج، عن سليمان بن موسى، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من المبادرة لأداء صلاة الوتر قبل طلوع الفجر، ومن تعمَّد تأخيره حتى طلع الفجر فلا وتر له","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (469), al-Hakim (302/1), and al-Bayhaqi (478/2).","chapter_en":"Hastening to perform Witr before Fajr rises; and whoever deliberately delays it until Fajr has risen has no Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar narrated from the Prophet ﷺ that he said: “When Fajr has risen, then all night-prayer and Witr have passed—so pray Witr before the rising of Fajr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (469) والحاكم (1/302)، والبيهقي (2/478)."},{"num":2806,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا عَمِلَ عَمَلًا أَثْبَتَهُ، وَكَانَ إِذَا نَامَ مِنَ اللَّيْلِ أَوْ مَرِضَ صَلَّى مِنَ النَّهَارِ ثِنْتَيْ عَشْرَةَ رَكْعَةً."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746: 141) عن علي بن خشْرم، أخبرنا عيسى –وهو ابن يونس-، عن شعبة، عن قتادة، عن زرارة، عن سعد بن هشام الأنصاري، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ماجاء في قضاء الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (746:141).","chapter_en":"What has been narrated about making up (qadā’) the Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ, whenever he did an act (of worship), he would keep it consistent. And if he slept through the night (i.e., missed his night prayer) or became ill, he would pray twelve rak‘ahs during the daytime."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (746: 141)."},{"num":2807,"demo":false,"sanad":"","matn":["عَنِ الْأَغَرِّ الْمُزَنِيِّ أَنَّ رَجُلًا أَتَى رسولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نبيَّ اللَّهِ إِنِّي أَصْبَحْتُ وَلَمْ أوتِرْ، فَقَالَ: إِنَّمَا الْوِتْرُ بِاللَّيْلِ ، قَالَ: يَا نبيَّ اللَّهِ إِنِّي أَصْبَحْتُ وَلَمْ أَوْتِرْ قَالَ: فأوْتِرْ ."],"takhrij":"حسن: رواه الطبراني في الكبير (891)، والبيهقي في الكبرى (4522) كلاهما من طريق زهير بن معاوية، عن خالد بن أبي كريمة، حدثنا معاوية بن قرّة، عن الأغر المزني قال فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في قضاء الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Kabir (280–281/1) and al-Bayhaqi in al-Kubra (479/2).","chapter_en":"What has been narrated about making up (qadā’) the Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["Al-Agharr al-Muzani narrated that a man came to the Messenger of Allah ﷺ and said: “O Prophet of Allah, I have reached morning and I did not pray Witr.” He said: “Witr is only at night.” The man said again: “O Prophet of Allah, I have reached morning and I did not pray Witr.” He said: “Then pray Witr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (887)، والبيهقي في الكبرى (4522)."},{"num":2808,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ نَامَ عَنْ وِتْرِهِ، أَوْ نَسِيَهُ، فَلْيُصَلِّهِ إِذَا أَصْبَحَ أَوْ ذَكَرَهُ."],"takhrij":"صحيح: رواه أبو داود (1431) عن محمد بن عوف، حدثنا عثمان بن سعيد، عن أبي غسان محمد بن مطرف المدني، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ماجاء في قضاء الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1431), al-Hakim (302/1), and al-Bayhaqi (480/2).","chapter_en":"What has been narrated about making up (qadā’) the Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":10,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said: “Whoever sleeps and misses his Witr, or forgets it, then let him pray it when he reaches morning or when he remembers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1431) والحاكم (1127)، والبيهقي (4533)."},{"num":2809,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ قَالَ:  سَأَلْتُ عَائِشَةَ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: كَانَ يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً. يُصَلِّي ثَمَانَ رَكَعَاتٍ، ثُمَّ يُوتِرُ. ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ."],"takhrij":"صحيح: رواه مسلم في صلاة مسافرين (738/126) عن محمد بن المثنى، حدثنا ابن أبي عدي، حدثنا هشام، عن يحيى، عن أبي سلمة فذكره.","grade":"صحيح","chapter_ar":"باب أداء ركعتين بعد الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (738:126).","chapter_en":"Performing two rak‘ahs after Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["Abu Salamah said: I asked ‘A’ishah about the prayer of the Messenger of Allah ﷺ. She said: “He used to pray thirteen rak‘ahs: he would pray eight rak‘ahs, then pray Witr, then pray two rak‘ahs while sitting; and when he wanted to bow (rukū‘), he would stand and then bow.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (738/126)."},{"num":2810,"demo":false,"sanad":"","matn":["عن أبي أمامة كان رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُوتر بِتِسعٍ حتَّى إذا بَدُن وكَثُر لحمُه أوتر بسبعٍ، وصلَّى ركعتين وهو جالس، يقرأ فيهما: إِذَا زُلْزِلَتِ و قُلْ يَا أَيُّهَا الْكَافِرُونَ."],"takhrij":"حسن: رواه أحمد (22313)، والطبراني في الكبير (8/332)، والبيهقي (4827)، ومحمد بن نصر في كتاب الوتر (55) كلهم من طريق عُمارة بن زاذان، ثنا أبو غالب، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب أداء ركعتين بعد الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (22313), al-Tabarani in al-Kabir (8/332), and al-Bayhaqi (3/33).","chapter_en":"Performing two rak‘ahs after Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["Abu Umamah said: The Messenger of Allah ﷺ used to pray Witr with nine (rak‘ahs) until, when he became heavier and his flesh increased, he prayed Witr with seven; and he would pray two rak‘ahs while sitting, reciting in them: “When the earth is shaken…” and “Say: O disbelievers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22313)، والطبراني في الكبير (8/332)، والبيهقي (4827)،."},{"num":2811,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَقَالَ: إِنَّ السَّفَرَ جَهْدٌ وَثِقَلٌ، فَإِذَا أَوْتَرَ أَحَدُكُمْ فَلْيَرْكَعْ رَكْعَتَيْنِ، فَإِنِ اسْتَيْقَظَ وَإِلا كَانَتَا لَهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (1410)، والبزار -كشف الأستار (692) كلاهما من حديث عبدالله بن صالح، حدثني معاوية بن صالح، عن عبدالرحمن بن جبير، عن أبيه، عن ثوبان فذكره.","grade":"حسن","chapter_ar":"باب أداء ركعتين بعد الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Kabir (2/87) and al-Bazzar (Kashf al-Astar, 692).","chapter_en":"Performing two rak‘ahs after Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":11,"content":{"translation":{"en":["Thawban said: We were with the Messenger of Allah ﷺ on a journey, and he said: “This travel is exertion and heaviness. So if one of you prays Witr, then let him pray two rak‘ahs; if he wakes up (later), fine, and if not, then those two will be for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (1410)، والبزار -كشف الأستار (692)."},{"num":2812,"demo":false,"sanad":"","matn":["عن أنس بْنِ سِيرِينَ قـال: قُلْتُ: لاِبْنِ عُمَرَ أَرَأَيْتَ الرَّكْعَتَيْنِ قَبْلَ صَلاَةِ الْغَدَاةِ أُطِيلُ فِيهِمَا الْقِرَاءَةَ؟ فَقَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ مَثْنَى مَثْنَى، وَيُوتِرُ بِرَكْعَةٍ، وَيُصَلِّي الرَّكْعَتَيْنِ قَبْلَ صَلاَةِ الْغَدَاةِ. وَكَأَنَّ الأَذَانَ بِأُذُنَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في صلاة الوتر (995)، ومسلم في صلاة المسافرين (749/157) كلاهما من حديث حماد بن زيد، قال: حدثنا أنس ابن سيرين فذكره، واللفظ للبخاري، وسبق لفظ مسلم وهو قريب منه مع بعض الزيادات.","grade":"متفق عليه","chapter_ar":"باب وتر النبي ﷺ بواحدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (995) and Muslim (749:157).","chapter_en":"The Witr of the Prophet ﷺ with one rak‘ah","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Sirin said: I asked Ibn ‘Umar. I said: “What do you think about the two rak‘ahs before Fajr—should one lengthen the recitation in them?” He said: “The Prophet ﷺ used to pray the night prayer two by two, and pray Witr with one rak‘ah, and he would pray the two rak‘ahs before Fajr immediately after the adhan.”"]},"buhuth":{"en":["Hammad explained that this indicates speed and immediacy."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (995)، ومسلم (749/157). وقوله: (( كأن الأذان بأذنيه)) قال حماد: أي سرعة."},{"num":2813,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَجُلاً، سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلاَةِ اللَّيْلِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَةُ اللَّيْلِ مَثْنَى مَثْنَى، فَإِذَا خَشِيَ أَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً، تُوتِرُ لَهُ مَا قَدْ صَلَّى."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (13) عن نافع وعبد الله بن دينار، عن ابن عمر، فذكره. ورواه البخاري في الوتر (990) ومسلم في صلاة المسافرين (749) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب وتر النبي ﷺ بواحدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (13), al-Bukhari (990), and Muslim (749).","chapter_en":"The Witr of the Prophet ﷺ with one rak‘ah","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Umar narrated that a man asked the Messenger of Allah ﷺ about the night prayer, and the Messenger of Allah ﷺ said: “The night prayer is two by two. If one of you fears the coming of Fajr, then let him pray one rak‘ah that will make Witr for what he has already prayed.”"]}},"tuhfa":{},"full":1,"rep":[2748],"tks":"متفق عليه: رواه مالك (13) والبخاري (990) ومسلم (749)."},{"num":2814,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ قـال: قـال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : الْوِتْرُ رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (752) عن شيبان بن فَرُّوخ، حدثنا عبد الوارث، عن أبي التيَّاح، قال: حدثني أبو مِجْلَز، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب وتر النبي ﷺ بواحدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (752).","chapter_en":"The Witr of the Prophet ﷺ with one rak‘ah","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":12,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The Messenger of Allah ﷺ said: “Witr is one rak‘ah at the end of the night.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (752)."},{"num":2815,"demo":false,"sanad":"","matn":["عَنْ أَبِي مِجْلَزٍ قَالَ:  سَأَلْتُ ابْنَ عَبَّاسٍ، عَنِ الْوِتْرِ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ. وَسَأَلْتُ ابْنَ عُمَرَ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (753) عن زهير بن حرب، حدثنا عبد الصمد، حدثنا همام، حدثنا قتادة، عن أبي مِجْلَز فذكره.","grade":"صحيح","chapter_ar":"باب وتر النبي ﷺ بواحدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (753).","chapter_en":"The Witr of the Prophet ﷺ with one rak‘ah","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":12,"content":{"translation":{"en":["Abu Majlaz said: I asked Ibn ‘Abbas about Witr. He said: I heard the Messenger of Allah ﷺ say: “One rak‘ah at the end of the night.” And I asked Ibn ‘Umar, and he said: I heard the Messenger of Allah ﷺ say: “One rak‘ah at the end of the night.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (753)."},{"num":2816,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصلِّي مِنَ اللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْهَا بِوَاحِدَةٍ، فَإِذَا فَرَغَ اضْطَجَعَ عَلَى شقة الْأَيْمَنِ."],"takhrij":"صحيح: رواه مالك في صلاة الليل (8) عن ابن شهاب، عن عروة بن الزبير، عن عائشة فذكرته. ورواه مسلم في صلاة المسافرين (736) عن يحيى بن يحيى، عن مالك به مثله وزاد في آخر الحديث: حتى يأتيه المؤذِّن فيصلي ركعتين خفيفتين .","grade":"صحيح","chapter_ar":"باب وتر النبي ﷺ بواحدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Malik (8) and Muslim (736). Muslim adds at the end of the hadith: “until the mu’adhdhin came to him, and then he would pray two light rak‘ahs.”","chapter_en":"The Witr of the Prophet ﷺ with one rak‘ah","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, narrated that the Messenger of Allah ﷺ used to pray at night eleven rak‘ahs. He would perform Witr with one rak‘ah from them, and when he finished, he would lie down on his right side."]},"buhuth":{"en":["Her statement “he lay down” means: in the house, to rest after the night prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (8) ورواه مسلم (736) وزاد في آخر الحديث: (( حتى يأتيه المؤذن فيصلي ركعتين خفيفتين)."},{"num":2817,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بْنِ عبدالرحمن أنَّه سَأَلَ عَائِشَةَ: كَيْفَ كَانَتْ صَلاَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ؟ قَالَتْ: مَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزِيدُ فِي رَمَضَانَ، وَلاَ فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً، يُصلِّي أَرْبَعًا فَلاَ تَسْأَلْ عَنْ حُسنِهن وطُولِهِن، ثُمَّ يُصلِّي أَرْبَعًا فَلاَ تَسْأَلْ عَنْ حُسنِهنَّ وطُولِهِنَّ، ثمَّ يُصَلِّي ثَلاَثًا."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (9) عن سعيد بن أبي سعيد المقبري، عن أبي سلمة بن عبدالرحمن بن عوف فذكره.","grade":"متفق عليه","chapter_ar":"وتر النبي ﷺ بثلاث ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (9), al-Bukhari (1147), and Muslim (738).","chapter_en":"The Witr of the Prophet ﷺ with three rak‘ahs","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":13,"content":{"translation":{"en":["Abu Salamah ibn ‘Abd al-Rahman said that he asked ‘A’ishah: “How was the prayer of the Messenger of Allah ﷺ in Ramadan?” She said: “The Messenger of Allah ﷺ would not increase in Ramadan or outside of it beyond eleven rak‘ahs. He would pray four—do not ask about their beauty and their length—then he would pray four—do not ask about their beauty and their length—then he would pray three.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (9) والبخاري (1147)، ومسلم (738)."},{"num":2818,"demo":false,"sanad":"","matn":["عَنْ أُبَىِّ بْنِ كَعْبٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْوَتْرِ بِـ { سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى } وَفِي الرَّكْعَةِ الثَّانِيَةِ بِـ { قُلْ يَا أَيُّهَا الْكَافِرُونَ } وَفِي الثَّالِثَةِ بِـ { قُلْ هُوَ اللَّهُ أَحَدٌ } وَلاَ يُسَلِّمُ إِلاَّ فِي آخِرِهِنَّ، وَيَقُولُ: يَعْنِي بَعْدَ التَّسْلِيمِ: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ. ثَلاَثًا."],"takhrij":"صحيح: رواه النسائي (1701) عن يحيى بن موسى قال: أنبأنا عبدالعزيز بن خالد، قال: حدثنا سعيد بن أبي عروبة، عن قتادة، عن عزْرة، عن سعيد بن عبدالرحمن بن أَبْزَى، عن أبيه، عن أُبَيِّ بن كعب فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"وتر النبي ﷺ بثلاث ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by al-Nasa’i (1701).","chapter_en":"The Witr of the Prophet ﷺ with three rak‘ahs","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":13,"content":{"translation":{"en":["Ubayy ibn Ka‘b said: The Messenger of Allah ﷺ used to recite in Witr: in the first rak‘ah, “Glorify the Name of your Lord, the Most High”; in the second, “Say: O you disbelievers”; and in the third, “Say: He is Allah, the One.” He would not give salām except at the end of them, and he would say—meaning after the salām—“Subḥān al-Malik al-Quddūs” three times."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه النسائي (1701)."},{"num":2819,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْ ذَلِكَ بِخَمْسٍ، لَا يَجْلِسُ فِي شَيْءٍ إِلَّا فِي آخِرِهَا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (737) من طرق عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب وتر النبي ﷺ خمساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (737). Al-Tirmidhi (459) added: “When the mu’adhdhin gave the adhan, he would stand and pray two light rak‘ahs.”","chapter_en":"The Prophet’s ﷺ Witr as five (rak‘ahs)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":14,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ used to pray at night thirteen rak‘ahs; he would perform Witr from that with five, and he would not sit in any of them except at the last one."]},"buhuth":{"en":["Al-Nasa’i (1717) also narrated it, and in it: “He used to pray Witr with five and he would not sit except in the last of them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2743],"tks":"صحيح: رواه مسلم (737). وزاد الترمذي (459): فإذا أذن المؤذن قام فصلى ركعتين خفيفتين."},{"num":2820,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصلّي تسعَ رَكَعَاتٍ، لَا يجلِسُ فِيهَا إِلَّا فِي الثَّامِنَةِ، فَيَذْكُرُ اللهَ ، وَيَحْمَدُهُ، وَيَدْعُوهُ ، ثُمَّ يَنْهَضُ، وَلَا يُسَلِّم، ثُمَّ يَقُومُ، فَيُصَلِّي التَّاسِعَةَ، ثُمَّ يَقْعُدُ فَيَذْكُرُ اللهَ، وَيَحْمَدُهُ، وَيَدْعُوهُ، ثمَّ يُسلّم تَسْلِيمًا يُسْمِعُنَا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746) من حديث قتادة، عن زُرارة بن أوفى، عن سعد بن هشام بن عامر، عن عائشة في حديث طويل سبق ذكره كاملاً في جامع صلاة النبي صلى الله عليه وسلم في الليل.","grade":"صحيح","chapter_ar":"وتر النبي ﷺ بتسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (746).","chapter_en":"The Witr of the Prophet ﷺ with nine rak‘ahs","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":15,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ would pray nine rak‘ahs. He would not sit in them except in the eighth, wherein he would remember Allah, praise Him, and supplicate; then he would stand and not give salām. Then he would stand and pray the ninth, then sit and remember Allah, praise Him, and supplicate; then he would give salām in a manner that we could hear."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (746)."},{"num":2821,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ بِثَلاَثِ عَشْرَةَ رَكْعَةً، فَلَمَّا كَبِرَ وَضَعُفَ أَوْتَرَ بِتِسْعٍ."],"takhrij":"حسن: رواه الترمذي (457)، والنسائي (1709) كلاهما من طريق أبي معاوية، عن الأعمش، عن عمرو بن مُرَّة، عن يحيى بن الجزار، عن أمِّ سلمة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في الوتر بثلاث عشرة وبسبع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (457) who graded it hasan, and by al-Nasa’i (1709).","chapter_en":"What has been narrated about Witr as thirteen and as seven","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":16,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ used to pray Witr with thirteen rak‘ahs, and when he grew older and became weaker, he prayed Witr with seven."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (457) وحسنه، والنسائي (1709)."},{"num":2822,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن أَبِي قيس قَالَ: قلتُ لِعَائِشَةَ: بِكَمْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُوتِرُ؟ قَالَتْ: كَانَ يُوتِرُ بِأَرْبَعٍ وَثَلاَثٍ، وَسِتٍّ وَثَلاَثٍ، وَثَمَانٍ وَثَلاَثٍ، وَعَشْرٍ وَثَلاَثٍ، وَلَمْ يَكُنْ يُوتِرُ بِأَنْقَصَ مِنْ سَبْعٍ، وَلاَ بِأَكْثَرَ مِنْ ثَلاَثَ عَشْرَةَ."],"takhrij":"صحيح: رواه أبو داود (1362) عن أحمد بن صالح ومحمد بن سلمة المرادي، قالا: حدثنا ابن وهب، عن معاوية بن صالح، عن عبدالله بن أبي قيس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الوتر بثلاث عشرة وبسبع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1362).","chapter_en":"What has been narrated about Witr as thirteen and as seven","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":16,"content":{"translation":{"en":["‘Abdullah ibn Abi Qays said: I said to ‘A’ishah: “With how many (rak‘ahs) would the Messenger of Allah ﷺ pray Witr?” She said: “He would pray Witr as four and three, six and three, eight and three, and ten and three; and he would not pray Witr with fewer than seven, nor with more than thirteen.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود ( 1362)."},{"num":2823,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يفصِلُ بَيْنَ الْوَتْرِ وَالشَّفْعِ بِتَسْلِيمَةٍ ويُسمعنا."],"takhrij":"حسن: رواه الإمام أحمد (5461)، والطبراني في الأوسط (757) كلاهما من حديث عتَّاب بن زياد، حدثنا أبو حمزة -يعني السُّكَّري، عن إبراهيم -يعني الصائغ - عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الفصل بين الشفع والوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (5461) and al-Tabarani in al-Awsat (757); Ibn Hibban authenticated it (2435).","chapter_en":"What has been narrated about separating the even (shaf‘) from the Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":17,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ used to separate the Witr from the even (shaf‘) with a salām, and he would let us hear it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (5461)، والطبراني في الأوسط (757)، وصححه ابن حبان (2435)."},{"num":2824,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ بِرَكْعَةٍ، وَكَانَ يَتَكَلَّمُ بَيْنَ الرَّكْعَتَيْنِ وَالرَّكْعَةِ."],"takhrij":"حسن: رواه ابن أبي شيبة في مصنفه (6871) عن شبابة بن سوّار، حدثنا ابن أبي ذئب، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء من الفصل بين الشفع والوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Abi Shaybah in his Musannaf (6871).","chapter_en":"What has been narrated about separating the even (shaf‘) from the Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":17,"content":{"translation":{"en":["‘A’ishah narrated that the Prophet ﷺ would pray Witr with one rak‘ah, and he would speak between the two rak‘ahs and the single rak‘ah (of Witr)."]}},"tuhfa":{},"voc":["sh9944",6799],"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة في مصنفه (6871)."},{"num":2825,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوِتْرُ حَقٌّ عَلَى كُلِّ مُسْلِمٍ، فَمَنْ أَحَبَّ أَنْ يُوتِرَ بِخَمْسٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِثَلاَثٍ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِوَاحِدَةٍ فَلْيَفْعَلْ."],"takhrij":"صحيح: رواه أبو داود (1422) عن عبدالرحمن بن المبارك، حدَّثني قُريش بن حَيَّان العجلي، حدثنا بكر بن وائل، عن الزهري، عن عطاء بن يزيد الليثي، عن أبي أيوب الأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب تخيير الموتر بين الواحدة والثلاث والخمس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1422), al-Nasa’i (1710, 1711), and Ibn Majah (1190).","chapter_en":"Giving the one who prays Witr the choice between one, three, and five (rak‘ahs)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":18,"content":{"translation":{"en":["Abu Ayyub said: The Messenger of Allah ﷺ said: “Witr is a right upon every Muslim. Whoever loves to pray Witr with five, let him do so; whoever loves to pray Witr with three, let him do so; and whoever loves to pray Witr with one, let him do so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1422)، والنسائي (1710، 1711)، وابن ماجه (1190)."},{"num":2826,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوْتِرْ بِخَمْسٍ، فَإِنْ لَمْ تَسْتَطِعْ فَبِثَلَاثٍ، فَإِنْ لَمْ تَسْتَطِعْ فَبِوَاحِدَةٍ، فَإِنْ لَمْ تَسْتَطِعْ فَأَوْمِئْ إِيمَاءً."],"takhrij":"حسن: رواه الإمام أحمد (23545) عن يزيد، حدثنا سفيان بن حسين، عن الزهري، عن عطاء بن يزيد الليثي، عن أبي أيوب الأنصاري ، فذكر الحديث.","grade":"حسن","chapter_ar":"باب من لم يستطع أن يُوتر يومِئُ إيماءً برأسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (23545), Abu Dawud al-Tayalisi (594), al-Shashi (1111), and al-Hakim (1/303).","chapter_en":"Whoever cannot perform Witr signals by nodding with his head","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":19,"content":{"translation":{"en":["Abu Ayyub al-Ansari said: The Messenger of Allah ﷺ said: “Pray Witr with five; if you cannot, then with three; if you cannot, then with one; and if you cannot, then gesture by nodding.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23545)، وأبو داود الطيالسي (594)، والشاشي (1111)، والحاكم (1131)."},{"num":2827,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تُوتِرُوا بِثَلَاثٍ، أَوْتِرُوا بِخَمْسٍ أَوْ بِسَبْعٍ، وَلَا تُشبه بِصَلَاةِ الْمَغْرِبِ ."],"takhrij":"صحيح: رواه الدارقطني (1650) والحاكم في المستدرك (1138) كلاهما من طريق عبدالله بن سليمان بن الأشعث، ثنا أحمد بن صالح، ثنا عبدالله بن وهب، أخبرنا سليمان بن بلال، عن صالح بن كَيْسان، عن عبدالله بن الفضل، عن أبي سلمة بن عبدالرحمن وعبدالرحمن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن تشبيه صلاة الوتر بصلاة المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by al-Daraqutni (2/24) and al-Hakim in al-Mustadrak (1138).","chapter_en":"Prohibition of making the Witr prayer resemble the Maghrib prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not pray Witr with three. Pray Witr with five or with seven, and do not make it resemble the Maghrib prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الدارقطني (1650) والحاكم في المستدرك (1138)."},{"num":2828,"demo":false,"sanad":"","matn":["عن أُبَيِّ بن كعب قال: كان رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يوتر بـ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى و قُلْ يَا أَيُّهَا الْكَافِرُونَ و قُلْ هُوَ اللَّهُ أَحَدٌ."],"takhrij":"صحيح: رواه أبو داود (1423)، وابن ماجه (1171)، وأحمد (21141) كلهم من حديث عثمان بن أبي شيبة، حدثنا أبو حفص الأبَّار، قال: حدَّثنا الأعمش، عن طلحة وزُبيد، عن سعيد بن عبدالرحمن بن أبْزى، عن أبيه، عن أُبَيِّ بن كعب فذكره، وزاد ابن ماجه بين طلحة وزبيد ذر وهو: ابن عبدالله المرهبي ثقة من رجال الجماعة.","grade":"صحيح","chapter_ar":"باب ما يقرأ به في الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1423), Ibn Majah (1171), Ahmad (21141), and authenticated by Ibn Hibban (2436).","chapter_en":"What is recited in the Witr prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":21,"content":{"translation":{"en":["Ubayy ibn Ka‘b said: The Messenger of Allah ﷺ used to pray Witr reciting: “Glorify the Name of your Lord, the Most High,” “Say: O you disbelievers,” and “Say: He is Allah, the One.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13706],"tks":"صحيح: رواه أبو داود (1423)، وابن ماجه (1171)، وأحمد (21141)، وصححه ابن حبان (2436)."},{"num":2829,"demo":false,"sanad":"","matn":["عن ابن عبدالرحمن بن أبْزى، عن أبيه، أن رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كان يُوتر بـ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى و قُلْ يَا أَيُّهَا الْكَافِرُونَ و قُلْ هُوَ اللَّهُ أَحَدٌ وكان يقول إذا سلَّم: سبحان الملك القدوس ثلاثاً ويرفع صوتَه بالثالثة."],"takhrij":"صحيح: رواه النسائي (1732) عن عمرو بن يزيد، قال: حدثنا بهز بن أسد، قال: حدثنا شُعبة، عن سلمة وزُبيد، عن ذر، عن ابن عبدالرحمن بن أبْزى فذكره.","grade":"صحيح","chapter_ar":"باب ما يقرأ به في الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (1732).","chapter_en":"What is recited in the Witr prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":21,"content":{"translation":{"en":["Ibn ʿAbd al-Raḥmān ibn Abzā reported from his father: The Messenger of Allah ﷺ used to perform Witr reciting: “Glorify the Name of your Lord, the Most High,” “Say: O disbelievers,” and “Say: He is Allah, One.” When he gave the salām, he would say: “Glory be to the King, the Most Holy,” three times, raising his voice on the third."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1732)."},{"num":2830,"demo":false,"sanad":"","matn":["عن ابن عباس قال: كان رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يوتر بثلاث، يقرأ في الأولى: بـ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى وفي الثانية بـ قُلْ يَا أَيُّهَا الْكَافِرُونَ وفي الثالثة بـ قُلْ هُوَ اللَّهُ أَحَدٌ."],"takhrij":"صحيح: رواه النسائي (1702)، والدارمي (1596) كلاهما من طريق أَبِي أُسَامة، حدَّثنا زكريا بن أبي زائدة، عن أبي إسحاق، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما يقرأ به في الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (1702), al-Dārimī (1596), Ibn Mājah (1172), and Aḥmad (2726).","chapter_en":"What is recited in the Witr prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":21,"content":{"translation":{"en":["Ibn ʿAbbās reported: The Messenger of Allah ﷺ used to perform Witr with three rakʿahs. In the first he would recite: “Glorify the Name of your Lord, the Most High.” In the second: “Say: O disbelievers.” And in the third: “Say: He is Allah, One.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13707],"tks":"صحيح: رواه النسائي (1702)، والدارمي (1596)، وابن ماجه (1172)، وأحمد (2726)."},{"num":2831,"demo":false,"sanad":"","matn":["عن عمران بن حصين أن النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أوتر بـ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى."],"takhrij":"صحيح: رواه النسائي (1743) عن بشر بن خالد، قال حدثنا شَبابةُ، عن شعبة، عن قتادة، عن زُرارة بن أوفى، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب ما يقرأ به في الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (1743).","chapter_en":"What is recited in the Witr prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":21,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported: The Prophet ﷺ performed Witr reciting: “Glorify the Name of your Lord, the Most High.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1743)."},{"num":2832,"demo":false,"sanad":"","matn":["عن عائشة أن النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كان يقرأ في الركعتين التي يُوتر بعدهما: بـ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى و قُلْ يَا أَيُّهَا الْكَافِرُونَ ويقرأ في الوتر: بـ قُلْ هُوَ اللَّهُ أَحَدٌ و قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ و قُلْ أَعُوذُ بِرَبِّ النَّاسِ."],"takhrij":"حسن: رواه الدارقطني (1675)، والحاكم (1143) وعنه البيهقي (3/37) عن الحسين بن إسماعيل، ثنا أبو حاتم الرازي، ثنا سعيد بن عفير، ثنا يحيى بن أيوب، عن يحيى بن سعيد، عن عمرة بنت عبدالرحمن، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما يقرأ به في الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good: Narrated by al-Dāraquṭnī (2/34–35), al-Ḥākim (1143), and al-Bayhaqī from him (3/37).","chapter_en":"What is recited in the Witr prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":21,"content":{"translation":{"en":["ʿĀʾishah reported: The Messenger of Allah ﷺ used to recite in the two rakʿahs after which he would perform the Witr rakʿah: “Glorify the Name of your Lord, the Most High,” and “Say: O disbelievers.” Then in the Witr rakʿah he would recite: “Say: He is Allah, One,” “Say: I seek refuge in the Lord of daybreak,” and “Say: I seek refuge in the Lord of mankind.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (1675)، والحاكم (1143)، وعنه البيهقي (3/37)."},{"num":2833,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي آخِرِ وِتْرِهِ اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ."],"takhrij":"صحيح: رواه أبو داود (1427)، والترمذي (3561)، والنسائي (1748)، وابن ماجه (1179) كلهم من طريق حماد بن سلمة، قال: حدثني هشام بن عمرو الفزاري، عن عبدالرحمن بن الحارث بن هشام المخزومي، عن علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب ما يدعى به في قنوت الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1427), al-Tirmidhi (3561), al-Nasa’i (1748), and Ibn Majah (1179).","chapter_en":"What is supplicated in the Qunut of Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":22,"content":{"translation":{"en":["‘Ali ibn Abi Talib narrated that the Prophet ﷺ used to say at the end of Witr: “O Allah, I seek refuge in Your pleasure from Your wrath, and I seek refuge in Your pardon from Your punishment, and I seek refuge in You from You. I cannot enumerate praise of You; You are as You have praised Yourself.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11070],"tks":"صحيح: رواه أبو داود (1427)، والترمذي (3561)، والنسائي (1748)، وابن ماجه (1179)."},{"num":2834,"demo":false,"sanad":"","matn":["عَنْ الْحَسَنِ بن عَلِيٍّ قَالَ: علَّمني رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلِمَاتٍ أقولُهنَّ فِي الْوِتْرِ: اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تولَّيتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وقِنِي شرَّ مَا قَضَيْتَ، إنَّك تَقْضِي وَلاَ يُقْضَى عَلَيْكَ، وإنَّه لاَ يَذِلُّ مَنْ وَالَيْتَ، وَلاَ يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ ربَّنا وَتَعَالَيْتَ ."],"takhrij":"صحيح: رواه أبو داود (1425)، والترمذي (464)، والنسائي (1745)، وابن ماجه (1178) كلهم من طريق أبي إسحاق، عن بُريد بن أبي مريم السلولي، عن أبي الحوراء، عن الحسن بن علي فذكره.","grade":"صحيح","chapter_ar":"باب ما يدعى به في قنوت الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1425), al-Tirmidhi (464), al-Nasa’i (1745), and Ibn Majah (1178).","chapter_en":"What is supplicated in the Qunut of Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":22,"content":{"translation":{"en":["Al-Hasan ibn ‘Ali said: The Messenger of Allah ﷺ taught me words to say in Witr: “O Allah, guide me among those You have guided; grant me well-being among those You have granted well-being; take me into Your care among those You have taken into Your care; bless for me what You have given; and protect me from the evil of what You have decreed. Indeed, You decree and none can decree against You. Indeed, he whom You befriend is not humiliated, and he whom You oppose is not honored. Blessed are You, our Lord, and Exalted.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11071],"tks":"صحيح: رواه أبو داود (1425)، والترمذي (464)، والنسائي (1745)، وابن ماجه (1178)."},{"num":2835,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدٍ قَالَ:  قُلْتُ لِأَنَسٍ: هَلْ قَنَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الصُّبْحِ؟ قَالَ: نَعَمْ، بَعْدَ الرُّكُوعِ يَسِيرًا."],"takhrij":"متفق عليه: رواه البخاري في الوتر (1001)، ومسلم في المساجد (677/298) كلاهما من حديث أيوب، عن محمد بن سيرين به مثله.","grade":"متفق عليه","chapter_ar":"باب القنوت بعد الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1001) and Muslim (677/298).","chapter_en":"Qunut after bowing (rukū‘)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":23,"content":{"translation":{"en":["Muhammad ibn Sirin said: I said to Anas: “Did the Messenger of Allah ﷺ perform Qunut in Fajr?” He said: “Yes—after rukū‘ for a short time.”"]},"buhuth":{"en":["His phrase “for a short time” means for some days, as ‘Asim explains in the following narration."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1001)، ومسلم (677/298)."},{"num":2836,"demo":false,"sanad":"","matn":["عن عاصم بن سليمان الأحول قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ عَنِ الْقُنُوتِ،. فَقَالَ: قَدْ كَانَ الْقُنُوتُ. قُلْتُ: قَبْلَ الرُّكُوعِ أَوْ بَعْدَهُ، قَالَ: قَبْلَهُ. قَالَ: فَإِنَّ فُلاَنًا أَخْبَرَنِي عَنْكَ أَنَّكَ قُلْتَ: بَعْدَ الرُّكُوعِ. فَقَالَ: كَذَبَ، إِنَّمَا قَنَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ الرُّكُوعِ شَهْرًا، ـ أُرَاهُ ـ كَانَ بَعَثَ قَوْمًا يُقَالُ لَهُمُ: الْقُرَّاءُ زُهَاءَ سَبْعِينَ رَجُلاً إِلَى قَوْمٍ مِنَ الْمُشْرِكِينَ دُونَ أُولَئِكَ، وَكَانَ بَيْنَهُمْ وَبَيْنَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَهْدٌ: فَقَنَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَهْرًا يَدْعُو عَلَيْهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الوتر (1002)، ومسلم في المساجد (677/301) كلاهما من طريق عاصم به واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب القنوت بعد الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1002) and Muslim (677/301), with the wording of al-Bukhari. His word “kadhaba” here means “he erred/made a mistake.”","chapter_en":"Qunut after bowing (rukū‘)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":23,"content":{"translation":{"en":["‘Asim ibn Sulayman al-Ahwal said: I asked Anas ibn Malik about Qunut. He said: “Qunut did occur.” I asked: “Before rukū‘ or after it?” He said: “Before it.” Then he said: “So-and-so told me that you said: ‘After rukū‘.’” Anas said: “He is mistaken. The Messenger of Allah ﷺ only performed Qunut after rukū‘ for one month. I think he sent a group called the Qurra’, about seventy men, to some polytheists (other than those with whom there was a treaty). The Messenger of Allah ﷺ then performed Qunut for a month, supplicating against them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1002)، ومسلم (677/301) واللفظ للبخاري. وقوله: “كذب” معنى أخطأ."},{"num":2837,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ سِيرِينَ، قَالَ: حَدَّثَنِي مَنْ، صَلَّى مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَةَ الْغَدَاةِ. فَلَمَّا رَفَعَ رَأْسَهُ مِنَ الرَّكْعَةِ الثَّانِيَةِ قَامَ هُنَيَّةً."],"takhrij":"صحيح: رواه أبو داود (1446)، والنسائي (1073) كلاهما من طريق بشر بن مفضَّل، حدثنا يونس بن عبيد، عن محمد بن سيرين فذكره.","grade":"صحيح","chapter_ar":"باب القنوت بعد الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1446) and al-Nasa’i (1073). The word “hunayyah” means a short, small amount of time.","chapter_en":"Qunut after bowing (rukū‘)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":23,"content":{"translation":{"en":["Muhammad ibn Sirin said: Someone who prayed the morning prayer with the Prophet ﷺ told me that when he raised his head from the second rak‘ah, he stood for a brief moment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1446)، والنسائي (1073). وقوله: هنية - أي القدر اليسير من الوقت."},{"num":2838,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ سُئِلَ عَنِ الْقُنُوتِ، فِي صَلاَةِ الصُّبْحِ فَقَالَ: كُنَّا نَقْنُتُ قَبْلَ الرُّكُوعِ وَبَعْدَهُ."],"takhrij":"صحيح: رواه ابن ماجه (1183) عن نصر بن علي الجهضميُّ قال: حدثنا سهل بن يوسف، قال: حدثنا حُميد، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب في القنوت في النازلة قبل الركوع وبعده","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Ibn Majah (1183) and ‘Abd al-Razzaq (4966).","chapter_en":"Qunut in a calamity (nāzilah) before rukū‘ and after it","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":24,"content":{"translation":{"en":["Anas ibn Malik was asked about Qunut in the Fajr prayer. He said: “We used to perform Qunut before rukū‘ and after it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1183) وعبد الرزاق (4966)."},{"num":2839,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْوِتْرِ... وَلَا يُسَلِّمُ إِلَّا فِي آخِرِهِنَّ وَيَقُولُ : يَعْنِي بَعْدَ التَّسْلِيمِ: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ ثَلَاثًا."],"takhrij":"صحيح: رواه النسائي (1699) من طريق سفيان، عن زُبيد، عن سعيد ابن عبدالرحمن بن أَبزى، عن أبيه، عن أبي بن كعب فذكره.","grade":"صحيح","chapter_ar":"باب ما كان يقوله النبي بعد التسليم من صلاة الوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by al-Nasa’i (1699).","chapter_en":"What the Prophet ﷺ used to say after giving salām from Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":25,"content":{"translation":{"en":["Ubayy ibn Ka‘b said: The Messenger of Allah ﷺ, after completing his Witr and giving salām, would say: “Subḥān al-Malik al-Quddūs” three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1699)."},{"num":2840,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْعِينَ رَجُلاً لِحَاجَةٍ، يُقَالُ لَهُمُ الْقُرَّاءُ، فَعَرَضَ لَهُمْ حَيَّانِ مِنْ بَنِي سُلَيْمٍ: رِعْلٌ وَذَكْوَانُ، عِنْدَ بِئْرٍ يُقَالُ لَهَا بِئْرُ مَعُونَةَ، فَقَالَ الْقَوْمُ: وَاللَّهِ مَا إِيَّاكُمْ أَرَدْنَا، إِنَّمَا نَحْنُ مُجْتَازُونَ فِي حَاجَةٍ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَتَلُوهُمْ، فَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِمْ شَهْرًا فِي صَلاَةِ الْغَدَاةِ، وَذَلِكَ بَدْءُ الْقُنُوتِ وَمَا كُنَّا نَقْنُتُ.","قال عبدالعزيز: وسأل رجل أنساً عن القنوت: أبعد الركوع، أو عند فَراغٍ من القراءة؟ قال: لا بل عند فَراغٍ من القراءةِ."],"takhrij":"صحيح: رواه البخاري في المغازي (4088) عن أبي معمر، حدثنا عبد الوارث، حدثنا عبدالعزيز، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في بدء القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by al-Bukhari (4088).","chapter_en":"What has been narrated regarding the beginning/origin of Qunut","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":26,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ sent seventy men on a mission; they were known as the Qurra’. Two clans from Banu Sulaym—Ri‘l and Dhakwān—confronted them at a well called Bi’r Ma‘ūnah. The group said: “By Allah, we did not intend you; we are only passing through on an errand for the Prophet ﷺ.” But they killed them. So the Prophet ﷺ supplicated against them for a month in the morning (Fajr) prayer; this was the beginning of Qunut, and we had not used to perform Qunut (in that manner). ‘Abd al-‘Aziz said: A man asked Anas about Qunut: “Is it after rukū‘, or when one finishes the recitation?” He said: “Rather, it is when one finishes the recitation.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4088)."},{"num":2841,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: دَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الَّذِينَ قَتَلُوا ـ يَعْنِي ـ أَصْحَابَهُ بِبِئْرِ مَعُونَةَ ثَلاَثِينَ صَبَاحًا، حِينَ يَدْعُو عَلَى رِعْلٍ وَلِحْيَانَ: وَعُصَيَّةَ عَصَتِ اللَّهَ وَرَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ أَنَسٌ: فَأَنْزَلَ اللَّهُ تَعَالَى لِنَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الَّذِينَ قُتِلُوا أَصْحَابِ بِئْرِ مَعُونَةَ قُرْآنًا قَرَأْنَاهُ حَتَّى نُسِخَ بَعْدُ: بَلِّغُوا قَوْمَنَا فَقَدْ لَقِينَا رَبَّنَا، فَرَضِيَ عَنَّا، وَرَضِينَا عَنْهُ."],"takhrij":"متفق عليه: رواه مالك عن إسحاق بن عبدالله بن أبي طلحة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب القنوت في الصلوات إذا نزلت بالمسلمين نازلةٌ والجَهْرُ به","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik; al-Bukhari (4095); Muslim (677). Muslim adds “and Dhakwān” after “Ri‘l.”","chapter_en":"The recommendation of Qunut in the prayers when a calamity (nāzilah) befalls the Muslims, and reciting it aloud","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":27,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ supplicated against those who killed (i.e., his Companions) at Bi’r Ma‘ūnah for thirty mornings, when he would supplicate against Ri‘l and Lihyān: “and ‘Usayyah—who disobeyed Allah and His Messenger.” Anas said: Then Allah revealed Qur’an concerning those who were killed at Bi’r Ma‘ūnah, which we recited until it was later abrogated: “Convey to our people that we have met our Lord; He is pleased with us, and we are pleased with Him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8885,11074],"tks":"متفق عليه: رواه مالك، والبخاري (4095)، ومسلم (677)، وزاد مسلم: «وذكوان» بعد «رعل»."},{"num":2842,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رِعْلاً، وَذَكْوَانَ وَعُصَيَّةَ وَبَنِي لَحْيَانَ اسْتَمَدُّوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَدُوٍّ، فَأَمَدَّهُمْ بِسَبْعِينَ مِنَ الأَنْصَارِ، كُنَّا نُسَمِّيهِمُ الْقُرَّاءَ فِي زَمَانِهِمْ، كَانُوا يَحْتَطِبُونَ بِالنَّهَارِ، وَيُصَلُّونَ بِاللَّيْلِ، حَتَّى كَانُوا بِبِئْرِ مَعُونَةَ، قَتَلُوهُمْ، وَغَدَرُوا بِهِمْ، فَبَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَنَتَ شَهْرًا يَدْعُو فِي الصُّبْحِ عَلَى أَحْيَاءٍ مِنْ أَحْيَاءِ الْعَرَبِ، عَلَى رِعْلٍ وَذَكْوَانَ وَعُصَيَّةَ وَبَنِي لَحْيَانَ.","قال أنس: فقرأنا فيهم قرآناً، ثم إنَّ ذلك رُفِع: بَلِّغوا عَنَّا قومنا أنَّا لقينا ربَّنـا فرضي عنا وأرضانا ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4090) عن عبد الأعلى بن حماد، حدثنا يزيد بن زُريع، حدثنا سعيد، عن قتادة، عن أنس فذكره واللفظ له.","grade":"متفق عليه","chapter_ar":"باب استحباب القنوت في الصلوات إذا نزلت بالمسلمين نازلةٌ والجَهْرُ به","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (4090) with this wording; Muslim (677/303–304).","chapter_en":"The recommendation of Qunut in the prayers when a calamity (nāzilah) befalls the Muslims, and reciting it aloud","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":27,"content":{"translation":{"en":["Anas ibn Malik said: Ri‘l, Dhakwān, ‘Usayyah, and Banu Lihyān asked the Messenger of Allah ﷺ for help against an enemy, so he sent them seventy of the Ansar—whom we used to call “the Qurra’” in their time. They would gather firewood by day and pray by night. When they reached Bi’r Ma‘ūnah, they were killed and betrayed. When this reached the Prophet ﷺ, he performed Qunut for a month in Fajr, supplicating against tribes among the Arabs: Ri‘l, Dhakwān, ‘Usayyah, and Banu Lihyān. Anas said: We recited Qur’an concerning them, then it was later lifted: “Convey to our people that we have met our Lord; He has been pleased with us and has pleased us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4090) واللفظ له، ومسلم (677، 303، 304)."},{"num":2843,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ حِينَ يَفْرُغُ مِن صَلَاةِ الْفَجْرِ مِنَ الْقِرَاءَةِ، ويكبِّر، وَيَرْفَعُ رَأْسَهُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ ثُمَّ يَقُولُ وَهُوَ قَائِمٌ: اللَّهُمَّ أنْجِ الْوَلِيدَ بْنَ الْوَلِيدِ، وَسَلَمَةَ بْنَ هِشَامٍ، وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ، وَالْمُسْتَضْعَفِينَ مِنَ الْمُؤْمِنِينَ، واللهم اشدُدْ وَطْأتك عَلَى مُضَرَ، وَاجْعَلْهَا عَلَيْهِمْ كَسِنِيِّ يُوسُفَ. اللَّهُمَّ العَنْ لَحْيانَ ورِعْلاً وَذَكْوَانَ وعُصَيَّة عصتِ اللَّهَ وَرَسُولَهُ ثُمَّ بَلَغَنَا أَنَّهُ تَرَكَ ذَلِكَ لَمَّا أُنْزِلَ: ﴿لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ﴾ [سورة آلِ عِمْرَانَ: 128].","وفي رواية: قنت بعد الركعة في صلاةٍ شهراً.","وفي رواية قَالَ أَبُو هُرَيْرَةَ: وَاللهِ لَأُقَرِّبَنَّ بِكُمْ صَلَاةَ رَسُولِ اللهِ صلى الله عليه وسلم ، فَكَانَ أَبُو هُرَيْرَةَ يَقْنُتُ فِي الظُّهْرِ، وَالْعِشَاءِ الْآخِرَةِ، وَصَلَاةِ الصُّبْحِ، وَيَدْعُو لِلْمُؤْمِنِينَ، وَيَلْعَنُ الْكُفَّارَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4560)، ومسلم في المساجد (675) كلاهما من طريق ابن شهاب، عن سعيد بن المسيب وأبي سلمة بن عبدالرحمن، عن أبي هريرة فذكر الحديث واللفظ لمسلم،","grade":"متفق عليه","chapter_ar":"باب استحباب القنوت في الصلوات إذا نزلت بالمسلمين نازلةٌ والجَهْرُ به","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (4560) and Muslim (675).","chapter_en":"The recommendation of Qunut in the prayers when a calamity (nāzilah) befalls the Muslims, and reciting it aloud","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":27,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ used to say—when he finished the recitation in Fajr, said the takbīr, and raised his head: “Sami‘a Allahu liman hamidah, Rabbana wa laka al-hamd,” then while standing he would say: “O Allah, rescue al-Walid ibn al-Walid, Salamah ibn Hisham, ‘Ayyash ibn Abi Rabi‘ah, and the oppressed among the believers. O Allah, intensify Your punishment upon Muḍar, and make it years like the years of Yusuf. O Allah, curse Lihyān, Ri‘l, Dhakwān, and ‘Usayyah—‘Usayyah disobeyed Allah and His Messenger.” Then we were informed that he left that when the verse was revealed: “You have no part in the matter: whether He turns to them in mercy or punishes them—for indeed they are wrongdoers.” [Āl ‘Imrān: 128] In one narration: He performed Qunut after the rak‘ah for a month in a prayer.","In another narration Abu Hurayrah said: “By Allah, I will bring you close to the prayer of the Messenger of Allah ﷺ,” so Abu Hurayrah would perform Qunut in Ẓuhr, ‘Isha’, and Fajr, supplicating for the believers and cursing the disbelievers."]},"buhuth":{"en":["“Like the years of Yusuf” means years of severe hardship—drought and high prices."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4560)، ومسلم (675)."},{"num":2844,"demo":false,"sanad":"","matn":["عَنْ خُفَافِ بْنِ إِيمَاءٍ الْغِفَارِيِّ قَالَ:  قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةٍ: اللَّهُمَّ الْعَنْ بَنِي لِحْيَانَ، وَرِعْلًا، وَذَكْوَانَ، وَعُصَيَّةَ عَصَوُا اللهَ وَرَسُولَهُ. غِفَارُ غَفَرَ اللَّهُ لَهَا، وَأَسْلَمُ سَالَمَهَا اللهُ."],"takhrij":"صحيح: رواه مسلم في المساجد (679) من حديث ابن وهب، عن الليث، عن عِمران بن أبي أَنَس، عن حنظلة بن علي، عن خُفاف بن إيماء فذكره.","grade":"صحيح","chapter_ar":"باب استحباب القنوت في الصلوات إذا نزلت بالمسلمين نازلةٌ والجَهْرُ به","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: Muslim (679).","chapter_en":"The recommendation of Qunut in the prayers when a calamity (nāzilah) befalls the Muslims, and reciting it aloud","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":27,"content":{"translation":{"en":["Khufaf ibn Imā’ al-Ghifari said: The Messenger of Allah ﷺ said in a prayer: “O Allah, curse Banu Lihyān, Ri‘l, Dhakwān, and ‘Usayyah—who disobeyed Allah and His Messenger. (As for) Ghifār—may Allah forgive them; and Aslam—may Allah grant them safety.”"]},"buhuth":{"en":["In another narration: He bowed then raised his head and said: “Ghifār—may Allah forgive them; and Aslam—may Allah grant them safety; and ‘Usayyah disobeyed Allah and His Messenger. O Allah, curse Banu Lihyān, and curse Ri‘l and Dhakwān.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10521],"tks":"صحيح: رواه مسلم (679)."},{"num":2845,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ مِنَ الرَّكْعَةِ الآخِرَةِ مِنَ الْفَجْرِ يَقُولُ: اللَّهُمَّ الْعَنْ فُلاَنًا وَفُلاَنًا وَفُلاَنًا بَعْدَ مَا يَقُولُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ فَأَنْزَلَ اللَّهُ: ﴿لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ﴾ [سورة آلِ عِمْرَانَ: 128]."],"takhrij":"صحيح: رواه البخاري في المغازي (4069) عن يحيى بن عبدالله السلمي، أخبرنا عبدالله (وهو ابن المبارك) أخبرنا معمر، عن الزهري، حدثني سالم، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب استحباب القنوت في الصلوات إذا نزلت بالمسلمين نازلةٌ والجَهْرُ به","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: al-Bukhari (4069).","chapter_en":"The recommendation of Qunut in the prayers when a calamity (nāzilah) befalls the Muslims, and reciting it aloud","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":27,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said he heard the Messenger of Allah ﷺ—when he raised his head from rukū‘ in the last rak‘ah of Fajr—say: “O Allah, curse so-and-so, so-and-so, and so-and-so,” after he said: “Sami‘a Allahu liman hamidah, Rabbana wa laka al-hamd.” Then Allah revealed: “You have no part in the matter: whether He turns to them in mercy or punishes them—for indeed they are wrongdoers.” [Āl ‘Imrān: 128]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4069)."},{"num":2846,"demo":false,"sanad":"","matn":["عن ابن عمر أنه سمع النبيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حين رفع رأسه من صلاة الصبح من الركعة الأخيرة قال: اللهمَّ العَنْ فُلاناً وفُلاناً يدعو على أُناس من المنافقين. فأنزل الله عزوجل: ﴿لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ﴾ [سورة آل عمران: 128]."],"takhrij":"صحيح: رواه النسائي (1078) عن إسحاق بن إبراهيم، قال: أنبأنا عبد الرزاق، قال: حدثنا معمر، عن الزهري، عن سالم، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب استحباب القنوت في الصلوات إذا نزلت بالمسلمين نازلةٌ والجَهْرُ به","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasā’ī (1078), ‘Abd al-Razzāq (4027), Aḥmad (6349), and Ibn Khuzaymah (622).","chapter_en":"The recommendation of Qunut in the prayers when a calamity (nāzilah) befalls the Muslims, and reciting it aloud","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":27,"content":{"translation":{"en":["Ibn ‘Umar said that he heard the Prophet ﷺ—when he raised his head in Fajr in the final rak‘ah—say: “O Allah, curse so-and-so and so-and-so,” supplicating against some hypocrites. Then Allah, Mighty and Majestic, revealed: “You have no share in the matter—whether He turns to them in mercy or punishes them—for indeed they are wrongdoers.” [Āl ‘Imrān: 128]"]},"buhuth":{"en":["(Fiqh of the Chapter)","Fiqh of the chapter: There is no disagreement among the scholars that when a calamity (nāzilah) befalls the Muslims, Qunūt is recommended in all prayers, and it is left when there is no such cause—except al-Shāfi‘ī, who holds that Qunūt continues in Fajr all the time.","The majority interpret the wording “then he left it” to mean: he stopped the cursing and specific supplication against those tribes mentioned in the hadith. Al-Shāfi‘ī and those who agree with him interpret it to mean: he left it in the other four prayers but did not leave it in Fajr—based on a weak report from Anas: “The Messenger of Allah ﷺ continued to make Qunūt in Fajr until he departed this world,” as will come in the chapter on leaving Qunūt.","Imam Aḥmad said: No Qunūt in Fajr except during a nāzilah that befalls the Muslims, so the imam supplicates for the Muslim armies."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1078)، وعبد الرزاق (4027)، وأحمد (6349)، وابن خزيمة (622)."},{"num":2847,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ بْنِ عَازِبٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْنُتُ فِي الصُّبْحِ وَالْمَغْرِبِ."],"takhrij":"صحيح: رواه مسلم في المساجد (678) من حديث شعبة، عن عمرو بن مُرَّةَ، قال: سمعتُ ابن أبي ليلى، قال: حدثنا البراء بن عازب فذكره.","grade":"صحيح","chapter_ar":"باب القنوت في الصبح والمغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (678).","chapter_en":"Qunūt in Fajr and Maghrib","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":28,"content":{"translation":{"en":["Al-Barā’ ibn ‘Āzib said: The Messenger of Allah ﷺ used to perform Qunūt in Fajr and Maghrib."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (678)."},{"num":2848,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: كَانَ الْقُنُوتُ فِي الْمَغْرِبِ وَالْفَجْرِ."],"takhrij":"صحيح: رواه البخاري في الأذان (798)، وفي الوتر (1004) من طرقٍ عن إسماعيل، حدثنا خالد الحذّاء، عن أبي قلابة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب القنوت في الصبح والمغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Bukhārī (1004) and (798).","chapter_en":"Qunūt in Fajr and Maghrib","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":28,"content":{"translation":{"en":["Anas said: Qunūt was in Maghrib and Fajr."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (798)، (798)."},{"num":2849,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَنَتَ شَهْرًا يَدْعُو عَلَى أَحْيَاءٍ مِنْ أَحْيَاءِ الْعَرَبِ، ثُمَّ تَرَكَهُ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4089)، ومسلم في المساجد (677/304) من حديث هشام، عن قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في ترك القنوت بعد زوال سببه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (4089) and Muslim (677/304). Muslim’s wording is as above; al-Bukhārī’s wording: “The Messenger of Allah ﷺ performed Qunūt for a month after rukū‘, supplicating against tribes among the Arabs.”","chapter_en":"Leaving Qunūt after its cause has ended","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":29,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ performed Qunūt for a month, supplicating against certain tribes among the Arabs, then he left it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4089)، ومسلم (677/304). واللفظ لمسلم، ولفظ البخاري: «قنت رسول الله ﷺ شهرا بعد الركوع يدعو على أحياء من العرب»."},{"num":2850,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَنَتَ بَعْدَ الرَّكْعَةِ فِي صلاته شَهْرًا إِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ يَقُولُ فِي قُنُوتِهِ: اللهمَّ أَنج الْوَلِيدَ بْنَ الْوَلِيدِ، اللهمَّ نَجِّ سَلَمَةَ بْنَ هِشَامٍ، اللهمَّ نَجِّ عيَّاش بْنَ أَبِي رَبِيعَةَ، اللهمَّ نَجِّ الْمُسْتَضْعَفِينَ مِنَ الْمُسْلِمِينَ، اللهمَّ اشْدُدْ وَطْأَتَكَ عَلَى مُضَرَ. اللهمَّ اجْعَلْهَا عَلَيْهِمْ سِنِينَ كَسِنِيِّ يُوسُفَ ، قَالَ أَبُو هُرَيْرَةَ: ثمَّ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَرَكَ الدُّعَاءَ بَعدُ. فَقُلْتُ: أُرى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ تَرَكَ الدُّعَاءَ لَهُمْ، قَالَ: فَقِيلَ: وَمَا تَرَاهُمْ قَدْ قَدِمُوا؟."],"takhrij":"صحيح: رواه مسلم في المساجد (675/295) من طريق الوليد بن مسلم قال: حدثنا الأوزاعي، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكره وقد سبق.","grade":"صحيح","chapter_ar":"باب ما جاء في ترك القنوت بعد زوال سببه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (675/295).","chapter_en":"Leaving Qunūt after its cause has ended","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ performed Qunūt for a month after the rak‘ah in his prayer. When he said, “Sami‘a Allahu liman hamidah,” he would say in his Qunūt: “O Allah, rescue al-Walid ibn al-Walid. O Allah, rescue Salamah ibn Hisham. O Allah, rescue ‘Ayyash ibn Abi Rabi‘ah. O Allah, rescue the oppressed among the Muslims. O Allah, intensify Your punishment upon Muḍar. O Allah, make it years upon them like the years of Yusuf.” Abu Hurayrah said: Then I saw the Messenger of Allah ﷺ later stop that supplication. I said: “I see the Messenger of Allah ﷺ has stopped supplicating for them.” It was said: “Do you not think they have arrived (i.e., been delivered)?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (675/295)."},{"num":2851,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الأَشْجَعِيِّ، قَالَ: قُلْتُ لأَبِي: يَا أَبَةِ إِنَّكَ قَدْ صَلَّيْتَ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ وَعَلِيِّ بْنِ أَبِي طَالِبٍ هَا هُنَا بِالْكُوفَةِ نَحْوًا مِنْ خَمْسِ سِنِينَ، أَكَانُوا يَقْنُتُونَ؟ قَالَ: أَىْ بُنَىَّ مُحْدَثٌ."],"takhrij":"صحيح: رواه الترمذي (402)، وابن ماجه (1241)، والإمام أحمد (15879) كلُّهم من طريق يزيد بن هارون، قال: أخبرنا أبو مالك قال: فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في ترك القنوت بعد زوال سببه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (402), Ibn Mājah (1241), and Aḥmad (15879). Its chain is authentic.","chapter_en":"Leaving Qunūt after its cause has ended","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":29,"content":{"translation":{"en":["Abū Mālik al-Ashjaʿī said: I said to my father, “My father, you prayed behind the Messenger of Allah ﷺ, Abū Bakr, ʿUmar, ʿUthmān, and ʿAlī ibn Abī Ṭālib here in Kūfah for about five years. Did they perform Qunūt?” He replied, “My son, it is a newly introduced practice.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (402)، وابن ماجه (1241)، وأحمد (15879). وإسناده صحيح."},{"num":2852,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَقْنُتُ إِلَّا أَنْ يَدْعُوَ لِأَحَدٍ، أَوْ يَدْعُوَ عَلَى أَحَدٍ، وَكَانَ إِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، قَالَ: رَبَّنَا وَلَكَ الْحَمْدُ، اللَّهُمَّ أَنْجِ، وَذَكَرَ الْحَدِيثَ."],"takhrij":"صحيح: رواه ابن خزيمة (619) عن محمد بن يحيى، نا أبو داود، حدثنا إبراهيم بن سعد، عن الزهري، عن سعيد وأبي سلمة، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن النبي ﷺ ما كان يقنت إلا إذا دعا لقوم أو على قوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Ibn Khuzaymah (619). Its basis is in Ṣaḥīḥ al-Bukhārī (4560).","chapter_en":"The Prophet ﷺ did not perform Qunūt except when supplicating for a people or against a people","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ would not perform Qunūt except to supplicate for someone or against someone. When he said, “Sami‘a Allahu liman hamidah,” he would say: “Rabbana wa laka al-hamd, O Allah rescue …” and he mentioned the hadith."]}},"tuhfa":{},"voc":["ibnkhuzaymah",620],"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (619). وأصله في صحيح البخاري (4560)."},{"num":2853,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ ، لَا يَقْنُتُ إِلَّا إِذَا دَعَا لِقَوْمٍ، أَوْ دَعَا عَلَى قَوْمٍ."],"takhrij":"صحيح: رواه ابن خزيمة (620) عن محمد بن محمد بن مرزوق الباهلي، حدّثنا محمد بن عبدالله الأنصاري، حدثنا سعيد بن أبي عروبة، عن قتادة، عن أنس ، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن النبي ﷺ ما كان يقنت إلا إذا دعا لقوم أو على قوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Ibn Khuzaymah (620).","chapter_en":"The Prophet ﷺ did not perform Qunūt except when supplicating for a people or against a people","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":30,"content":{"translation":{"en":["Anas said: “The Prophet ﷺ did not perform Qunūt except when supplicating for a people or against a people.”"]}},"tuhfa":{},"voc":["ibnkhuzaymah",621],"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (620)."},{"num":2854,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَنَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَهْرًا مُتَتَابِعًا فِي الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ وَصَلاَةِ الصُّبْحِ فِي دُبُرِ كُلِّ صَلاَةٍ إِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. مِنَ الرَّكْعَةِ الآخِرَةِ. يَدْعُو عَلَى أَحْيَاءٍ مِنْ بَنِي سُلَيْمٍ، عَلَى رِعْلٍ وَذَكْوَانَ وَعُصَيَّةَ. وَيُؤَمِّنُ مَنْ خَلْفَهُ."],"takhrij":"حسن: رواه أبو داود (1443) عن عبدالله بن معاوية الجُمحي، حدَّثنا ثابت بن يزيد، عن هلال بن خَبَّاب، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب تأمين المأمومين خلف الإمام إذا دعا في القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (1443) and authenticated by Ibn Khuzaymah (618). Also narrated by Aḥmad (2746), with an addition at the end: “And he sent to them, calling them to Islam, but they killed them.”","chapter_en":"The congregation saying “Āmīn” behind the imam when he supplicates in Qunūt","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":31,"content":{"translation":{"en":["Ibn ‘Abbās said: The Messenger of Allah ﷺ performed Qunūt for a continuous month in Ẓuhr, ‘Aṣr, Maghrib, ‘Ishā’, and Fajr—at the end of every prayer—when he said, “Sami‘a Allahu liman hamidah,” in the last rak‘ah. He supplicated against certain clans from Banū Sulaym—against Ri‘l, Dhakwān, and ‘Uṣayyah—and those behind him would say “Āmīn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1443) وصححه ابن خزيمة (618)، ورواه الإمام أحمد (2746) وزاد في آخره: «وأرسل إليهم يدعوهم إلى الإسلام فقتلوهم»."},{"num":2855,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ فِي قِصَّةِ الْقُرَّاءِ وَقَتْلِهِمْ، قَالَ: فَقَالَ لِي أَنَسٌ: لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّمَا صَلَّى الْغَدَاةَ رَفَعَ يَدَيْهِ يَدْعُو عَلَيْهِمْ، يَعْنِي عَلَى الَّذِينَ قَتَلُوهُمْ."],"takhrij":"حسن: رواه البيهقي (3145) عن علي بن صقربن نصر السّكري ببغداد في سويقة غالب من كتابه، ثنا عفان بن مسلم، ثنا سليمان بن المغيرة، عن ثابت، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب رفع اليدين في دعاء القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bayhaqī (2/211).","chapter_en":"Raising the hands in the supplication of Qunūt","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":32,"content":{"translation":{"en":["In the story of the Qurra’ and their killing, Anas ibn Mālik said: “I saw the Messenger of Allah ﷺ—whenever he prayed Fajr—raise his hands and supplicate against them,” meaning those who killed them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (3145)."},{"num":2856,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ:  فُرِضَتِ الصَّلَاةُ رَكْعَتَيْنِ رَكْعَتَيْنِ فِي الْحَضَرِ وَالسَّفَرِ، فَأُقِرَّتْ صَلَاةُ السَّفَرِ، وَزِيدَ فِي صَلَاةِ الْحَضَرِ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة في السفر (8) عن صالح بن كيسان، عن عروة بن الزبير، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب صلاة المسافر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Mālik (8), al-Bukhārī (350), Muslim (685).","chapter_en":"The prayer of the traveler","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["‘Ā’ishah, the wife of the Prophet ﷺ, said: The prayer was initially prescribed as two rak‘ahs in both residence and travel. Then the travel prayer was kept as it is, and the resident prayer was increased."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (8) والبخاري (350)، ومسلم (685)."},{"num":2857,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  فَرَضَ اللَّهُ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ أَرْبَعًا، وَفِي السَّفَرِ رَكْعَتَيْنِ، وَفِي الْخَوْفِ رَكْعَةً."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (687) من طرق عن مجاهد وغيره عن ابن عباس، وعن موسى بن سلمة الهُذَلي قال: سألت ابن عباس: كيف أُصَلِّي إذا كنتُ بمكة، إذا لم أُصَلِّ مع الإمام. فقال: ركعتين سنة أبي القاسم صلى الله عليه وسلم .","grade":"صحيح","chapter_ar":"باب صلاة المسافر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (687).","chapter_en":"The prayer of the traveler","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbās said: Allah prescribed the prayer—on the tongue of your Prophet ﷺ—as four rak‘ahs when resident, two rak‘ahs when traveling, and one rak‘ah in fear."]},"buhuth":{"en":["As for the wording “in fear: one,” it is understood to mean that one prays one rak‘ah with the imam and completes another rak‘ah individually, as established in authentic reports. The majority of scholars hold that Ṣalāt al-Khawf matches the regular prayer in the number of rak‘ahs: four when resident and two when traveling."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2910,12209],"tks":"صحيح: رواه مسلم (687)."},{"num":2858,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ، قَالَ: صَلاَةُ السَّفَرِ رَكْعَتَانِ، وَصَلاَةُ الْجُمُعَةِ رَكْعَتَانِ، وَالْفِطْرُ وَالأَضْحَى رَكْعَتَانِ، تَمَامٌ غَيْرُ قَصْرٍ عَلَى لِسَانِ مُحَمَّدٍ ـ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه ابن ماجة (1064) من طريق يزيد بن زياد بن أبي الجعد، عن زبيد، عن عبدالرحمن بن أبي ليلى، عن كعب بن عُجرة، عن عمر فذكره.","grade":"حسن","chapter_ar":"باب صلاة المسافر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Ibn Mājah (1064), Ibn Khuzaymah (1425), al-Bayhaqī (3/199).","chapter_en":"The prayer of the traveler","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["‘Umar ibn al-Khaṭṭāb said: The travel prayer is two rak‘ahs, Jumu‘ah is two rak‘ahs, and (the prayers of) al-Fiṭr and al-Aḍḥā are two rak‘ahs—complete and not a shortening—on the tongue of Muhammad ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3333],"tks":"حسن: رواه ابن ماجه (1064)، وابن خزيمة (1425)، والبيهقي (5719)."},{"num":2859,"demo":false,"sanad":"","matn":["عَنْ أُمَيَّةَ بْنِ عَبْدِ اللَّهِ بْنِ خَالِدٍ، أَنَّهُ قَالَ لِعَبْدِ اللَّهِ بْنِ عُمَرَ: إِنَّا نَجِدُ صَلَاةَ الْحَضَرِ وَصَلَاةَ الْخَوْفِ فِي الْقُرْآنِ، وَلَا نَجِدُ صَلَاةَ السَّفَرِ فِي الْقُرْآنِ؟ فَقَالَ عَبْدُ اللَّهِ: يَا ابْنَ أَخِي، إِنَّ اللَّهَ عَزَّ وَجَلَّ بَعَثَ إِلَيْنَا مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا نَعْلَمُ شَيْئًا، فَإِنَّمَا نَفْعَلُ كَمَا رَأَيْنَا مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ."],"takhrij":"حسن: رواه ابن ماجة (1066)، والنسائي (1434) وصحّحه ابن خزيمة (946)، وابن حبان (1451)، والحاكم (946) كلهم من طريق الليث بن سعد، قال: حدثني ابن شهاب، عن عبدالله بن أبي بكر بن عبدالرحمن، عن أمية بن عبدالله بن خالد فذكره.","grade":"حسن","chapter_ar":"باب صلاة المسافر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Ibn Mājah (1066), al-Nasā’ī (1434). Authenticated by Ibn Khuzaymah (946) and Ibn Ḥibbān (1451).","chapter_en":"The prayer of the traveler","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":1,"content":{"translation":{"en":["Umayyah ibn ‘Abdullāh ibn Khālid ibn Asīd said to ‘Abdullāh ibn ‘Umar: “We find the resident prayer and the prayer of fear in the Qur’an, but we do not find the travel prayer in the Qur’an.” Ibn ‘Umar said: “My nephew, Allah the Mighty and Majestic sent Muhammad ﷺ to us while we did not know anything; we only do as we saw Muhammad ﷺ do.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1066)، والنسائي (1434) وصححه ابن خزيمة (946)، وابن حبان (1451)."},{"num":2860,"demo":false,"sanad":"","matn":["عن يعلى بن أُمَيَّةَ قال: قلت لعمر بن الخطاب: ﴿فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمُ الَّذِينَ كَفَرُوا﴾ [سورة النساء: 101] فقد أمِن الناس. فقـــــــــال: عجبتُ مما عجبتَ منـــه. فسألتُ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عن ذلك فقــــال: صدقة تصدق الله بها عليكم فاقبلوا صدقته ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (686) من طرق عن عبدالله بن إدريس، عن ابن جريج، عن ابن أبي عمار، عن عبدالله بن بابَيْهِ، عن يعلى بن أمية فذكره.","grade":"صحيح","chapter_ar":"باب جواز تقصير الصلاة في السفر ولو كان الطريق آمناً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (686).","chapter_en":"The permissibility of shortening the prayer while traveling even if the route is safe","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Ya‘lā ibn Umayyah said: I said to ‘Umar ibn al-Khaṭṭāb regarding Allah’s statement, “There is no blame upon you to shorten the prayer if you fear that those who disbelieve may harm you” [al-Nisā’: 101]—“But the people are now safe.” He said: “I was amazed at what you were amazed by.” So I asked the Messenger of Allah ﷺ about it, and he said: “It is a charity Allah has given you—so accept His charity.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12210],"tks":"صحيح: رواه مسلم (686)."},{"num":2861,"demo":false,"sanad":"","matn":["عَنْ عَدِيٍّ قَالَ: سَمِعْتُ الْبَرَاءَ يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ  كَانَ فِي سَفَرٍ فَصَلَّى الْعِشَاءَ الْآخِرَةَ. فَقَرَأَ فِي إِحْدَى الرَّكْعَتَيْنِ: ﴿وَالتِّينِ وَالزَّيْتُونِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (767)، ومسلم في الصلاة (464) كلاهما من حديث شعبة، عن عدي بن ثابت فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز تقصير الصلاة في السفر ولو كان الطريق آمناً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (767), Muslim (464).","chapter_en":"The permissibility of shortening the prayer while traveling even if the route is safe","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["‘Adī ibn Thābit said: I heard al-Barā’ narrating about the Messenger of Allah ﷺ that he was traveling and prayed ‘Ishā’, and in one of the two rak‘ahs he recited: “By the fig and the olive” (Sūrat al-Tīn)."]},"buhuth":{"en":["In another wording al-Barā’ said: “I have not heard anyone with a more beautiful voice than him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (767)، ومسلم (464)."},{"num":2862,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْمَدِينَةِ إِلَى مَكَّةَ، لاَ يَخَافُ إِلاَّ اللَّهَ رَبَّ الْعَالَمِينَ، فَصَلَّى رَكْعَتَيْنِ."],"takhrij":"صحيح: رواه الترمذي (547)، والنسائي (1435) كلاهما عن قتيبة بن سعيد، حدثنا هُشيم، عن منصور بن زاذان، عن ابن سيرين، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب جواز تقصير الصلاة في السفر ولو كان الطريق آمناً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (547) and al-Nasā’ī (1435). Al-Tirmidhī said: “Ḥasan Ṣaḥīḥ.”","chapter_en":"The permissibility of shortening the prayer while traveling even if the route is safe","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Abbās reported that the Messenger of Allah ﷺ set out from Madinah to Makkah, fearing none but Allah, the Lord of the worlds, and he prayed two rak‘ahs (i.e., he shortened the prayer)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (547)، والنسائي (1435). قال الترمذي: «حسن صحيح»."},{"num":2863,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ يَقُولُ: صلَّيت مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ رَكْعَتَيْنِ، وَمَعَ أَبِي بَكْرٍ رَكْعَتَيْنِ، وَمَعَ عمرَ رَكْعَتَيْنِ."],"takhrij":"صحيح: رواه النسائي (1439) عن محمد بن علي بن الحسن بن شقيق، قال: أخبرني أبي، أخبرنا أبو حمزة -وهو السُّكَّري- عن منصور، عن إبراهيم، عن علقمة، عن عبدالله بن مسعود قال: فذكره.","grade":"صحيح","chapter_ar":"باب جواز تقصير الصلاة في السفر ولو كان الطريق آمناً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasā’ī (1439).","chapter_en":"The permissibility of shortening the prayer while traveling even if the route is safe","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":2,"content":{"translation":{"en":["‘Abdullāh ibn Mas‘ūd said: I prayed two rak‘ahs with the Messenger of Allah ﷺ while traveling, and two with Abū Bakr, and two with ‘Umar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1439)."},{"num":2864,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ يُحِبُّ أَنْ تُؤْتَى رُخَصُهُ، كَمَا يَكْرَهُ أَنْ تُؤْتَى مَعْصِيَتُهُ."],"takhrij":"حسن: رواه الإمام أحمد (5873)، والبزار - كشف الأستار (988) كلاهما من حديث عبد العزيز بن محمد (وهو الدراوردي) عن عُمارة بن عَزِيَّة، عن حرب بن قيس، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب استحباب قصر الصلاة في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (5873) and al-Bazzār (Kashf al-Astār, 988). Authenticated by Ibn Ḥibbān (2742).","chapter_en":"The recommendation of shortening the prayer during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “Allah loves that His concessions (rukhaṣ) be taken, just as He dislikes that His disobedience be committed.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4615],"tks":"حسن: رواه الإمام أحمد (5873)، والبزار - كشف الأستار (988)، وصححه ابن حبان (2742)."},{"num":2865,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إنَّ اللَّهَ عزَّ وجلَّ يُحِبُّ أَنْ يُؤْتَى رُخَصُهُ كَمَا يُحِبُّ أَنْ يُؤْتَى عَزَائِمُهُ ."],"takhrij":"حسن: رواه الطبراني في الكبير (11881)، والبزار -كشف الأستار (990) كلاهما من طريق حسين بن محمد الذارع، ثنا حصين بن نمير، ثنا هشام بن حسان، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب استحباب قصر الصلاة في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Kabīr (11/323) and al-Bazzār (Kashf al-Astār, 990).","chapter_en":"The recommendation of shortening the prayer during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Abbās said: The Messenger of Allah ﷺ said: “Indeed Allah—Mighty and Majestic—loves that His concessions be taken, just as He loves that His firm commands (ʿazā’im) be carried out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في «الكبير» (11881)، والبزار - كشف الأستار (990)."},{"num":2866,"demo":false,"sanad":"","matn":["عَنْ حَفْصٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ قَالَ: انْطُلِقَ بِنَا إِلَى الشَّامِ إِلَى عَبْدِ الْمَلِكِ، وَنَحْنُ أَرْبَعُونَ رَجُلًا مِنَ الْأَنْصَارِ لِيَفْرِضَ لَنَا، فَلَمَّا رَجَعَ وَكُنَّا بِفَجِّ النَّاقَةِ، صَلَّى بِنَا الظُّهْرَ رَكْعَتَيْنِ، ثُمَّ سَلَّمَ، وَدَخَلَ فُسْطَاطَهُ، وَقَامَ الْقَوْمُ يُضِيفُونَ إِلَى رَكْعَتَيْهِ رَكْعَتَيْنِ أُخْرَيَيْنِ. قَالَ: فَقَالَ: قَبَّحَ اللهُ الْوُجُوهَ، فَوَاللهِ مَا أَصَابَتِ السُّنَّةَ، وَلَا قَبِلَتِ الرُّخْصَةَ، فَأَشْهَدُ لَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَقْوَامًا يَتَعَمَّقُونَ فِي الدِّينِ، يَمْرُقُونَ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ."],"takhrij":"حسن: رواه الإمام أحمد (12615) عن حسين بن محمد، حدثنا خلف، عن حفص، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب استحباب قصر الصلاة في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (12615).","chapter_en":"The recommendation of shortening the prayer during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":3,"content":{"translation":{"en":["Ḥafṣ narrated from Anas ibn Mālik that he said: We set out to Syria to (see) ‘Abd al-Malik, and we were forty men from the Anṣār so that he would assign us our stipends. When we returned and were at Fajj al-Nāqah, he led us in Ẓuhr as two rak‘ahs, then gave salām and entered his tent. The people then began adding two more rak‘ahs to his two. He said: “May Allah disfigure these faces! By Allah, they have neither followed the Sunnah nor accepted the concession.” And I testify that I heard the Messenger of Allah ﷺ say: “Indeed, some people go to extremes and delve too deeply in the religion; they will pass out of it just as an arrow passes through the game.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (12615)."},{"num":2867,"demo":false,"sanad":"","matn":["سَمِعَا أَنَسَ بْنَ مَالِكٍ يَقُولُ:  صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ بِالْمَدِينَةِ أَرْبَعًا، وَصَلَّيْتُ مَعَهُ الْعَصْرَ بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1089)، ومسلم في صلاة المسافرين (690) كلاهما من حديث سفيان، حدثنا محمد بن المنكدر وإبراهيم بن ميسرة سمعا أنس بن مالك يقول: فذكره. وله أسانيد أخرى في الصّحيحين.","grade":"متفق عليه","chapter_ar":"باب من أين يبدأ المسافر القصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1089), Muslim (690).","chapter_en":"From where the traveler begins shortening the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik said: I prayed Ẓuhr with the Messenger of Allah ﷺ in Madinah as four rak‘ahs, and I prayed ‘Aṣr with him at Dhū al-Ḥulayfah as two rak‘ahs."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1089)، ومسلم (690)."},{"num":2868,"demo":false,"sanad":"","matn":["عَنْ جُبَيْرِ بْنِ نُفَيْرٍ قَالَ:  خَرَجْتُ مَعَ شُرَحْبِيلَ بْنِ السِّمْطِ إِلَى قَرْيَةٍ عَلَى رَأْسِ سَبْعَةَ عَشَرَ، أَوْ ثَمَانِيَةَ عَشَرَ مِيلًا. فَصَلَّى رَكْعَتَيْنِ فَقُلْتُ لَهُ. فَقَالَ: رَأَيْتُ عُمَرَ صَلَّى بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ. فَقُلْتُ لَهُ. فَقَالَ: إِنَّمَا أَفْعَلُ كَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (692) من طرق عن عبدالرحمن بن مهدي، ثنا شعبة، عن يزيد بن خُمير، عن حبيب بن عبيد، عن حيير بن نفير فذكره.","grade":"صحيح","chapter_ar":"باب من أين يبدأ المسافر القصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (692).","chapter_en":"From where the traveler begins shortening the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":4,"content":{"translation":{"en":["Jubayr ibn Nufayr said: I went out with Shuraḥbīl ibn al-Samṭ to a village at a distance of seventeen or eighteen miles, and he prayed two rak‘ahs. I spoke to him about it, and he said: “I saw ‘Umar pray two rak‘ahs at Dhū al-Ḥulayfah, and I spoke to him about it. He said: ‘I only do as I saw the Messenger of Allah ﷺ do.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (692)."},{"num":2869,"demo":false,"sanad":"","matn":["عَنْ يَحْيَى بْنِ يَزِيدَ الْهُنَائِيِّ قَالَ:  سَأَلْتُ أَنَسَ بْنَ مَالِكٍ: عَنْ قَصْرِ الصَّلَاةِ، فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ مَسِيرَةَ ثَلَاثَةِ أَمْيَالٍ، - أَوْ ثَلَاثَةِ فَرَاسِخَ. شُعْبَةُ الشَّاكُّ - صَلَّى رَكْعَتَيْنِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (691) عن أبي بكر بن أبي شيبة وغيره، عن غُندَر (وهو محمد بن جعفر) عن شعبة، عن يحيى بن يزيد الهُنَائي فذكره، وهو في المصنف (2/332 تحقيق اللحام).","grade":"صحيح","chapter_ar":"باب من أين يبدأ المسافر القصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (691).","chapter_en":"From where the traveler begins shortening the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":4,"content":{"translation":{"en":["Yaḥyā ibn Yazīd al-Hanā’ī said: I asked Anas ibn Mālik about shortening the prayer. He said: When the Messenger of Allah ﷺ had gone out a distance of three miles—or three farsakhs (Shu‘bah was unsure)—he would pray two rak‘ahs."]},"buhuth":{"en":["This indicates the beginning of travel, not its endpoint. Most jurists have said that the distance of travel for which prayer is shortened is approximately 80 kilometers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (691)."},{"num":2870,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ يَقُولُ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ إِلَى مَكَّةَ، فَكَانَ يُصَلِّي رَكْعَتَيْنِ رَكْعَتَيْنِ حَتَّى رَجَعْنَا إِلَى الْمَدِينَةِ. قُلْتُ: كَمْ أَقَامَ بِمَكَّةَ؟ قَالَ: عَشْرًا."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1081)، ومسلم في صلاة المسافرين (693) كلاهما من حديث يحيى بن أبي إسحاق، قال سمعتُ أنساً يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب كم يقيم مقصِّراً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1081), Muslim (693).","chapter_en":"How long a traveler may remain while shortening (qasr)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":5,"content":{"translation":{"en":["Anas said: We traveled with the Prophet ﷺ from Madinah to Makkah, and he would pray two rak‘ahs each time (i.e., shorten) until we returned to Madinah. I asked: How long did he stay in Makkah? He said: Ten (days)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1081)، ومسلم (693)."},{"num":2871,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعَةَ عَشَرَ يَقْصُرُ، فَنَحْنُ إِذَا سَافَرْنَا تِسْعَةَ عَشَرَ قَصَرْنَا، وَإِنْ زِدْنَا أَتْمَمْنَا."],"takhrij":"صحيح: رواه البخاري في تقصير الصلاة (1080) من طريق أبي عوانة عن عاصم وحُصَين، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب كم يقيم مقصِّراً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Bukhārī (1080).","chapter_en":"How long a traveler may remain while shortening (qasr)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":5,"content":{"translation":{"en":["‘Abdullāh ibn ‘Abbās said: The Prophet ﷺ stayed nineteen (days) shortening the prayer. So when we travel and stay nineteen, we shorten; and if we stay longer, we complete (the prayer)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1080)."},{"num":2872,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: أَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَبُوكَ عِشْرِينَ يَوْمًا يَقْصُرُ الصَّلاَةَ."],"takhrij":"صحيح: رواه أبو داود (1235) عن الإمام أحمد-وهو في مسنده (14139) عن عبدالرزاق، أخبرنا معمر، عن يحيى بن أبي كثير، عن محمد ابن عبدالرحمن بن ثوبان، عن جابر فذكره. والحديث في مصنف عبدالرزاق (4335) ومن طريقه أخرجه ابن حبان في صحيحه (2752)، والبيهقي (5473).","grade":"صحيح","chapter_ar":"باب كم يقيم مقصِّراً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (1235), Aḥmad (14139), ‘Abd al-Razzāq (4335), and Ibn Ḥibbān in his Ṣaḥīḥ (2752).","chapter_en":"How long a traveler may remain while shortening (qasr)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ‘Abdullāh said: The Messenger of Allah ﷺ stayed in Tabūk for twenty days, shortening the prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9275],"tks":"صحيح: رواه أبو داود (1235) وأحمد (14139) وعبد الرزاق (4335) وابن حبان في صحيحه (2752)."},{"num":2873,"demo":false,"sanad":"","matn":["عَنْ مُوسَى بْنِ سَلَمَةَ الْهُذَلِيِّ قَالَ:  سَأَلْتُ ابْنَ عَبَّاسٍ: كَيْفَ أُصَلِّي إِذَا كُنْتُ بِمَكَّةَ، إِذَا لَمْ أُصَلِّ مَعَ الْإِمَامِ؟ فَقَالَ: رَكْعَتَيْنِ، سُنَّةَ أَبِي الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (688) من طرق عن محمد بن جعفر، قال: حدثنا شعبة قال: سمعتُ قتادة يحدِّث عن موسى بن سلمة الهُذَلي فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة بمكة للمسافر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (688).","chapter_en":"Prayer in Makkah for the traveler","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":6,"content":{"translation":{"en":["Mūsā ibn Salamah al-Hudhalī said: I asked Ibn ‘Abbās: How should I pray when I am in Makkah if I do not pray with the imām? He said: Two rak‘ahs—this is the Sunnah of Abū al-Qāsim ﷺ."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (688)."},{"num":2874,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن يَزِيدَ يَقُولُ: صلَّى بِنَا عُثْمَانُ بِمِنًى أَرْبَعَ رَكَعَاتٍ، فَقِيلَ ذَلِكَ لعبدالله بْنِ مَسْعُودٍ فَاسْتَرْجَعَ ثُمَّ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِنًى رَكْعَتَيْنِ، وَصَلَّيْتُ مَعَ أَبِي بَكْرٍ بِمِنًى رَكْعَتَيْنِ، وَصَلَّيْتُ مَعَ عُمَرَ بِمِنًى رَكْعَتَيْنِ، فَلَيْتَ حَظِّي مِنْ أَرْبَعِ رَكَعَاتٍ رَكْعَتَانِ مُتَقَبَّلَتَانِ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1084)، ومسلم في صلاة المسافرين (695) كلاهما عن قتيبة بن سعيد، حدَّثنا عبد الواحد، عن الأعمش، قال: حدَّثنا إبراهيم، قال: سمعت عبدالرحمن بن يزيد فذكره.","grade":"متفق عليه","chapter_ar":"باب قَصْر الصلاة في منى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1084), Muslim (695).","chapter_en":"Shortening the prayer in Minā","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":7,"content":{"translation":{"en":["‘Abd al-Raḥmān ibn Yazīd said: ‘Uthmān led us in Minā with four rak‘ahs. When this was mentioned to ‘Abdullāh ibn Mas‘ūd, he said “Innā lillāh…” and then said: I prayed two rak‘ahs with the Messenger of Allah ﷺ in Minā; and I prayed two with Abū Bakr in Minā; and I prayed two with ‘Umar in Minā. Would that my share out of four rak‘ahs were two accepted (rak‘ahs)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1084)، ومسلم (695)."},{"num":2875,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ:  صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِنًى رَكْعَتَيْنِ، وَأَبُو بَكْرٍ بَعْدَهُ، وَعُمَرُ بَعْدَ أَبِي بَكْرٍ، وَعُثْمَانُ صَدْرًا مِنْ خِلَافَتِهِ. ثُمَّ إِنَّ عُثْمَانَ صَلَّى بَعْدُ أَرْبَعًا، فَكَانَ ابْنُ عُمَرَ إِذَا صَلَّى مَعَ الْإِمَامِ صَلَّى أَرْبَعًا، وَإِذَا صَلَّاهَا وَحْدَهُ صَلَّى رَكْعَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1082)، ومسلم في صلاة المسافرين (694/17) كلاهما من حديث عبيدالله، عن نافع، عن ابن عمر فذكر الحديث، واللفظ لمسلم، وفي رواية عند مسلم من طريق حفص بن عاصم، عن ابن عمر، قال: صلَّى صلى الله عليه وسلم بمنًى صلاة المسافر، وأبو بكر وعمر، وعثمان ثماني سنين، أو قال: ست سنين.","grade":"متفق عليه","chapter_ar":"باب قَصْر الصلاة في منى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1082), Muslim (694).","chapter_en":"Shortening the prayer in Minā","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ prayed two rak‘ahs in Minā, and Abū Bakr after him, and ‘Umar after Abū Bakr, and ‘Uthmān at the beginning of his caliphate; then later ‘Uthmān prayed four. Ibn ‘Umar would pray four if he prayed with the imām, and if he prayed by himself he would pray two."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1082)، ومسلم (694)."},{"num":2876,"demo":false,"sanad":"","matn":["عَنْ أَبِي إِسْحَاقَ قَالَ: سَمِعْتُ حَارِثَةَ بْنَ وَهْبٍ يَقُولُ: صَلَّى بِنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -آمَنَ مَا كَان- بِمِنىً رَكْعَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في تفسير الصلاة (1083) من حديث شعبة، أنبانا أبو إسحاق، قال سمعت حارثة بن وهبٍ فذكره.","grade":"متفق عليه","chapter_ar":"باب قَصْر الصلاة في منى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1083), Muslim (696).","chapter_en":"Shortening the prayer in Minā","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":7,"content":{"translation":{"en":["Abū Isḥāq said: I heard Ḥārithah ibn Wahb say: The Prophet ﷺ led us in prayer at Minā with two rak‘ahs—at a time when it was safe."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1083) ومسلم (696)."},{"num":2877,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا عَجِلَ بِهِ السَّيْرُ يَجْمَعُ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (3) عن نافع، عن عبدالله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Mālik (3), Muslim (703), al-Bukhārī (1106).","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["‘Abdullāh ibn ‘Umar said: When travel became pressing for the Messenger of Allah ﷺ, he would combine Maghrib and ‘Ishā’."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (3) ومسلم (703)، والبخاري (1106)."},{"num":2878,"demo":false,"sanad":"","matn":["عَنْ كثير بْنِ قاروندا قَالَ: سَأَلْتُ سَالِمَ بْنَ عَبْدِ اللَّهِ عَنْ صَلاَةِ أَبِيهِ فِي السَّفَرِ، وَسَأَلْنَاهُ هَلْ كَانَ يَجْمَعُ بَيْنَ شيء مِنْ صَلاَتِهِ فِي سَفَرِهِ؟ فَذَكَرَ أَنَّ صَفِيَّةَ بِنْتَ أَبِي عُبَيْدٍ كَانَتْ تَحْتَهُ، فَكَتَبَتْ إِلَيْهِ وَهُوَ فِي زَرَّاعَةٍ لَهُ أنّي فِي آخِرِ يَوْمٍ مِنْ أَيَّامِ الدُّنْيَا، وَأَوَّلِ يَوْمٍ مِنَ الآخِرَةِ، فَرَكِبَ، فَأَسْرَعَ السَّيْرَ إِلَيْهَا حَتَّى إِذَا حَانَتْ صَلاَةُ الظُّهْرِ، قَالَ لَهُ الْمُؤَذِّنُ: الصَّلاَةَ يَا أَبَا عَبْدِ الرَّحْمَنِ، فَلَمْ يَلْتَفِتْ حَتَّى إِذَا كَانَ بَيْنَ الصَّلاَتَيْنِ، نَزَلَ، فَقَالَ: أقمْ، فَإِذَا سلّمتُ فَأَقِمْ فَصَلَّى، ثُمَّ رَكِبَ حَتَّى إِذَا غَابَتِ الشَّمْسُ، قَالَ لَهُ الْمُؤَذِّنُ: الصَّلاَةَ، فَقَالَ: كَفِعْلِكَ فِي صَلاَةِ الظُّهْرِ وَالْعَصْرِ، ثُمَّ سَارَ حَتَّى إِذَا اشْتَبَكَتِ النُّجُومُ نَزَلَ، ثُمَّ قَالَ لِلْمُؤَذِّنِ: أقمْ فَإِذَا سلّمتُ فأقمِْ فَصَلَّى، ثُمَّ انْصَرَفَ، فَالْتَفَتَ إِلَيْنَا فَقَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِذَا حضرَ أَحَدَكُمُ الأَمْرُ الَّذِي يَخَافُ فَوْتَهُ فلْيصلّ هَذِهِ الصَّلاَةَ يَعْنِي الجمع بَيْنَ الصَّلاَتَيْنِ."],"takhrij":"حسن: رواه النسائي (588)، والطبراني في الكبير (12/319-320) كلاهما من حديث يزيد بن زريع قال حدثنا كثير بن قاروندا قال: فذكره.","grade":"حسن","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Nasā’ī (588) and al-Ṭabarānī in al-Kabīr (12/319–320).","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["Kathīr ibn Qārūndā said: I asked Sālim ibn ‘Abdillāh about his father’s prayer while traveling, and we asked him whether he used to combine any of his prayers on a journey. He mentioned that Ṣafiyyah bint Abī ‘Ubayd was his wife, and she wrote to him while he was at one of his farms: “I am at the last day of the days of this world, and the first day of the Hereafter.” So he rode out and hastened to her. When the time for Ẓuhr came, the mu’adhdhin said: “The prayer, O Abū ‘Abd al-Raḥmān,” but he did not stop until the time between the two prayers (Ẓuhr and ‘Aṣr). Then he dismounted and said: “Establish (the prayer). When I give salām, then establish (the next).” So he prayed, then rode on. When the sun set, the mu’adhdhin said: “The prayer,” and he said: “Do as you did for Ẓuhr and ‘Aṣr.” He continued until the stars were interwoven, then he dismounted and said to the mu’adhdhin: “Establish (the prayer). When I give salām, then establish (the next).” So he prayed, then departed. He then turned to us and said: The Messenger of Allah ﷺ said: “When an urgent matter comes to one of you that he fears he will miss, then let him perform this prayer”—meaning combining the two prayers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (588)، والطبراني في الكبير (12/319-320)."},{"num":2879,"demo":false,"sanad":"","matn":["عن أنس: أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْمَعُ بَيْنَ هَاتَيْنِ الصَّلَاتَيْنِ فِي السَّفَرِ يَعْنِي المغْرِبَ وَالْعِشَاءَ."],"takhrij":"صحيح: رواه البخاري في تقصير الصلاة (1110) عن إسحاق، حدثنا عبد الصمد بن عبد الوارث، حدثنا حرب، حدثنا يحيى، قال: حدثني حفص بن عبيد الله بن أنس أن أنسا حدّثه فذكره.","grade":"صحيح","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Bukhārī (1110).","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Mālik said: The Messenger of Allah ﷺ used to combine these two prayers while traveling—meaning Maghrib and ‘Ishā’."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1110)."},{"num":2880,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا ارْتَحَلَ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أخَّر الظُّهْرَ إِلَى وَقْتِ الْعَصْرِ، ثُمَّ يجمع بَيْنَهُمَا. وَإِذَا زَاغَتِ صَلَّى الظُّهْرَ ثُمَّ رَكِبَ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1112)، ومسلم في صلاة المسافرين (704) كلاهما عن قتيبه بن سعيد عن المفضَّل بن فَضالة، عن عُقيل، عن ابن شهاب، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1112) and Muslim (704). In a narration in Muslim: When he intended to combine the two prayers during travel, he would delay Ẓuhr until the beginning of the time for ‘Aṣr, then combine them.","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Mālik said: When the Prophet ﷺ set out to travel before the sun passed its zenith, he would delay Ẓuhr until the time of ‘Aṣr, then combine the two. And if the sun had already passed its zenith, he would pray Ẓuhr and then ride."]},"buhuth":{"en":["Also in Muslim: If travel became urgent for him, he would delay Ẓuhr until the beginning of ‘Aṣr and combine them; and he would delay Maghrib until he could combine it with ‘Ishā’ when the twilight (al-shafaq) had disappeared."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1112)، ومسلم (704)، وفي رواية عند مسلم: إذا أراد أن يجمع بين الصلاتين في السفر، أخر الظهر حتى يدخل أول وقت العصر، ثم يجمع بينهما."},{"num":2881,"demo":false,"sanad":"","matn":["عن مُعَاذِ بن جَبَلٍ أَخْبَرَهُ أَنَّهُمْ، خَرَجُوا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ تَبُوكَ فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ الظُّهْرِ وَالْعَصْرِ، وَالْمَغْرِبِ وَالْعِشَاءِ، - قَالَ: - فَأَخَّرَ الصَّلاَةَ يَوْمًا. ثُمَّ خَرَجَ فَصَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا، ثُمَّ دَخَلَ. ثُمَّ خَرَجَ فَصَلَّى الْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا."],"takhrij":"صحيح: رواه مالك في قصر الصلاة في السفر (2) عن أبي الزبير المكي، عن أبي الطفيل عامر بن واثلة، عن معاذ بن جبل فذكر في حديث طويل سيأتي في كتاب المعجزات وأبو الزبير مدلس، ولكنه صرَّح بالتحديث عند مسلم (706/53) فإنه رواه من طريق قُرَّة بن خالد، حدثنا أبو الزبير، حدثنا عامر ابن واثلة، حدثنا معاذ بن جبل فذكره.","grade":"صحيح","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (2) and Muslim (53/706). And in Abū Dāwūd (1208) from Mu‘ādh: If the sun passed its zenith before he set out in the Tabūk expedition, he combined Ẓuhr and ‘Aṣr; and if he set out before it passed the zenith, he delayed Ẓuhr until he stopped for ‘Aṣr, then combined them. He did similarly with Maghrib: if the sun set before he set out, he combined Maghrib and ‘Ishā’; and if he set out before sunset, he delayed Maghrib until he stopped for ‘Ishā’, then combined them. This chain is ḥasan.","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["Mu‘ādh ibn Jabal said: They went out with the Messenger of Allah ﷺ to Tabūk, and the Messenger of Allah ﷺ used to combine Ẓuhr with ‘Aṣr, and Maghrib with ‘Ishā’. He said: One day he delayed the prayer. Then he came out and prayed Ẓuhr and ‘Aṣr together, then went back in. Then he came out and prayed Maghrib and ‘Ishā’ together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (2) و مسلم (706/53). وعند أبي داود (1208) عن معاذ بن جبل: (( أن رسول الله ﷺ كان في غزوة تبوك إذا زاغت الشمس قبل أن يرتحل جمع الظهر والعصر، وإن ارتحل قبل أن تزيغ الشمس أخر الظهر حتى ينزل للعصر، وفي المغرب مثل ذلك. إن غابت الشمس قبل أن يرتحل جمع بين المغرب والعشاء، وإن يرتحل قبل أن تغيب الشمس أخر المغرب حتى ينزل للعشاء، ثم جمع بينهما)). وهذا إسناد حسن."},{"num":2882,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَمَعَ بَيْنَ الصَّلَاةِ فِي سَفْرَةٍ سَافَرَهَا فِي غَزْوَةِ تَبُوكَ، فَجَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ، وَالْمَغْرِبِ وَالْعِشَاءِ. قَالَ سَعِيدٌ: فَقُلْتُ لِابْنِ عَبَّاسٍ: مَا حَمَلَهُ عَلَى ذَلِكَ؟ قَالَ: أَرَادَ أَنْ لَا يُحْرِجَ أُمَّتَهُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (705/51) من طريق قرة، عن أبي الزبير، حدثنا سعيد بن جبير، حدثنا ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (51/705).","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Abbās said: The Messenger of Allah ﷺ combined prayers on a journey he traveled during the expedition of Tabūk: he combined Ẓuhr with ‘Aṣr, and Maghrib with ‘Ishā’. Sa‘īd said: I asked Ibn ‘Abbās, “What made him do that?” He replied: He wanted not to put his Ummah in hardship."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (705/51)."},{"num":2883,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ الصَّلاتَيْنِ فِي السَّفَرِ: الْمَغْرِبِ وَالْعِشَاءِ، وَالظُّهْرِ وَالْعَصْرِ."],"takhrij":"حسن: رواه أحمد (1874) عن محمد بن فضيل، عن يزيد، عن عطاء (هو ابن أبي رباح) عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Aḥmad (1874), (3288), (3397).","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["‘Abdullāh ibn ‘Abbās said: The Messenger of Allah ﷺ used to combine the two prayers while traveling: Maghrib with ‘Ishā’, and Ẓuhr with ‘Aṣr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1874، 3288، 3397)."},{"num":2884,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: جَمَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الظُّهْرِ وَالْعَصْرِ، وَبَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، وَأَخَّرَ الْمَغْرِبَ، وَعَجَّلَ الْعِشَاءَ فَصَلَّاهُمَا جَمِيعًا."],"takhrij":"حسن: رواه الطبراني في الأوسط (7990) عن موسى بن هارون، قال: حدثنا محمد بن عبد الواهب الحارثي، قال: حدثنا أبو شهاب الحناط، عن عوف، عن أبي نَضْرة، عن أبي سعيد فذكره.","grade":"حسن","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: al-Ṭabarānī in al-Awsaṭ (7990) and al-Bazzār (Kashf al-Astār 686).","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["Abū Sa‘īd said: The Messenger of Allah ﷺ combined Ẓuhr with ‘Aṣr, and Maghrib with ‘Ishā’. He delayed Maghrib and hastened ‘Ishā’, and prayed them together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (7990) والبزار - كشف الأستار (686)."},{"num":2885,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْمَعُ بَيْنَ الصَّلاتَيْنِ فِي السَّفَرِ."],"takhrij":"حسن: رواه ابن أبي شيبة (9430) وعنه أبو يعلى المقصد العلي (352)، والبزار في مسنده (5/414)، والطبراني في الكبير كلهم من طريق عيسى، نا ابن أبي ليلى، عن أبي قيس الأودي، عن هزيل، عن ابن مسعود فذكره.","grade":"حسن","chapter_ar":"باب الجمع بين الصلاتين في السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Ibn Abī Shaybah (2/458), Abū Ya‘lā (al-Maqṣad al-‘Alī 352), and al-Bazzār (5/414).","chapter_en":"Combining two prayers during travel","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":8,"content":{"translation":{"en":["‘Abdullāh ibn Mas‘ūd said: The Messenger of Allah ﷺ used to combine two prayers while traveling."]},"buhuth":{"en":["Fiqh of the chapter:","From the hadiths of this chapter it is understood that combining two prayers during travel is permissible, whether one is traveling on the move or has stopped, because it is a concession among the concessions of travel. However, it is better for the one who is staying in a place (not moving at that time) not to combine, because the Prophet ﷺ did not combine in Minā while he was staying there."]}},"tuhfa":{},"voc":["mujamkabir",9840],"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة (9430) وأبو يعلى في المقصد العلي (352)، والبزار في مسنده (5/414)."},{"num":2886,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عَبَّاسٍ أنَّه قَالَ: صلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ وَالْعَصْرَ جَمِيعًا، وَالْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا فِي غَيْرِ خَوْفٍ وَلَا سَفَرٍ.","قَالَ مَالِكٌ: أُرَى ذَلِكَ كَانَ فِي مَطَرٍ."],"takhrij":"متفق عليه: رواه مالك في قصر الصّلاة في السفر (4) عن أبي الزبير المكي، عن سعيد بن جبير، عن عبدالله بن عباس.","grade":"متفق عليه","chapter_ar":"باب الجمع بين الصلاتين في الحضر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Mālik (4), Muslim (705), and al-Bukhārī (543). In Muslim (56/705) it states that the Prophet ﷺ prayed in Madīnah seven and eight (rak‘ahs): Ẓuhr with ‘Aṣr, and Maghrib with ‘Ishā’.","chapter_en":"Combining two prayers while resident (not traveling)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":9,"content":{"translation":{"en":["‘Abdullāh ibn ‘Abbās said: The Messenger of Allah ﷺ prayed Ẓuhr and ‘Aṣr together, and Maghrib and ‘Ishā’ together, without fear and without travel. Mālik said: I think that was due to rain."]},"buhuth":{"en":["Mālik said: I think it was in rain—this is what he said—may Allah have mercy on him. However, in a narration in Muslim (54/705), Ibn ‘Abbās explicitly stated that it was without fear and without rain.","Scholars have said this should not be taken as a habitual practice.","And if combining while resident is allowed without fear and without rain, then illness has even more reason to allow combining—supported by the instruction to a woman with istiḥāḍah (irregular bleeding) to combine prayers, and istiḥāḍah is a type of illness."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4) ومسلم (705) والبخاري (543)، ومسلم (56/705) وفيه: أن النبي ﷺ صلى بالمدينة سبعا وثمانيا - الظهر والعصر، والمغرب والعشاء."},{"num":2887,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ، قَالَ: : مَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى صَلَاةً بِغَيْرِ مِيقَاتِهَا، إِلَّا صَلَاتَيْنِ، جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، ، وَصَلَّى الْفَجْرَ قَبْلَ مِيقَاتِهَا."],"takhrij":"متفق عليه: رواه البخاري في الحج (1682)، ومسلم في الحج (1289) كلاهما من طريق الأعمش قال: حدثني عُمارة، عن عبدالرحمن بن يزيد، عن عبدالله بن مسعود فذكره. والرواية الثانية ذكرها مسلم.","grade":"متفق عليه","chapter_ar":"باب من قال: إن الجمع في المدينة من غير عُذْر كان جمعاً صورياً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1682) and Muslim (1289).","chapter_en":"Those who said that combining in Madīnah without an excuse was only “apparent” combining (jam‘ ṣūrī)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":10,"content":{"translation":{"en":["‘Abdullāh ibn Mas‘ūd said: I did not see the Prophet ﷺ pray any prayer outside its prescribed time except two prayers: he combined Maghrib and ‘Ishā’, and he prayed Fajr before its (usual) time. In another narration: that was at Jam‘—meaning Muzdalifah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1682)، ومسلم (1289)."},{"num":2888,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا نَزَلَ مَنْزِلاً لَمْ يَرْتَحِلْ حَتَّى يُصَلِّيَ الظُّهْرَ. فَقَالَ لَهُ رَجُلٌ: وَإِنْ كَانَ بِنِصْفِ النَّهَارِ؟ قَالَ: وَإِنْ كَانَ بِنِصْفِ النَّهَارِ."],"takhrij":"حسن: رواه أبو داود (1205)، والنسائي (498) كلاهما من حديث يحيى بن سعيد، عن شعبة قال: حدثني حمزة العائذي قال: سمعت أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تعجيل الظهر في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Abū Dāwūd (1205), al-Nasā’ī (498). Authenticated by Ibn Khuzaymah (975); also narrated by Aḥmad (12204).","chapter_en":"What has been reported about performing Ẓuhr early while traveling","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Mālik said: When the Messenger of Allah ﷺ stopped at a place (during travel), he would not set out again until he prayed Ẓuhr. A man asked him: “Even if it is at midday?” He replied: “Even if it is at midday.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1798],"tks":"حسن: رواه أبو داود (1205)، والنسائي (498)، وصححه ابن خزيمة (975)، وأحمد (12204)."},{"num":2889,"demo":false,"sanad":"","matn":["عن عِيسَى بن حفص بن عَاصِمٍ بن عُمَرَ بن الْخَطَّابِ، عَنْ أَبِيهِ، قَالَ:  صَحِبْتُ ابْنَ عُمَرَ فِي طَرِيقِ مَكَّةَ، قَالَ: فَصَلَّى لَنَا الظُّهْرَ رَكْعَتَيْنِ، ثُمَّ أَقْبَلَ وَأَقْبَلْنَا مَعَهُ حَتَّى جَاءَ رَحْلَهُ وَجَلَسَ وَجَلَسْنَا مَعَهُ. فَحَانَتْ مِنْهُ الْتِفَاتَةٌ نَحْوَ حَيْثُ صَلَّى، فَرَأَى نَاسًا قِيَامًا. فَقَالَ: مَا يَصْنَعُ هَؤُلَاءِ؟ قُلْتُ: يُسَبِّحُونَ، قَالَ: لَوْ كُنْتُ مُسَبِّحًا أَتْمَمْتُ صَلَاتِي. يَا ابْنَ أَخِي، إِنِّي صَحِبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ. فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ. وَصَحِبْتُ أَبَا بَكْرٍ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ، وَصَحِبْتُ عُمَرَ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ، ثُمَّ صَحِبْتُ عُثْمَانَ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللَّهُ. وَقَدْ قَالَ اللَّهُ: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1102)، ومسلم في صلاة المسافرين (689) كلاهما من حديث عيسى بن حفص به،","grade":"متفق عليه","chapter_ar":"باب ترك التطوع في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1102) and Muslim (689), wording from Muslim.","chapter_en":"Leaving the (regular) voluntary prayers while traveling","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":12,"content":{"translation":{"en":["‘Īsā ibn Ḥafṣ ibn ‘Āṣim ibn ‘Umar ibn al-Khaṭṭāb, from his father, said: I accompanied Ibn ‘Umar on the road to Makkah. He prayed Ẓuhr for us as two rak‘ahs, then turned and we turned with him until he reached his lodging and sat, and we sat with him. Then he glanced toward the place where he had prayed and saw some people standing (in prayer). He asked: “What are these people doing?” I said: “They are praying voluntary prayers (yusabbiḥūn).” He said: “If I were going to pray voluntary prayers, I would have completed my (obligatory) prayer (i.e., prayed it full). O son of my brother, I accompanied the Messenger of Allah ﷺ in travel and he did not pray more than two (rak‘ahs) until Allah took him. I accompanied Abū Bakr and he did not pray more than two until Allah took him. I accompanied ‘Umar and he did not pray more than two until Allah took him. Then I accompanied ‘Uthmān and he did not pray more than two until Allah took him. And Allah the Exalted has said: “Indeed, in the Messenger of Allah you have an excellent example.” [al-Aḥzāb: 21].”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1102)، ومسلم (689) واللفظ لمسلم."},{"num":2890,"demo":false,"sanad":"","matn":["عَنْ عَمْرو بن دينار قَالَ سَمِعْتُ أبَا الشَّعْثَاءِ جَابِرًا قَالَ سَمِعْتُ ابْنَ عَبَّاسٍ قَالَ: صَلَّيْتُ مَعَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَمَانِيًا جَمِيعًا وَسَبْعًا جَمِيعًا. قُلْتُ يَا أَبَا الشَّعْثَاءِ أَظُنُّهُ أَخَّرَ الظُّهْرَ وَعَجَّلَ الْعَصْرَ، وَعَجَّلَ الْعِشَاءَ وَأَخَّرَ الْمَغْرِبَ. قَالَ: وَأَنَا أَظُنُّهُ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1174)، ومسلم في صلاة المسافرين (705: 55) كلاهما من حديث سفيان بن عيينة، عن عمرو بن دينار قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ترك التطوع في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1174) and Muslim (55/705).","chapter_en":"Leaving the (regular) voluntary prayers while traveling","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":12,"content":{"translation":{"en":["‘Amr ibn Dīnār said: I heard Abū al-Sha‘thā’ Jābir say: I heard Ibn ‘Abbās say: I prayed with the Messenger of Allah ﷺ eight (rak‘ahs) together and seven (rak‘ahs) together. I said: “O Abū al-Sha‘thā’, I think he delayed Ẓuhr and prayed ‘Aṣr early, and he prayed ‘Ishā’ early and delayed Maghrib.” He replied: “And I think so too.”"]},"buhuth":{"en":["Meaning of the hadith: that the Prophet ﷺ did not pray any of the regular sunnah-rātibah prayers before the (combined) obligatory prayer nor after it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1174)، ومسلم (705: 55)."},{"num":2891,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ قَالَ: كُنَّا فِي سَفَرٍ، وَمَعَنَا ابْنُ عُمَرَ فَسَأَلْتُهُ، فَقَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُسَبِّحُ فِي السَّفَرِ قَبْلَ الصَّلَاةِ وَلَا بَعْدَهَا."],"takhrij":"صحيح: رواه الإمام أحمد (5012) عن يزيد بن هارون قال: أخبرنا ابن أبي ذئب، عن عثمان بن عبدالله بن سراقة، فذكر الحديث، وإسناده صحيح.-","grade":"صحيح","chapter_ar":"باب ترك التطوع في السفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Aḥmad (5012).","chapter_en":"Leaving the (regular) voluntary prayers while traveling","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":12,"content":{"translation":{"en":["‘Uthmān ibn ‘Abdullāh ibn Surāqah said: We were traveling, and Ibn ‘Umar was with us. I asked him and he said: I saw the Messenger of Allah ﷺ not pray voluntary prayers (yusabbiḥ) in travel—neither before the (obligatory) prayer nor after it."]},"buhuth":{"en":["What is meant by “tasbīḥ” here is the regular sunnah-rātibah prayers. Otherwise, it is authentically reported that he ﷺ would pray voluntary prayers on the back of his mount wherever it was facing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (5012)."},{"num":2892,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عَامِرٍ بن رَبِيعَةَ، عَنْ أَبِيهِ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ.","وفي رواية: رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم وَهْوَ عَلَى راحلته يُسَبِّحُ، يُومِئُ بِرَأْسِهِ قِبَلَ أَىِّ وَجْهٍ تَوَجَّهَ، وَلَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَصْنَعُ ذَلِكَ فِي الصَّلاَةِ الْمَكْتُوبَةِ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1093، 1097، 1104) واللفظ له، ومسلم في صلاة المسافرين (701) كلاهما من حديث الزهري، عن عبدالله بن عامر بن ربيعه به قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1104, 1097, 1093) with his wording, and Muslim (701).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["‘Abdullāh ibn ‘Āmir ibn Rabī‘ah reported from his father: I saw the Prophet ﷺ praying on his mount wherever it turned with him. In another narration: I saw the Messenger of Allah ﷺ on his mount praying voluntary prayers (yusabbiḥ), signaling with his head, facing whatever direction it turned; and the Messenger of Allah ﷺ did not do that for the obligatory prayer."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1104، 1097، 1093) واللفظ له، ومسلم (701)."},{"num":2893,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَبِّح عَلَى الرَّاحِلَةِ قِبَل أيِّ وَجْهٍ تَوَجَّهَ، وَيُوتِرُ عَلَيْهَا، غَيْرَ أنَّه لَا يُصلِّي عَلَيْهَا الْمَكْتُوبَةَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (700/39) من حديث ابن وهب، أخبرني يونس، عن ابن شهاب، عن سالم بن عبدالله، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (39/700).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ used to pray voluntary prayers on his mount facing whatever direction it turned, and he would also pray Witr on it—except that he would not pray the obligatory prayer on it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (700/39)."},{"num":2894,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ، فَإِذَا أَرَادَ الْفَرِيضَةَ نَزَلَ فَاسْتَقْبَلَ الْقِبْلَةَ."],"takhrij":"صحيح: رواه البخاري في كتاب الصلاة (400) عن مسلم بن إبراهيم، حدثنا هشام (الدستوائي) قال: حدثنا يحيى بن أبي كثير، عن محمد بن عبدالرحمن، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Bukhārī (400).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ‘Abdullāh said: The Messenger of Allah ﷺ used to pray on his mount wherever it faced, but when he intended the obligatory prayer, he would dismount and face the qiblah."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (400)."},{"num":2895,"demo":false,"sanad":"","matn":["عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ، أَنَّهُ سَأَلَ عَائِشَةَ: رَضِيَ اللَّهُ عَنْهَا هَلْ رُخِّصَ لِلنِّسَاءِ أَنْ يُصَلِّينَ عَلَى الدَّوَابِّ؟ قَالَتْ: لَمْ يُرَخَّصْ لَهُنَّ فِي ذَلِكَ فِي شِدَّةٍ، وَلاَ رَخَاءٍ. قَالَ مُحَمَّدٌ هَذَا فِي الْمَكْتُوبَةِ."],"takhrij":"حسن: رواه أبو داود (1228) عن محمود بن خالد، حدثنا محمد بن شُعيب، عن النعمان بن المنذر، عن عطاء بن أبي رباح، فذكره.","grade":"حسن","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Abū Dāwūd (1228). Muḥammad ibn Shu‘ayb said: “This is regarding the obligatory prayer.”","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["‘Aṭā’ ibn Abī Rabāḥ reported that he asked ‘Ā’ishah: “Were women granted a concession to pray on riding animals?” She replied: “They were not granted a concession for that—neither in hardship nor in ease.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1228). قال محمد بن شعيب: هذا في المكتوبة."},{"num":2896,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن دِينَارٍ قَالَ: كَانَ عبدالله بْنُ عُمَرَ يُصَلِّي فِي السَّفَرِ عَلَى رَاحِلَتِهِ أَيْنَمَا توجَّهت يُومِئُ، وَذَكَرَ عبدالله أنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُهُ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1096) عن موسى بن إسماعيل، عن عبد العزيز بن مسلم، قال: حدثنا عبدالله بن دينار فذكره.","grade":"متفق عليه","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1096) and Muslim (37/700).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["‘Abdullāh ibn Dīnār said: ‘Abdullāh ibn ‘Umar used to pray during travel on his mount wherever it headed, gesturing (by nodding). And ‘Abdullāh (ibn ‘Umar) mentioned that the Prophet ﷺ used to do that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1096)، ومسلم (37/700)."},{"num":2897,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي وَهُوَ عَلَى حِمَارٍ، وَهُوَ مُتَوَجِّهٌ إِلَى خَيْبَرَ."],"takhrij":"صحيح: رواه مالك في قصر الصلاة (25) عن عمرو بن يحيى المازني، عن أبي الحُباب سعيد بن يسار، عن عبدالله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Mālik (25) and Muslim (35/700).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["‘Abdullāh ibn ‘Umar said: I saw the Messenger of Allah ﷺ praying while on a donkey, heading toward Khaybar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (25) ومسلم (35/700)."},{"num":2898,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي - وَهُوَ مُقْبِلٌ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ - عَلَى رَاحِلَتِهِ حَيْثُ كَانَ وَجْهُهُ. قَالَ: وَفِيهِ نَزَلَتْ: ﴿فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (700/33) من حديث عبد الملك بن أبي سليمان، قال: حدثنا سعيد بن جبير، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (33/700).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ would pray while traveling back from Makkah to Madīnah on his mount, facing whichever direction it was facing. He said: Concerning this, the verse was revealed: “Wherever you turn, there is the Face of Allah.” [al-Baqarah: 115]."]}},"tuhfa":{},"full":1,"rep":[11914],"tks":"صحيح: رواه مسلم (700/33)."},{"num":2899,"demo":false,"sanad":"","matn":["عن أنس بْنِ سِيرِينَ قَالَ: اسْتَقْبَلْنَا أَنَسًا حِينَ قَدِمَ مِنَ الشَّأْمِ، فَلَقِينَاهُ بِعَيْنِ التَّمْرِ، فَرَأَيْتُهُ يُصَلِّي عَلَى حِمَارٍ وَوَجْهُهُ مِنْ ذَا الْجَانِبِ، يَعْنِي عَنْ يَسَارِ الْقِبْلَةِ. فَقُلْتُ: رَأَيْتُكَ تُصَلِّي لِغَيْرِ الْقِبْلَةِ. فَقَالَ: لَوْلاَ أَنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَهُ لَمْ أَفْعَلْهُ."],"takhrij":"متفق عليه: رواه البخاري في تقصير الصلاة (1100)، ومسلم في صلاة المسافرين (702) كلاهما من حديث همَّام، حدثنا أنس بن سيرين فذكره واللفظ للبخاري، ولفظ مسلم سواء إلاَّ أنَّه قال فيه: حين قدم الشامَ .","grade":"متفق عليه","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1100) and Muslim (702).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Sīrīn said: We went to meet Anas when he arrived from Shām, and we met him at ‘Ayn al-Tamr. I saw him praying on a donkey, facing this side—meaning to the left of the qiblah. I said: “I saw you praying not toward the qiblah.” He said: “Had I not seen the Messenger of Allah ﷺ do it, I would not have done it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1100)، ومسلم (702)."},{"num":2900,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَافَرَ، فَأَرَادَ أَنْ يَتَطَوَّعَ اسْتَقْبَلَ بِنَاقَتِهِ الْقِبْلَةَ فَكَبَّرَ، ثُمَّ صَلَّى حَيْثُ وَجَّهَهُ رِكَابُهُ."],"takhrij":"حسن: رواه أبو داود (1225) عن مسدَّد، حدثنا رِبْعيُّ بن عبدالله بن الجارود، حدثني عمرو بن أبي الحجاج، حدثني الجارود بن أبي سبْرة، حدثني أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب لا تؤدى الفريضة على الراحلة دون النافلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Abū Dāwūd (1225) and Aḥmad (13109).","chapter_en":"The obligatory prayer is not performed on the riding mount (unlike voluntary prayers)","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Mālik said: When the Messenger of Allah ﷺ traveled and wanted to perform a voluntary prayer, he would face the qiblah with his she-camel, say the takbīr, then pray in whichever direction his mount turned."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1225) والإمام أحمد (13109)."},{"num":2901,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، - قَالَ: - بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ، قَالَ: فَجِئْتُ وَهُوَ يُصَلِّي عَلَى رَاحِلَتِهِ نَحْوَ الْمَشْرِقِ، وَالسُّجُودُ أَخْفَضُ مِنَ الرُّكُوعِ."],"takhrij":"حسن: رواه أبو داود (1227)، والترمذي (351) كلاهما من حديث وكيع، عن سفيان، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب أن السجدتين من المتنفل على الراحلة تكون في الإيماء أخفض من الركوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Abū Dāwūd (1227), al-Tirmidhī (351), Ibn Khuzaymah (1270), and from him Ibn Ḥibbān (2523).","chapter_en":"For the one praying voluntary prayers on a riding mount, the two prostrations are done by gesture (īmā’) and are lower than the bowing","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة المسافر","group_en":"Combined chapters: The prayer of the traveler","part_no":9,"group_no":18,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn ‘Abdullāh said: The Messenger of Allah ﷺ sent me on an errand. I came back and found him praying on his mount toward the east, and his prostration was lower than his bowing (i.e., by gesture)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1227)، والترمذي (351)، وابن خزيمة (1270) وعنه ابن حبان (2523)."},{"num":2902,"demo":false,"sanad":"","matn":["عَنِ الزُّهْرِيِّ قَالَ: أَخْبَرَنِي سَالِمٌ أنَّ عبدالله بْنَ عُمَرَ قَالَ: غَزَوْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِبل نجدٍ، فَوَازَيْنَا العدوَّ فَصَافَفْنَا لَهُمْ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي لَنَا، فَقَامَتْ طَائِفَةٌ مَعَهُ تُصلِّي، وَأَقْبَلَتْ طَائِفَةٌ عَلَى العدوِّ، وَرَكَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَنْ مَعَهُ، وَسَجَدَ سَجْدَتَيْنِ، ثُمَّ سلَّم. فَقَامَ كُلُّ وَاحِدٍ مِنْهُمْ فَرَكَعَ لِنَفْسِهِ رَكْعَةً، وَسَجَدَ سَجْدَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الخوف (942) وفي المغازي bukhari(4133)، ومسلم في صلاة المسافرين (839) كلاهما من حديث الزهري واللفظ للبخاري. ولم يذكر مسلم أنَّ ذلك كان في غزوةٍ قبل نجدٍ.","grade":"متفق عليه","chapter_ar":"باب ما جاء أنَّ الإمامَ يصلّي لكلِّ طائفة ركعة ثم يسلّم وتقضي كلُّ طائفةٍ ركعةً لنفسها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (942, 4133) and Muslim (839).","chapter_en":"The imam prays one rak‘ah with each group, then gives salām, and each group completes one rak‘ah on its own","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":1,"content":{"translation":{"en":["‘Abdullāh ibn ‘Umar said: I went on an expedition with the Messenger of Allah ﷺ toward Najd. We faced the enemy and lined up against them. The Messenger of Allah ﷺ stood to lead us in prayer. One group stood and prayed with him, while another group faced the enemy. The Messenger of Allah ﷺ bowed with those who were with him and prostrated twice, then gave salām. Then each of them stood and prayed one rak‘ah on his own and prostrated twice."]},"intro_majmu":{"ar":["قال اللّٰه تعالى:","﴿وَإِذَا ضَرَبْتُمْ فِي الْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمُ الَّذِينَ كَفَرُوا ۚ إِنَّ الْكَافِرِينَ كَانُوا لَكُمْ عَدُوًّا مُبِينًا﴾","﴿وَإِذَا كُنْتَ فِيهِمْ فَأَقَمْتَ لَهُمُ الصَّلَاةَ فَلْتَقُمْ طَائِفَةٌ مِنْهُمْ مَعَكَ وَلْيَأْخُذُوا أَسْلِحَتَهُمْ ۖ فَإِذَا سَجَدُوا فَلْيَكُونُوا مِنْ وَرَائِكُمْ وَلْتَأْتِ طَائِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَكَ وَلْيَأْخُذُوا حِذْرَهُمْ وَأَسْلِحَتَهُمْ ۗ وَدَّ الَّذِينَ كَفَرُوا لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُمْ مَيْلَةً وَاحِدَةً ۚ وَلَا جُنَاحَ عَلَيْكُمْ إِنْ كَانَ بِكُمْ أَذًى مِنْ مَطَرٍ أَوْ كُنْتُمْ مَرْضَىٰ أَنْ تَضَعُوا أَسْلِحَتَكُمْ ۖ وَخُذُوا حِذْرَكُمْ ۗ إِنَّ اللَّهَ أَعَدَّ لِلْكَافِرِينَ عَذَابًا مُهِينًا﴾","[سورة النساء: ١٠١-١٠٢].","قال الخطابي في معالم السنن:"," صلاة الخوف أنواع، وقد صلاها رسول اللّٰه ﷺ في أيام مختلفة، وعلى أشكال متباينة، يتوخَّى في كلِّ ما هو أحوط للصلاة، وأبلغ في الحراسة، وهي على اختلاف صورها مُؤتَلِفَة في المعاني.","وقال ابن حِبَّان:"," هذه الأخبار ليس بينها تضادٌّ ولا تَهَاتُر، ولكنّ المصطفى ﷺ صلَّى صلاة الخوف مراراً في أحوال مختلفة بأنواع متباينة، على حسب ما ذكرناها، أراد به تعليم أُمَّتِهِ صلاةَ الخوف، أنَّه مباح لهم أن يُصلُّوا أيَّ نوع من الأنواع التسعة التي صلاها رسول اللّٰه ﷺ في الخوف على حسب الحاجة إليها، والمرءُ مباح له أن يُصلِّي ما شاء عند الخوف من هذه الأنواع التي ذكرناها، إذ هي من اختلاف المباح من غير أن يكون بينها تضادٌّ، أو تَهَاتُر (١٤٥/٧)."],"en":["Allah Most High said:","(4:101) “When you travel through the land, there is no blame upon you for shortening the prayer if you fear that those who disbelieve may harm you. Indeed, the disbelievers are to you a clear enemy.”","(4:102) “And when you are among them and lead them in prayer, let a group of them stand with you and take their weapons. Then when they have prostrated, let them be behind you, and let another group come that has not yet prayed and pray with you, taking precaution and their weapons. Those who disbelieve wish that you would neglect your weapons and belongings so they could attack you in a single assault. But there is no blame upon you if you are troubled by rain or are ill to lay down your weapons—yet take your precaution. Indeed, Allah has prepared for the disbelievers a humiliating punishment.”","[al-Nisā’: 101–102]","Al-Khaṭṭābī said in Ma‘ālim al-Sunan:","“Ṣalāt al-Khawf has multiple forms. The Messenger of Allah ﷺ performed it on different days and in varying ways, choosing each time what best preserved the prayer and most effectively ensured guard and protection. Though the forms differ, their meanings are harmonious.”","Ibn Ḥibbān said:","“These reports do not contradict one another. Rather, the Chosen One ﷺ prayed Ṣalāt al-Khawf repeatedly in different circumstances and in distinct forms, as we have mentioned, intending to teach his ummah that it is permissible for them to pray any of the nine forms that the Messenger of Allah ﷺ prayed in times of fear—according to the need. A person may choose whichever of these forms suits the situation, as this is permitted variety without contradiction or conflict.” (7/145)"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (942، 4133)، ومسلم (839)."},{"num":2903,"demo":false,"sanad":"","matn":["عَنْ صَالِحِ بْنِ خَوَّاتٍ، عَمَّنْ شَهِدَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ ذَاتِ الرِّقَاعِ، صَلَّى صَلاَةَ الْخَوْفِ، أَنَّ طَائِفَةً صَفَّتْ مَعَهُ، وَطَائِفَةٌ وُجَاهَ الْعَدُوِّ، فَصَلَّى بِالَّتِي مَعَهُ رَكْعَةً، ثُمَّ ثَبَتَ قَائِمًا، وَأَتَمُّوا لأَنْفُسِهِمْ، ثُمَّ انْصَرَفُوا، فَصَفُّوا وُجَاهَ الْعَدُوِّ، وَجَاءَتِ الطَّائِفَةُ الأُخْرَى فَصَلَّى بِهِمِ الرَّكْعَةَ الَّتِي بَقِيَتْ، مِنْ صَلاَتِهِ، ثُمَّ ثَبَتَ جَالِسًا، وَأَتَمُّوا لأَنْفُسِهِمْ، ثُمَّ سَلَّمَ بِهِمْ."],"takhrij":"متفق عليه: رواه مالك في صلاة الخوف (1) عن يزيد بن رومان، عن صالح بن خوَّات، عمَّن صلَّى مع رسول الله صلى الله عليه وسلم فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء أنَّ الإمامَ يصلّي لكلِّ طائفة ركعة ثم يسلّم وتقضي كلُّ طائفةٍ ركعةً لنفسها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Mālik (1), al-Bukhārī (4129), and Muslim (842). The phrase “from one who prayed with the Messenger of Allah ﷺ” refers to Sahl ibn Abī Ḥathmah, as stated in al-Bukhārī (4131) and Muslim (841).","chapter_en":"The imam prays one rak‘ah with each group, then gives salām, and each group completes one rak‘ah on its own","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":1,"content":{"translation":{"en":["Ṣāliḥ ibn Khawwāt narrated from one who prayed Ṣalāt al-Khawf with the Prophet ﷺ on the day of Dhāt al-Riqā‘: One group lined up with him, and another group faced the enemy. He prayed one rak‘ah with the group that was with him, then remained standing while they completed (the remaining rak‘ah) for themselves. Then they departed and lined up facing the enemy. The other group came, and he prayed with them the remaining rak‘ah, then remained seated while they completed for themselves. Then he gave salām with them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9096],"tks":"متفق عليه: رواه مالك (1) والبخاري (4129)، ومسلم (842). وقوله: (( عمن صلى مع رسول الله ﷺ )) هو سهل بن أبي حثمة كما في رواية البخاري (4131)، ومسلم (841)."},{"num":2904,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْمًا مِنْ جُهَيْنَةَ، فَقَاتَلُونَا قِتَالًا شَدِيدًا، فَلَمَّا صَلَّيْنَا الظُّهْرَ قَالَ الْمُشْرِكُونَ: لَوْ مِلْنَا عَلَيْهِمْ مَيْلَةً لَاقْتَطَعْنَاهُمْ، فَأَخْبَرَ جِبْرِيلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَلِكَ، فَذَكَرَ ذَلِكَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: وَقَالُوا: إِنَّهُ سَتَأْتِيهِمْ صَلَاةٌ هِيَ أَحَبُّ إِلَيْهِمْ مِنَ الْأَوْلَادِ، فَلَمَّا حَضَرَتِ الْعَصْرُ، قَالَ: صَفَّنَا صَفَّيْنِ، وَالْمُشْرِكُونَ بَيْنَنَا وَبَيْنَ الْقِبْلَةِ. قَالَ: فَكَبَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرْنَا، وَرَكَعَ فَرَكَعْنَا، ثُمَّ سَجَدَ وَسَجَدَ مَعَهُ الصَّفُّ الْأَوَّلُ. فَلَمَّا قَامُوا سَجَدَ الصَّفُّ الثَّانِي، ثُمَّ تَأَخَّرَ الصَّفُّ الْأَوَّلُ وَتَقَدَّمَ الصَّفُّ الثَّانِي، فَقَامُوا مَقَامَ الْأَوَّلِ، فَكَبَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرْنَا، وَرَكَعَ فَرَكَعْنَا، ثُمَّ سَجَدَ وَسَجَدَ مَعَهُ الصَّفُّ الْأَوَّلُ، وَقَامَ الثَّانِي. فَلَمَّا سَجَدَ الصَّفُّ الثَّانِي، ثُمَّ جَلَسُوا جَمِيعًا، سَلَّمَ عَلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","قال أبو الزبير: ثُمَّ خَصَّ جابرٌ أن قال: كما يُصَلِّي أمَرَاؤُكم هؤلاء."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (840/308) عن أحمد بن عبدالله بن يونس، حدثنا زهير، حدثنا أبو الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أنَّ الإمام يصلّي بكلّ طائفةِ ركعةً، ثم ينتظر حتى تقضي كل طائفة لنفسها ثم يسلم مع الجميع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (308/840).","chapter_en":"The imam prays one rak‘ah with each group, then waits for each group to complete for itself, then gives salām with everyone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn ‘Abdullāh said: We went out with the Messenger of Allah ﷺ against a people from Juhaynah, and they fought us fiercely. When we had prayed ẓuhr, the polytheists said: “If we were to attack them with a single charge, we would cut them down.” Jibrīl informed the Messenger of Allah ﷺ of that, and the Messenger of Allah ﷺ mentioned it to us. He said: They also said: “A prayer will come to them that is more beloved to them than their children.” When ‘aṣr arrived, he arranged us in two rows, with the polytheists between us and the qiblah. The Messenger of Allah ﷺ said takbīr and we said takbīr; he bowed and we bowed; then he prostrated, and the first row prostrated with him. When they rose, the second row prostrated. Then the first row moved back and the second row moved forward, taking the place of the first. The Messenger of Allah ﷺ said takbīr and we said takbīr; he bowed and we bowed; then he prostrated and the (now) first row prostrated with him, while the second row stood. When the second row prostrated, then all of them sat together, and the Messenger of Allah ﷺ gave salām to them. Abū al-Zubayr added that Jābir specifically said: “Like the way your leaders pray nowadays.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (840/308)."},{"num":2905,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ:  شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْخَوْفِ، فَصَفَّنَا صَفَّيْنِ: صَفٌّ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَالْعَدُوُّ بَيْنَنَا وَبَيْنَ الْقِبْلَةِ. فَكَبَّرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرْنَا جَمِيعًا، ثُمَّ رَكَعَ وَرَكَعْنَا جَمِيعًا، ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ وَرَفَعْنَا جَمِيعًا، ثُمَّ انْحَدَرَ بِالسُّجُودِ وَالصَّفُّ الَّذِي يَلِيهِ، وَقَامَ الصَّفُّ الْمُؤَخَّرُ فِي نَحْرِ الْعَدُوِّ. فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السُّجُودَ، وَقَامَ الصَّفُّ الَّذِي يَلِيهِ، انْحَدَرَ الصَّفُّ الْمُؤَخَّرُ بِالسُّجُودِ، وَقَامُوا. ثُمَّ تَقَدَّمَ الصَّفُّ الْمُؤَخَّرُ، وَتَأَخَّرَ الصَّفُّ الْمُقَدَّمُ، ثُمَّ رَكَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَكَعْنَا جَمِيعًا، ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ وَرَفَعْنَا جَمِيعًا. ثُمَّ انْحَدَرَ بِالسُّجُودِ وَالصَّفُّ الَّذِي يَلِيهِ الَّذِي كَانَ مُؤَخَّرًا فِي الرَّكْعَةِ الْأُولَى، وَقَامَ الصَّفُّ الْمُؤَخَّرُ فِي نُحُورِ الْعَدُوِّ. فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السُّجُودَ وَالصَّفُّ الَّذِي يَلِيهِ، انْحَدَرَ الصَّفُّ الْمُؤَخَّرُ بِالسُّجُودِ، فَسَجَدُوا، ثُمَّ سَلَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَلَّمْنَا جَمِيعًا.","قَالَ جَابِرٌ: كَمَا يَصْنَعُ حَرَسُكُمْ هَؤُلاءِ بِأُمَرَائِهِمْ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (840) عن محمد بن عبدالله بن نُمير، حدثنا أبي، حدثنا عبدالملك بن أبي سليمان، عن عطاء، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أنَّ الإمام يصلّي بكلّ طائفةِ ركعةً، ثم ينتظر حتى تقضي كل طائفة لنفسها ثم يسلم مع الجميع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (840).","chapter_en":"The imam prays one rak‘ah with each group, then waits for each group to complete for itself, then gives salām with everyone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn ‘Abdullāh said: I witnessed the Prayer of Fear with the Messenger of Allah ﷺ. He arranged us in two rows: one row behind the Messenger of Allah ﷺ, while the enemy was between us and the qiblah. The Prophet ﷺ said takbīr and we all said takbīr, then he bowed and we all bowed. Then he raised his head from bowing and we all raised our heads. Then he went down into prostration with the row nearest to him, while the rear row remained standing facing the enemy. When the Prophet ﷺ completed the prostration and the row nearest to him stood up, the rear row then went down into prostration and stood up. Then the rear row moved forward, and the front row moved back. Then the Prophet ﷺ bowed and we all bowed, then he raised his head and we all raised our heads. Then he went down into prostration with the row nearest to him (which had been the rear row in the first rak‘ah), while the rear row stood facing the enemy. When the Prophet ﷺ completed the prostration and the row nearest to him stood, the rear row went down into prostration and prostrated. Then the Prophet ﷺ gave salām and we all gave salām. Jābir said: “Like the way your guards do with their leaders.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (840)."},{"num":2906,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَيَّاشٍ الزُّرَقِيِّ، قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُسْفَانَ، وَعَلَى الْمُشْرِكِينَ خَالِدُ بْنُ الْوَلِيدِ، فَصَلَّيْنَا الظُّهْرَ، فَقَالَ الْمُشْرِكُونَ: لَقَدْ أَصَبْنَا غِرَّةً، لَقَدْ أَصَبْنَا غَفْلَةً، لَوْ كُنَّا حَمَلْنَا عَلَيْهِمْ وَهُمْ فِي الصَّلاَةِ، فَنَزَلَتْ آيَةُ الْقَصْرِ بَيْنَ الظُّهْرِ وَالْعَصْرِ، فَلَمَّا حَضَرَتِ الْعَصْرُ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسْتَقْبِلَ الْقِبْلَةِ، وَالْمُشْرِكُونَ أَمَامَهُ، فَصَفَّ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَفٌّ، وَصَفَّ بَعْدَ ذَلِكَ الصَّفِّ صَفٌّ آخَرُ فَرَكَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَكَعُوا جَمِيعًا، ثُمَّ سَجَدَ وَسَجَدَ الصَّفُّ الَّذِينَ يَلُونَهُ، وَقَامَ الآخَرُونَ يَحْرُسُونَهُمْ، فَلَمَّا صَلَّى هَؤُلاَءِ السَّجْدَتَيْنِ وَقَامُوا سَجَدَ الآخَرُونَ الَّذِينَ كَانُوا خَلْفَهُمْ، ثُمَّ تَأَخَّرَ الصَّفُّ الَّذِي يَلِيهِ إِلَى مَقَامِ الآخَرِينَ، وَتَقَدَّمَ الصَّفُّ الأَخِيرُ إِلَى مَقَامِ الصَّفِّ الأَوَّلِ، ثُمَّ رَكَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَكَعُوا جَمِيعًا، ثُمَّ سَجَدَ وَسَجَدَ الصَّفُّ الَّذِي يَلِيهِ، وَقَامَ الآخَرُونَ يَحْرُسُونَهُمْ، فَلَمَّا جَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالصَّفُّ الَّذِي يَلِيهِ سَجَدَ الآخَرُونَ، ثُمَّ جَلَسُوا جَمِيعًا، فَسَلَّمَ عَلَيْهِمْ جَمِيعًا، فَصَلاَّهَا بِعُسْفَانَ وَصَلاَّهَا يَوْمَ بَنِي سُلَيْمٍ."],"takhrij":"صحيح: رواه أبو داود (1236) عن سعيد بن منصور، حدثنا جرير بن عبدالحميد، عن منصور، عن مجاهد، عن أبي عيَّاشٍ الزُّرَقي فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أنَّ الإمام يصلّي بكلّ طائفةِ ركعةً، ثم ينتظر حتى تقضي كل طائفة لنفسها ثم يسلم مع الجميع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Abū Dāwūd (1236). Also authenticated by Ibn Ḥibbān (2876) and al-Ḥākim (1/337–338).","chapter_en":"The imam prays one rak‘ah with each group, then waits for each group to complete for itself, then gives salām with everyone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":2,"content":{"translation":{"en":["Abū ‘Ayyāsh al-Zuraqī said: We were with the Messenger of Allah ﷺ at ‘Usfān, and Khālid ibn al-Walīd was leading the polytheists. We prayed ẓuhr, and the polytheists said: “We caught them off guard; we caught them in heedlessness. If we had charged them while they were in prayer, we would have done so.” Then the verse regarding shortening (was revealed) between ẓuhr and ‘aṣr. When ‘aṣr came, the Messenger of Allah ﷺ stood facing the qiblah, with the polytheists in front of him. One row lined up behind the Messenger of Allah ﷺ, and another row behind that row. The Messenger of Allah ﷺ bowed and they all bowed. Then he prostrated, and the row nearest to him prostrated, while the others stood guarding them. When those completed the two prostrations and stood, the others who had been behind them prostrated. Then the row nearest to him moved back to the position of the others, and the last row moved forward to the position of the first row. Then the Messenger of Allah ﷺ bowed and they all bowed. Then he prostrated, and the row nearest to him prostrated, while the others stood guarding them. When the Messenger of Allah ﷺ sat (for the final sitting) along with the row nearest to him, the others prostrated, then all sat together, and he gave salām to them all. He prayed it that way at ‘Usfān, and he prayed it the same way on the day of Banī Sulaym."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1236). وصححه أيضا ابن حبان (2876)، والحاكم (1252)."},{"num":2907,"demo":false,"sanad":"","matn":["عَنْ مَرْوَانَ بْنِ الْحَكَمِ، أَنَّهُ سَأَلَ أَبَا هُرَيْرَةَ: هَلْ صَلَّيْتَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَةَ الْخَوْفِ؟ قَالَ أَبُو هُرَيْرَةَ: نَعَمْ. قَالَ مَرْوَانُ: مَتَى؟ فَقَالَ أَبُو هُرَيْرَةَ: عَامَ غَزْوَةِ نَجْدٍ، قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى صَلاَةِ الْعَصْرِ، فَقَامَتْ مَعَهُ طَائِفَةٌ، وَطَائِفَةٌ أُخْرَى مُقَابِلَ الْعَدُوِّ ظُهُورُهُمْ إِلَى الْقِبْلَةِ، فَكَبَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَبَّرُوا جَمِيعًا، الَّذِينَ مَعَهُ، وَالَّذِينَ مُقَابِلِي الْعَدُوِّ، ثُمَّ رَكَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً وَاحِدَةً، وَرَكَعَتِ الطَّائِفَةُ الَّتِي مَعَهُ، ثُمَّ سَجَدَ فَسَجَدَتِ الطَّائِفَةُ الَّتِي تَلِيهِ، وَالآخَرُونَ قِيَامٌ مُقَابِلِي الْعَدُوِّ، ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَامَتِ الطَّائِفَةُ الَّتِي مَعَهُ، فَذَهَبُوا إِلَى الْعَدُوِّ، فَقَابَلُوهُمْ، وَأَقْبَلَتِ الطَّائِفَةُ الَّتِي كَانَتْ مُقَابِلِي الْعَدُوِّ، فَرَكَعُوا وَسَجَدُوا، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ كَمَا هُوَ، ثُمَّ قَامُوا فَرَكَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً أُخْرَى وَرَكَعُوا مَعَهُ وَسَجَدَ وَسَجَدُوا مَعَهُ، ثُمَّ أَقْبَلَتِ الطَّائِفَةُ الَّتِي كَانَتْ مُقَابِلِي الْعَدُوِّ، فَرَكَعُوا وَسَجَدُوا، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ وَمَنْ مَعَهُ، ثُمَّ كَانَ السَّلاَمُ، فَسَلَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَلَّمُوا جَمِيعًا، فَكَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَانِ، وَلِكُلِّ رَجُلٍ مِنَ الطَّائِفَتَيْنِ رَكْعَةٌ رَكْعَةٌ."],"takhrij":"صحيح: رواه أبو داود (1240)، والنسائي (1543) كلاهما من طريق عبدالله بن يزيد المُقري، حدثنا حيوة وابن لهيعة، قالا: أخبرنا أبو الأسود، أنَّه سمع عروة بن الزبير، يحدث عن مروان بن الحكم فذكره، واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب ما جاء أنَّ الإمام يصلّي بكلّ طائفةِ ركعةً، ثم ينتظر حتى تقضي كل طائفة لنفسها ثم يسلم مع الجميع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Abū Dāwūd (1240) and al-Nasā’ī (1543).","chapter_en":"The imam prays one rak‘ah with each group, then waits for each group to complete for itself, then gives salām with everyone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":2,"content":{"translation":{"en":["Marwān ibn al-Ḥakam asked Abū Hurayrah: “Did you pray the Prayer of Fear with the Messenger of Allah ﷺ?” Abū Hurayrah said: “Yes.” Marwān said: “When?” Abū Hurayrah said: “In the year of the expedition to Najd. The Messenger of Allah ﷺ stood for the ‘aṣr prayer. One group stood with him, and another group stood facing the enemy with their backs toward the qiblah. The Messenger of Allah ﷺ said takbīr and all of them said takbīr—those with him and those facing the enemy. Then the Messenger of Allah ﷺ bowed one time, and the group with him bowed. Then he prostrated, and the group nearest to him prostrated, while the others remained standing facing the enemy. Then the Messenger of Allah ﷺ stood, and the group with him stood and went toward the enemy to face them. The group that had been facing the enemy came forward and bowed and prostrated, while the Messenger of Allah ﷺ remained standing as he was. Then when they stood, the Messenger of Allah ﷺ bowed for another rak‘ah, and they bowed with him; and he prostrated and they prostrated with him. Then the group that had been facing the enemy came and bowed and prostrated, while the Messenger of Allah ﷺ was sitting along with those who were with him. Then there was the salām: the Messenger of Allah ﷺ gave salām and they all gave salām. Thus the Messenger of Allah ﷺ had two rak‘ahs, and each man from the two groups had one rak‘ah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1240)، والنسائي (1543)."},{"num":2908,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَبَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَبَّرَتِ الطَّائِفَةُ الَّذِينَ صُفُّوا مَعَهُ، ثُمَّ رَكَعَ فَرَكَعُوا، ثُمَّ سَجَدَ فَسَجَدُوا، ثُمَّ رَفَعَ فَرَفَعُوا، ثُمَّ مَكَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا، ثُمَّ سَجَدُوا هُمْ لأَنْفُسِهِمُ الثَّانِيَةَ، ثُمَّ قَامُوا فَنَكَصُوا عَلَى أَعْقَابِهِمْ يَمْشُونَ الْقَهْقَرَى، حَتَّى قَامُوا مِنْ وَرَائِهِمْ، وَجَاءَتِ الطَّائِفَةُ الأُخْرَى فَقَامُوا فَكَبَّرُوا، ثُمَّ رَكَعُوا لأَنْفُسِهِمْ ثُمَّ سَجَدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَجَدُوا مَعَهُ، ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَجَدُوا لأَنْفُسِهِمُ الثَّانِيَةَ، ثُمَّ قَامَتِ الطَّائِفَتَانِ جَمِيعًا فَصَلُّوا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَكَعَ فَرَكَعُوا، ثُمَّ سَجَدَ فَسَجَدُوا جَمِيعًا، ثُمَّ عَادَ فَسَجَدَ الثَّانِيَةَ وَسَجَدُوا مَعَهُ سَرِيعًا كَأَسْرَعِ الإِسْرَاعِ جَاهِدًا لاَ يَأْلُونَ سِرَاعًا، ثُمَّ سلَّم رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَلَّمُوا فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَقَدْ شَارَكَهُ النَّاسُ فِي الصَّلاَةِ كلِّها."],"takhrij":"حسن: رواه أبو داود (1242) قال: وأما عبيدالله بن سعد فحدثنا قال: حدثني عمي، حدثنا أبي، عن ابن إسحاق، حدثني محمد بن جعفر بن الزبير، أن عروة بن الزبير حدثه، أن عائشة حدثته بهذه القصة، فقالت: فذكرت الحديث. وإسناده حسن لأجل محمد بن إسحاق وهو صدوق وقد صرَّح بالتحديث.","grade":"حسن","chapter_ar":"باب ما جاء أنَّ الإمام يصلّي بكلّ طائفةِ ركعةً، ثم ينتظر حتى تقضي كل طائفة لنفسها ثم يسلم مع الجميع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: Abū Dāwūd (1242), Aḥmad (26356), Ibn Khuzaymah (1363), and from him Ibn Ḥibbān (2873).","chapter_en":"The imam prays one rak‘ah with each group, then waits for each group to complete for itself, then gives salām with everyone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":2,"content":{"translation":{"en":["‘Ā’ishah (may Allah be pleased with her) said: The Messenger of Allah ﷺ said “Allāhu akbar,” and the group that had lined up with him also said “Allāhu akbar.” Then he bowed and they bowed; then he prostrated and they prostrated; then he raised his head and they raised their heads. Then the Messenger of Allah ﷺ remained seated, and they performed the second prostration for themselves. Then they stood and retreated on their heels, walking backward, until they stood behind the other group. Then the other group came and stood and said “Allāhu akbar.” Then they bowed for themselves. Then the Messenger of Allah ﷺ prostrated and they prostrated with him. Then the Messenger of Allah ﷺ stood, and they performed the second prostration for themselves. Then both groups stood together and prayed with the Messenger of Allah ﷺ: he bowed and they bowed; then he prostrated and they all prostrated together. Then he returned and made the second prostration, and they prostrated with him quickly—at the fastest pace—striving and not holding back. Then the Messenger of Allah ﷺ gave salām and they gave salām. Then the Messenger of Allah ﷺ stood, and the people had shared with him in the entire prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1242)، والإمام أحمد (26356)، وابن خزيمة (1363) وعنه ابن حبان (2873)."},{"num":2909,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ:  أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى إِذَا كُنَّا بِذَاتِ الرِّقَاعِ قَالَ: كُنَّا إِذَا أَتَيْنَا عَلَى شَجَرَةٍ ظَلِيلَةٍ تَرَكْنَاهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَجَاءَ رَجُلٌ مِنَ الْمُشْرِكِينَ وَسَيْفُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُعَلَّقٌ بِشَجَرَةٍ، فَأَخَذَ سَيْفَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاخْتَرَطَهُ، فَقَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَخَافُنِي؟ قَالَ: لَا. قَالَ: فَمَنْ يَمْنَعُكَ مِنِّي؟ قَالَ: اللَّهُ يَمْنَعُنِي مِنْكَ. قَالَ: فَتَهَدَّدَهُ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَغْمَدَ السَّيْفَ وَعَلَّقَهُ. قَالَ: فَنُودِيَ بِالصَّلَاةِ، فَصَلَّى بِطَائِفَةٍ رَكْعَتَيْنِ، ثُمَّ تَأَخَّرُوا، وَصَلَّى بِالطَّائِفَةِ الْأُخْرَى رَكْعَتَيْنِ. قَالَ: فَكَانَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعُ رَكَعَاتٍ، وَلِلْقَوْمِ رَكْعَتَانِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (843) عن أبي بكر ابن أبي شيبة، حدثنا عفَّان، حدثنا أبان بن يزيد، حدثنا يحيى بن أبي كثير، عن أبي سلمة، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء للإمام أربع ركعات وللمأموم ركعتان ركعتان","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (843).","chapter_en":"What has been reported that the imam has four rak‘ahs, while the followers have two rak‘ahs (two and two).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":3,"content":{"translation":{"en":["Jābir said: We came with the Messenger of Allah ﷺ until we were at Dhāt al-Riqā‘. He said: When we came upon a shady tree, we would leave it for the Messenger of Allah ﷺ. Then a man from the polytheists came while the Messenger of Allah’s ﷺ sword was hanging on a tree. He took the Prophet’s ﷺ sword and drew it, and said to the Messenger of Allah ﷺ: “Do you fear me?” He said: “No.” He said: “Then who will protect you from me?” He said: “Allah will protect me from you.” Then the companions of the Messenger of Allah ﷺ threatened him, so he sheathed the sword and hung it back. Then the call was made for prayer, and the Prophet ﷺ prayed two rak‘ahs with one group, then they moved back; and he prayed two rak‘ahs with the other group. Thus, the Messenger of Allah ﷺ had four rak‘ahs, while the people had two rak‘ahs."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9095],"tks":"صحيح: رواه مسلم (843)."},{"num":2910,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  فَرَضَ اللَّهُ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ أَرْبَعًا، وَفِي السَّفَرِ رَكْعَتَيْنِ، وَفِي الْخَوْفِ رَكْعَةً."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (687) من طرق عن مجاهد وغيره، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب من قال: وفي الخوف ركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (687).","chapter_en":"Those who said: “In fear, it is one rak‘ah.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":4,"content":{"translation":{"en":["Ibn ‘Abbās said: Allah prescribed the prayer on the tongue of your Prophet ﷺ: in residence, four (rak‘ahs); in travel, two; and in fear, one."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2857,12209],"tks":"صحيح: رواه مسلم (687)."},{"num":2911,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِذِي قَرَدٍ، وَصَفَّ النَّاسُ خَلْفَهُ صَفَّيْنِ، صَفًّا خَلْفَهُ، وَصَفًّا مُوَازِيَ الْعَدُوِّ، فَصَلَّى بِالَّذِينَ خَلْفَهُ رَكْعَةً، ثُمَّ انْصَرَفَ هَؤُلاَءِ إِلَى مَكَانِ هَؤُلاَءِ، وَجَاءَ أُولَئِكَ فَصَلَّى بِهِمْ رَكْعَةً، وَلَمْ يَقْضُوا."],"takhrij":"صحيح: رواه النسائي (1535) عن محمد بن بشار، قال: حدثنا يحيى بن سعيد، عن سفيان، قال: حدثنا أبو بكر بن أبي الجهم، عن عبيدالله بن عبدالله، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب من قال: وفي الخوف ركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Nasā’ī (1535), Aḥmad (2063); authenticated by Ibn Khuzaymah (1344) and Ibn Ḥibbān (2871).","chapter_en":"Those who said: “In fear, it is one rak‘ah.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":4,"content":{"translation":{"en":["Ibn ‘Abbās said: The Messenger of Allah ﷺ prayed at Dhī Qarad. The people formed two rows behind him: one row behind him, and one row parallel to the enemy. He prayed one rak‘ah with the group behind him. Then those people went to the place of the other group, and the others came, and he prayed one rak‘ah with them, and they did not make up anything."]},"buhuth":{"en":["His wording “Dhī Qarad”: with a qāf (ق) and an open rā’ (ر), ending with a dāl (د) — a mountain approximately 35 km northeast of Madinah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1535)، والإمام أحمد (2063)، وصححه ابن خزيمة (1344)، وابن حبان (2871)."},{"num":2912,"demo":false,"sanad":"","matn":["عَنْ ثَعْلَبَةَ بْنِ زَهْدَمٍ، قَالَ: كُنَّا مَعَ سَعِيدِ بْنِ الْعَاصِ بِطَبَرِسْتَانَ فَقَامَ فَقَالَ: أَيُّكُمْ صَلَّى مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَةَ الْخَوْفِ؟ فَقَالَ حُذَيْفَةُ: أَنَا. فَصَلَّى بِهَؤُلاَءِ رَكْعَةً، وَبِهَؤُلاَءِ رَكْعَةً، وَلَمْ يَقْضُوا."],"takhrij":"صحيح: رواه أبو داود (1246)، والنسائي (1531) كلاهما من طريق يحيى، قال: حدثنا سفيان، حدثني أشعث بن سُليم، عن الأسود بن هلال، عن ثعلبة بن زهدم فذكره.","grade":"صحيح","chapter_ar":"باب من قال: وفي الخوف ركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Abū Dāwūd (1246), al-Nasā’ī (1531).","chapter_en":"Those who said: “In fear, it is one rak‘ah.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":4,"content":{"translation":{"en":["Tha‘labah ibn Zahdam said: We were with Sa‘īd ibn al-‘Āṣ in Ṭabaristān, and he said: “Which of you prayed the Prayer of Fear with the Messenger of Allah ﷺ?” Ḥudhayfah said: “I did.” So he prayed one rak‘ah with one group and one rak‘ah with the other group, and they did not make up anything."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1246)، والنسائي (1531)."},{"num":2913,"demo":false,"sanad":"","matn":["عَنِ الْقَاسِمِ بْنِ حَسَّانَ، قَالَ: أَتَيْتُ زَيْدَ بْنَ ثَابِتٍ، فَسَأَلْتُهُ عَنْ صَلَاةِ الْخَوْفِ، فَقَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَفٌّ خَلْفَهُ، وَصَفٌّ بِإِزَاءِ الْعَدُوِّ، فَصَلَّى بِهِمْ رَكْعَةً، ثُمَّ ذَهَبُوا إِلَى مَصَافِّ إِخْوَانِهِمْ، وَجَاءَ الآخَرُونَ، فَصَلَّى بِهِمْ رَكْعَةً، ثُمَّ سَلَّمَ، فَكَانَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَانِ، وَلِكُلِّ طَائِفَةٍ رَكْعَةٌ."],"takhrij":"حسن: رواه النسائي (1531)، والإمام أحمد (21593)، وابن خزيمة (1345)، وابن حبان (2870)، والبيهقي (6050) كلهم من طريق سفيان، عن الرُّكَين الفزاري، عن القاسم بن حسان فذكره، واللفظ لابن حبان، وأمَّا النسائي فأحال على حديث حذيفة، والإمام أحمد أحال على حديث ابن عباس، وابن خزيمة أحال على حديث حذيفة، وإسناده حسن فإنَّ القاسم بن حسَّان وهو العامري الكوفي روى عنه اثنان ووثقه أحمد بن صالح كما ذكره ابن شاهين في ثقاته (1094) وذكره ابن حبان في الثقات (2870) واعتمده ابن خزيمة وابن حِبَّان فأخرجا الحديث في صحيحيهما.","grade":"حسن","chapter_ar":"باب من قال: وفي الخوف ركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: al-Nasā’ī (1531), Aḥmad (21593), Ibn Khuzaymah (1345), Ibn Ḥibbān (2870).","chapter_en":"Those who said: “In fear, it is one rak‘ah.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":4,"content":{"translation":{"en":["al-Qāsim ibn Ḥassān said: I came to Zayd ibn Thābit and asked him about the Prayer of Fear. He said: The Messenger of Allah ﷺ prayed while a row stood behind him and a row stood facing the enemy. He prayed one rak‘ah with them; then they went to the positions of their brothers, and the others came, and he prayed one rak‘ah with them. Then he gave salām. Thus, the Prophet ﷺ had two rak‘ahs, and each group had one rak‘ah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1531)، والإمام أحمد (21593)، وابن خزيمة (1345)، وابن حبان (2870)."},{"num":2914,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، صَلَّى بِهِمْ صَلَاةَ الْخَوْفِ، فَقَامَ صَفٌّ بَيْنَ يَدَيْهِ، وَصَفٌّ خَلْفَهُ، فَصَلَّى بِالَّذِي خَلْفَهُ رَكْعَةً، وَسَجْدَتَيْنِ، ثُمَّ تَقَدَّمَ هَؤُلَاءِ حَتَّى قَامُوا فِي مَقَامِ أَصْحَابِهِمْ، وَجَاءَ أُولَئِكَ حَتَّى قَامُوا مَقَامَ هَؤُلَاءِ، فَصَلَّى بِهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَةً، وَسَجْدَتَيْنِ، ثُمَّ سَلَّمَ، فَكَانَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَانِ، وَلَهُمْ رَكْعَةً."],"takhrij":"صحيح: رواه النسائي (1545) عن إبراهيم بن الحسن، عن حجاج بن محمد، عن شعبة، عن الحكم، عن يزيد الفقير، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب من قال: وفي الخوف ركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Nasā’ī (1545), Aḥmad (14180); authenticated by Ibn Khuzaymah (1347) and Ibn Ḥibbān (2869).","chapter_en":"Those who said: “In fear, it is one rak‘ah.”","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ‘Abdillāh reported that the Messenger of Allah ﷺ led them in the Prayer of Fear. One row stood in front of him and one row stood behind him. He prayed one rak‘ah with two prostrations with those behind him, then they moved forward to take the place of their companions, and the others came and stood in their place. The Messenger of Allah ﷺ then prayed one rak‘ah with two prostrations with them, then he gave salām. Thus, the Prophet ﷺ had two rak‘ahs, while they had one rak‘ah (each group)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1545) وأحمد (14180) وصححه ابن خزيمة (1347)، وابن حبان (2869)."},{"num":2915,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ:  صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْخَوْفِ فِي بَعْضِ أَيَّامِهِ، فَقَامَتْ طَائِفَةٌ مَعَهُ، وَطَائِفَةٌ بِإِزَاءِ الْعَدُوِّ، فَصَلَّى بِالَّذِينَ مَعَهُ رَكْعَةً. ثُمَّ ذَهَبُوا، وَجَاءَ الْآخَرُونَ فَصَلَّى بِهِمْ رَكْعَةً، ثُمَّ قَضَتِ الطَّائِفَتَانِ رَكْعَةً رَكْعَةً.","قَالَ ابْنُ عُمَرَ: فَإِذَا كَانَ خَوْفٌ أَكْثَرَ مِنْ ذَلِكَ فَصَلِّ رَاكِبًا أَوْ قَائِمًا، تُومِئُ إِيمَاءً."],"takhrij":"متفق عليه: رواه البخاري في الخوف (943)، ومسلم في صلاة المسافرين (830/306) كلاهما من حديث موسى بن عقبة، عن نافع، عن ابن عمر فذكره،","grade":"متفق عليه","chapter_ar":"باب صلاة الخوف رجالاً وركباناً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (943) and Muslim (306/830).","chapter_en":"Prayer of Fear on foot and while riding.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ prayed the Prayer of Fear on one of his days. One group stood with him, and another group faced the enemy. He prayed one rak‘ah with those with him; then they went, and the other group came and he prayed one rak‘ah with them. Then both groups made up one rak‘ah each. Ibn ‘Umar said: If the fear is greater than that, then pray while riding or standing, indicating the movements by gesture (īmā’)."]},"buhuth":{"en":["Mālik also narrated in Ṣalāt al-Khawf (3) from Nāfi‘ that ‘Abdullāh ibn ‘Umar, when asked about the Prayer of Fear, said:","The imam goes forward with a group of people and prays one rak‘ah with them, while another group stands between him and the enemy and has not prayed. When the imam has prayed one rak‘ah with those with him, they move back to the place of those who had not prayed, and they do not give salām. Then those who had not prayed come forward and pray one rak‘ah with him. Then the imam departs having prayed two rak‘ahs, and each of the two groups stands and prays one rak‘ah for themselves after the imam departs—so each group has prayed two rak‘ahs. If the fear is more severe than that, they pray on foot while standing, or while riding—facing the qiblah or not facing it.","Mālik said: Nāfi‘ said: I do not think ‘Abdullāh ibn ‘Umar narrated this except from the Messenger of Allah ﷺ. al-Bukhārī also narrated it in the Book of Tafsīr (535)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (943)، ومسلم (830/306)."},{"num":2916,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَامَ النَّاسُ مَعَهُ، فَكَبَّرَ وَكَبَّرُوا مَعَهُ، وَرَكَعَ وَرَكَعَ نَاسٌ مِنْهُمْ، ثُمَّ سَجَدَ وَسَجَدُوا مَعَهُ، ثُمَّ قَامَ لِلثَّانِيَةِ فَقَامَ الَّذِينَ سَجَدُوا وَحَرَسُوا إِخْوَانَهُمْ، وَأَتَتِ الطَّائِفَةُ الأُخْرَى فَرَكَعُوا وَسَجَدُوا مَعَهُ، وَالنَّاسُ كُلُّهُمْ فِي صَلاَةٍ، وَلَكِنْ يَحْرُسُ بَعْضُهُمْ بَعْضًا."],"takhrij":"صحيح: رواه البخاري في الخوف (944) عن حيوة بن شريح، قال: حدثنا محمد بن حرب، عن الزبيدي، عن الزهري، عن عبيدالله بن عبدالله ابن عتبة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب يحرس بعضهم بعضاً في صلاة الخوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Bukhārī (944).","chapter_en":"That they guard one another during the Prayer of Fear.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":6,"content":{"translation":{"en":["‘Abdullāh ibn ‘Abbās said: The Prophet ﷺ stood and the people stood with him. He said “Allāhu akbar” and they said “Allāhu akbar” with him. He bowed and some of them bowed. Then he prostrated and they prostrated with him. Then he stood for the second (rak‘ah), and those who had prostrated stood and guarded their brothers, and the other group came and bowed and prostrated with him. All of the people were in prayer, but they were guarding one another."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (944)."},{"num":2917,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: مَا كَانَتْ صَلاَةُ الْخَوْفِ إِلاَّ سَجْدَتَيْنِ كَصَلاَةِ أَحْرَاسِكُمْ هَؤُلاَءِ الْيَوْمَ خَلْفَ أَئِمَّتِكُمْ هَؤُلاَءِ إِلاَّ أَنَّهَا كَانَتْ عُقَبًا، قَامَتْ طَائِفَةٌ مِنْهُمْ وَهُمْ جَمِيعًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَجَدَتْ مَعَهُ طَائِفَةٌ مِنْهُمْ، ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَامُوا مَعَهُ جَمِيعًا، ثُمَّ رَكَعَ وَرَكَعُوا مَعَهُ جَمِيعًا، ثُمَّ سَجَدَ فَسَجَدَ مَعَهُ الَّذِينَ كَانُوا قِيَامًا أَوَّلَ مَرَّةٍ، فَلَمَّا جَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالَّذِينَ سَجَدُوا مَعَهُ فِي آخِرِ صَلاَتِهِمْ سَجَدَ الَّذِينَ كَانُوا قِيَامًا لأَنْفُسِهِمْ، ثُمَّ جَلَسُوا فَجَمَعَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالتَّسْلِيمِ."],"takhrij":"حسن: رواه النسائي (1535) عن عبيدالله بن سعد بن إبراهيم، قال: حدثني عمي، قال: حدثنا أبي، عن ابن إسحاق، قال: حدثني داود بن الحصين، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب يحرس بعضهم بعضاً في صلاة الخوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: al-Nasā’ī (1535), Aḥmad (2382), al-Bayhaqī (3/258).","chapter_en":"That they guard one another during the Prayer of Fear.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Abbās said: The Prayer of Fear was only two prostrations, like the prayer of your guards today behind your imams—except that it used to be in turns (ʿuqaban): a group of them would stand while all of them were with the Messenger of Allah ﷺ, and a group of them would prostrate with him. Then the Messenger of Allah ﷺ would stand and they would all stand with him. Then he would bow and they would all bow with him. Then he would prostrate, and those who had been standing the first time would prostrate with him. When the Messenger of Allah ﷺ and those who had prostrated with him were seated at the end of their prayer, those who had been standing would prostrate for themselves, then they would sit, and the Messenger of Allah ﷺ would unite them with the salām."]},"buhuth":{"en":["His phrase “it was in turns (ʿuqaban)” means: one group prays after another; they alternate it like warriors alternating duties."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1535)، والإمام أحمد (2382)، والبيهقي (6032)."},{"num":2918,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لمَّا رَجَعَ مِنْ الأَحْزَابِ: لاَ يُصَلِّيَنَّ أحدٌ الْعَصْرَ إلاَّ فِي بَنِي قُرَيْظَةَ فَأَدْرَكَ بَعْضُهُمُ الْعَصْرَ فِي الطَّرِيقِ، فَقَالَ بَعْضُهُمْ: لاَ نُصلِّي حتَّى نَأْتِيَهَا، وَقَالَ بَعْضُهُمْ: بَلْ نُصلِّي، وَلَمْ يُرِد مِنَّا ذَلِكَ، فذُكِر لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُعنِّف وَاحِدًا مِنْهُمْ."],"takhrij":"متفق عليه: رواه البخاري في صلاة الخوف (946) وفي المغازي bukhari(4119)، ومسلم في الجهاد والسير (1770) كلاهما عن عبدالله بن محمد ابن أسماء الضُّبعى، حدثنا جويرية بن أسماء، عن نافع، عن عبدالله فذكره. واللفظ للبخاري، ولفظ مسلم: نادي فينا رسول الله صلى الله عليه وسلم يوم انصرف عن الأحزاب: أن لا يُصَلِّينَّ أحد الظهرَ إلاَّ في بني قريظة فتخوَّف ناسٌ فوتَ الوقت فصلّوْا دون بني قُريظة، وقال آخرون: لا نُصَلِّي إلاَّ حيث أمرنا","grade":"متفق عليه","chapter_ar":"باب صلاة الطالب والمطلوب راكباً وإيماءً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (4119, 946) and Muslim (1770). The wording above is al-Bukhārī’s.","chapter_en":"The prayer of the pursuer and the pursued while riding and by gesturing (īmā’).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Umar reported: When the Prophet ﷺ returned from (the battle of) al-Aḥzāb, he said: “None of you should pray ‘Aṣr except in Banī Qurayẓah.” Some of them reached the time of ‘Aṣr while on the road. Some said: “We will not pray until we reach it (Banī Qurayẓah),” and others said: “Rather, we will pray,” and he did not intend from us that (i.e., blame either interpretation). It was mentioned to the Prophet ﷺ, and he did not reprimand any one of them."]},"buhuth":{"en":["Muslim’s wording: The Messenger of Allah ﷺ called out to us the day he returned from al-Aḥzāb: “That none of you should pray Ẓuhr except in Banī Qurayẓah.” Some feared missing the time, so they prayed before reaching Banī Qurayẓah. Others said: “We will not pray except where the Messenger of Allah ﷺ commanded us, even if the time passes.” He did not reprimand either group.","Some scholars reconciled the two wordings by suggesting: some had already prayed Ẓuhr before the command, while others had not—so it was said to those who had not prayed: “Do not pray Ẓuhr except…” and to those who had prayed: “Do not pray ‘Aṣr except…” Others reconciled it by suggesting different groups departed at different times: the first group was told “Ẓuhr,” and the later group was told “‘Aṣr.”","Both reconciliations are acceptable."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4119، 946)، ومسلم (1770). واللفظ للبخاري."},{"num":2919,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عبدالله بْنِ أُنَيس، عَنْ أَبِيهِ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى خَالِدِ بْنِ سُفْيَانَ الْهُذَلِيِّ، وَكَانَ نَحْوَ عُرَنَة وَعَرَفَاتٍ. فَقَالَ: اذْهَبْ فَاقْتُلْهُ، قَالَ: فَرَأَيْتُهُ وَحَضَرَتْ صَلاَةُ الْعَصْرِ، فَقُلْتُ: إنِّي لأَخَافُ أَنْ يَكُونَ بَيْنِي وَبَيْنَهُ مَا إِنْ أؤخِّر الصَّلاَةَ. فَانْطَلَقْتُ أَمْشِي، وَأَنَا أصلِّي أُومِئُ إِيمَاءً نَحْوَهُ. فَلَمَّا دَنَوْتُ مِنْهُ قَالَ لِي: مَنْ أَنْتَ؟ قُلْتُ: رَجُلٌ مِنَ الْعَرَبِ، بَلَغَنِي أَنَّكَ تَجْمَعُ لِهَذَا الرَّجُلِ، فَجِئْتُكَ فِي ذَاكَ، قَالَ: إِنِّي لَفِي ذَاكَ، فَمَشَيْتُ مَعَهُ سَاعَةً حَتَّى إِذَا أَمْكَنَنِي عَلَوْتُهُ بِسَيْفِي حَتَّى بَرَدَ. وَزَادَ رزين: وَكَانَ ساكنا بعُرنـة، وَكَانَ يجمـع لقتـال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِيهِ: قلتُ: إِنِّي لا أعرفه. قَالَ: إنه ثائر الرَّأْسِ، كَأَنَّهُ شيطان، إِذَا رأيته لَمْ يخفَ عليك؟ قَالَ: فجئتُه فَرَأَيْتُهُ وعرفتُه."],"takhrij":"حسن: رواه أبو داود (1249) عن أبي معمر عبدالله بن عمرو، حدثنا عبدالوارث، حدثنا محمد بن إسحاق، عن محمد بن جعفر، عن ابن عبدالله بن أُنَيس، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب صلاة الطالب والمطلوب راكباً وإيماءً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan due to supporting chains: Abū Dāwūd (1249), Aḥmad (16047), Ibn Khuzaymah (982, 983), Ibn Ḥibbān (7160), and al-Bayhaqī in al-Dalā’il (4/40–41).","chapter_en":"The prayer of the pursuer and the pursued while riding and by gesturing (īmā’).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الخوفِ","group_en":"Comprehensive section: Prayer of Fear (Ṣalāt al-Khawf)","part_no":9,"group_no":19,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Abdillāh ibn Unays narrated from his father: The Messenger of Allah ﷺ sent me to Khālid ibn Sufyān al-Hudhalī, who was near ‘Uranah and ‘Arafāt, and said: “Go and kill him.” I saw him and the time for ‘Aṣr arrived, so I said: “I fear that something may come between me and him if I delay the prayer.” So I set off walking while praying, gesturing (īmā’) toward him. When I came near him, he said: “Who are you?” I said: “A man from the Arabs. I heard you are gathering (people) against this man, so I came to you regarding that.” He said: “Indeed I am doing that.” I walked with him for a while until I had the chance, then I struck him with my sword until he became cold (died). Razīn added: He was living at ‘Uranah and was gathering to fight the Messenger of Allah ﷺ. In it: I said: “I do not know him.” He said: “He is disheveled-haired, as if he were a devil—when you see him, he will not be hidden from you.” So I went to him, saw him, and recognized him."]},"buhuth":{"en":["Aḥmad’s wording: The Messenger of Allah ﷺ called me and said: “It has reached me that Khālid ibn Sufyān ibn Nubayḥ al-Hudhalī is gathering people against me to raid me, and he is at ‘Uranah—so go to him and kill him.” I said: “O Messenger of Allah, describe him to me so I can recognize him.” He said: “When you see him, you will feel a shiver (iqsha‘rīrah).” I went out with my sword and found him at ‘Uranah with some women traveling (ẓu‘un), looking for a place to settle, and it was the time of ‘Aṣr. When I saw him, I felt what the Messenger of Allah ﷺ described. I approached him, fearing that a struggle between me and him might distract me from the prayer, so I prayed while walking toward him, gesturing with my head for bowing and prostration. When I reached him, he said: “Who is the man?” I said: “A man from the Arabs who heard about you and your gathering against this man, so he came to you for that.” He said: “Yes, I am doing that.” I walked with him a little until I had the chance, then I attacked him with the sword until I killed him. Then I left, and I left his women bent over him. When I returned to the Messenger of Allah ﷺ, he saw me and said: “The face has succeeded!” I said: “I killed him, O Messenger of Allah.” He said: “You have spoken the truth.” Then the Messenger of Allah ﷺ stood with me and entered his house, and he gave me a stick and said: “Keep this with you, O ‘Abdullāh ibn Unays.” I went out with it among the people and they said: “What is this stick?” I said: “The Messenger of Allah ﷺ gave it to me and ordered me to keep it.” They said: “Will you not go back to the Messenger of Allah ﷺ and ask him about it?” So I returned and said: “O Messenger of Allah, why did you give me this stick?” He said: “A sign between me and you on the Day of Resurrection; indeed the fewest (of people) that day will be those who carry things at their waist (al-mutakhaṣṣirūn).” ‘Abdullāh then fastened it with his sword and it remained with him until he died; he instructed that it be placed with him in his shroud, and they were buried together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1249)، وأحمد (16047)، وابن خزيمة (982، 983)، وابن حبان (7160)، والبيهقي في (( الدلائل)) (4/40-41)."},{"num":2920,"demo":false,"sanad":"","matn":["عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى، يَقُولُ: مَا حَدَّثَنَا أَحَدٌ، أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى غَيْرَ أُمِّ هَانِئٍ، فَإِنَّهَا قَالَتْ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ بَيْتَهَا يَوْمَ فَتْحِ مَكَّةَ، فَاغْتَسَلَ، وَصَلَّى ثَمَانِيَ رَكَعَاتٍ، فَلَمْ أَرَ صَلاَةً قَطُّ أَخَفَّ مِنْهَا، غَيْرَ أَنَّهُ يُتِمُّ الرُّكُوعَ وَالسُّجُودَ."],"takhrij":"متفق عليه: رواه البخاريّ في كتاب التهجد (1176)، ومسلم في صلاة المسافرين (336/80) كلاهما من طريق شعبة، حدثنا عمرو بن مُرَّة، قال: سمعت عبدالرحمن بن أبي ليلى فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1176) and Muslim (80/336).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["‘Abd al-Raḥmān ibn Abī Laylā said: None of those who saw the Prophet ﷺ praying Ḍuḥā informed us except Umm Hānī’. She said: The Prophet ﷺ entered her house on the day of the conquest of Makkah, performed ghusl, and prayed eight rak‘ahs. I have never seen a prayer lighter than it, while he still completed the bowing and prostration fully."]},"buhuth":{"en":["Mālik (28) also narrated that Umm Hānī’ bint Abī Ṭālib said: I went to the Messenger of Allah ﷺ in the year of the conquest and found him bathing, while his daughter Fāṭimah was screening him with a cloth. I greeted him and he said: “Who is this?” I said: Umm Hānī’ bint Abī Ṭālib. He said: “Welcome, Umm Hānī’.” When he finished bathing, he stood and prayed eight rak‘ahs, wrapped in a single garment, then left. I said: O Messenger of Allah, my brother ‘Alī claims he will kill a man whom I have granted protection—so-and-so ibn Hubayrah. The Messenger of Allah ﷺ said: “We have granted protection to whom you have granted protection, O Umm Hānī’.” Umm Hānī’ said: And that was during Ḍuḥā.","Also narrated by al-Bukhārī (357) and Muslim (82/336).","Her statement “I went to the Messenger of Allah ﷺ” means: to her own house—because the Prophet ﷺ entered her house while she had stepped out; then she returned and found him bathing, with Fāṭimah screening him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1176)، ومسلم (336/80)."},{"num":2921,"demo":false,"sanad":"","matn":["عن أنس بْنِ سِيرِينَ قَالَ: سَمِعْتُ أَنَسًا، يَقُولُ: قَالَ رَجُلٌ مِنَ الأَنْصَارِ: إِنِّي لاَ أَسْتَطِيعُ الصَّلاَةَ مَعَكَ. وَكَانَ رَجُلاً ضَخْمًا، فَصَنَعَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا فَدَعَاهُ إِلَى مَنْزِلِهِ، فَبَسَطَ لَهُ حَصِيرًا، وَنَضَحَ طَرَفَ الْحَصِيرِ، صَلَّى عَلَيْهِ رَكْعَتَيْنِ. فَقَالَ رَجُلٌ مِنْ آلِ الْجَارُودِ لأَنَسٍ: أَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى؟ قَالَ: مَا رَأَيْتُهُ صَلاَّهَا إِلاَّ يَوْمَئِذٍ."],"takhrij":"صحيح: رواه البخاري في الأذان (670) عن آدم، وفي التهجد bukhari(1179) عن علي بن الجعد، كلاهما عن شعبة قال: حدثنا أنس بن سيرين، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Bukhārī (1179, 670).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Sīrīn said: I heard Anas say: A man from the Anṣār said: “I cannot pray with you (in the mosque)”—and he was a large man—so he prepared food for the Prophet ﷺ and invited him to his home. He spread out a mat for him and sprinkled water on the edge of the mat, and the Prophet ﷺ prayed two rak‘ahs on it. A man from the family of al-Jārūd asked Anas: “Did the Prophet ﷺ pray Ḍuḥā?” He said: “I did not see him pray it except on that day.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2583],"tks":"صحيح: رواه البخاري (1179، 670)."},{"num":2922,"demo":false,"sanad":"","matn":["حَدَّثَتْنِي مُعَاذَةُ  أَنَّهَا سَأَلَتْ عَائِشَةَ: رَضِيَ اللَّهُ عَنْهَا: كَمْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلَاةَ الضُّحَى؟ قَالَتْ: أَرْبَعَ رَكَعَاتٍ، وَيَزِيدُ مَا شَاءَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (719) عن شيبان بن فروُّخ، حدّثنا عبد الوارث، حدثنا يزيد (يعني الرِشْك) حدثتني معاذةُ فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (719).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Mu‘ādhah asked ‘Ā’ishah: How many (rak‘ahs) did the Messenger of Allah ﷺ use to pray for Ḍuḥā? She said: Four rak‘ahs, and he would add whatever Allah willed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (719)."},{"num":2923,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  يُصْبِحُ عَلَى كُلِّ سُلَامَى مِنْ أَحَدِكُمْ صَدَقَةٌ، فَكُلُّ تَسْبِيحَةٍ صَدَقَةٌ، وَكُلُّ تَحْمِيدَةٍ صَدَقَةٌ، وَكُلُّ تَهْلِيلَةٍ صَدَقَةٌ، وَكُلُّ تَكْبِيرَةٍ صَدَقَةٌ، وَأَمْرٌ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيٌ عَنِ الْمُنْكَرِ صَدَقَةٌ. وَيُجْزِئُ مِنْ ذَلِكَ رَكْعَتَانِ يَرْكَعُهُمَا مِنَ الضُّحَى."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (720) عن عبدالله بن محمد بن أسماء الضُبَعي، حدثنا مهدي (وهو ابن ميمون) حدثنا واصل مولى أبي عيينة، عن يحيى بن عقيل، عن يحيى بن يَعْمَر، عن أبي الأسود الدُولي، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Muslim (720).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū Dharr narrated that the Prophet ﷺ said: “Each morning, every joint (salāmā) of one of you owes a charity. Every saying of ‘Subḥānallāh’ is a charity, every ‘Alḥamdulillāh’ is a charity, every ‘Lā ilāha illā Allāh’ is a charity, every ‘Allāhu Akbar’ is a charity, enjoining what is right is a charity, and forbidding what is wrong is a charity—and two rak‘ahs prayed at Ḍuḥā suffice for all of that.”"]},"buhuth":{"en":["Abū Dāwūd (5243) narrated it with an addition: “Greeting with salām those you meet is a charity; removing harm from the road is a charity; and marital intimacy with one’s spouse is a charity.” They said: O Messenger of Allah ﷺ, does one of us fulfill desire and still receive charity? He said: “Do you see—if he were to place it in other than its lawful place, would he bear sin?” Then he said: “And two rak‘ahs of Ḍuḥā suffice for all of that.”","His statement “every salāmā” means every bone and joint that a person relies upon for movement. The original usage of salāmā is a bone in the camel’s hoof-area, and its plural is salāmiyyāt."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (720)."},{"num":2924,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: أَوْصَانِي حَبِيبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بثلاثة لَا أَدَعُهُنَّ إِنْ شَاءَ اللَّهُ تَعَالَى أَبَدًا. أَوْصَانِي بِصَلَاةِ الضُّحَى، وَبِالْوِتْرِ قَبْلَ النَّوْمِ، وَبِصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ."],"takhrij":"صحيح: رواه النسائي (2404) عن علي بن حجر، قال: حدثنا إسماعيل، حدثنا محمد بن أبي حرملة، عن عطاء بن يسار، عن أبي ذرٍّ فذكره.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: al-Nasā’ī (2404), Aḥmad (21518); also authenticated by Ibn Khuzaymah (1083).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū Dharr said: My beloved (the Prophet ﷺ) advised me with three things which I will never abandon, Allah willing: the Ḍuḥā prayer, Witr before sleeping, and fasting three days of every month."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2801],"tks":"صحيح: رواه النسائي (2404)، والإمام أحمد (21518)، وقد صححه ابن خزيمة (1083)."},{"num":2925,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، وَأَبِي، ذَرٍّ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اللَّهِ، عَزَّ وَجَلَّ أَنَّهُ قَالَ: ابْنَ آدَمَ ارْكَعْ لِي مِنْ أَوَّلِ النَّهَارِ أَرْبَعَ رَكَعَاتٍ أَكْفِكَ آخِرَهُ."],"takhrij":"حسن: رواه الترمذي (475) عن أبي جعفر السمناني، حدثنا أبو مُسْهِر، حدثنا إسماعيل بن عياش، عن بحير بن سعد، عن خالد بن معدان، عن جبير بن نفير، عن أبي الدرداء وأبي ذر فذكراه.","grade":"حسن","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: al-Tirmidhī (475). Al-Tirmidhī said: “Ḥasan gharīb.”","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū al-Dardā’ and Abū Dharr narrated that the Messenger of Allah ﷺ reported from Allah, Mighty and Majestic, that He said: “Son of Ādam, pray for Me four rak‘ahs at the beginning of the day, and I will suffice you for its end.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (475). قال الترمذي: (( حسن غريب ))."},{"num":2926,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ:  أَوْصَانِي حَبِيبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثٍ، لَنْ أَدَعَهُنَّ مَا عِشْتُ: بِصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَصَلَاةِ الضُّحَى، وَبِأَنْ لَا أَنَامَ حَتَّى أُوتِرَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (722) عن هارون بن عبدالله ومحمد بن رافع، قالا: حدثنا ابن أبي فُديك، عن الضّحاك بن عثمان، عن إبراهيم بن عبدالله بن حُنين، عن أبي مُرة مولى أم هانئ، عن أبي الدرداء فذكره.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Muslim (722).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū al-Dardā’ said: My beloved (the Prophet ﷺ) advised me with three things I will never leave as long as I live: fasting three days each month, the Ḍuḥā prayer, and not sleeping until I have prayed Witr."]}},"tuhfa":{},"full":1,"rep":[2800,4449],"tks":"صحيح: رواه مسلم (722)."},{"num":2927,"demo":false,"sanad":"","matn":["عن بُرَيْدَةَ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: فِي الإِنْسَانِ ثَلاَثُمِائَةٍ وَسِتُّونَ مَفْصِلاً، فَعَلَيْهِ أَنْ يَتَصَدَّقَ عَنْ كُلِّ مَفْصِلٍ مِنْهُ بِصَدَقَةٍ. قَالُوا: وَمَنْ يُطِيقُ ذَلِكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: النُّخَاعَةُ فِي الْمَسْجِدِ تَدْفِنُهَا، وَالشَّىْءُ تُنَحِّيهِ عَنِ الطَّرِيقِ، فَإِنْ لَمْ تَجِدْ فَرَكْعَتَا الضُّحَى تُجْزِئُكَ."],"takhrij":"حسن: رواه أبو داود (5242) عن أحمد بن محمد المروزي، قال: حدثني علي بن حسين، حدثني أبي، قال: حدثني عبدالله بن بريدة، قال: سمعتُ أبي بريدةَ فذكر الحديث.","grade":"حسن","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Abū Dāwūd (5242), Ibn Khuzaymah (1226), and Ibn Ḥibbān (1642, 2540).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Buraydah said: I heard the Messenger of Allah ﷺ say: “A human being has three hundred and sixty joints, and he must give charity on behalf of each joint.” They said: Who can manage that, O Prophet of Allah ﷺ? He said: “A glob of phlegm in the mosque that you bury, and something harmful that you remove from the road. If you do not find (a way to do that), then the two rak‘ahs of Ḍuḥā suffice you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14761],"tks":"حسن: رواه أبو داود (5242)، وابن خزيمة (1226)، وابن حبان (1642، 2540)."},{"num":2928,"demo":false,"sanad":"","matn":["عَنْ عِتْبَانَ بْنِ مَالِكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي بَيْتِهِ سُبْحَةَ الضُّحَى، فَقَامُوا وَرَاءَهُ فَصَلَّوْا بِصَلَاتِهِ."],"takhrij":"صحيح: رواه الإمام أحمد (23773) عن عثمان بن عمر، حدثنا يونس، عن الزهري، عن محمود بن الربيع، عن عِتْبان بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Imām Aḥmad (23773).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["‘Itbān ibn Mālik (may Allah be pleased with him) reported that the Messenger of Allah ﷺ prayed the Ḍuḥā voluntary prayer in his house, and they stood behind him and prayed following his prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (23773)."},{"num":2929,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ قَالَ: أَوْصَانِي خَلِيلِي بِثَلاَثٍ، لاَ أَدَعُهُنَّ حَتَّى أَمُوتَ: صَوْمِ ثَلاَثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَصَلاَةِ الضُّحَى، وَنَوْمٍ عَلَى وِتْرٍ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1178)، ومسلم في صلاة المسافرين (721) كلاهما من طريق شُعبة، حدثنا عباس الجُريري -وهو ابن فروُّخ عن أبي عثمان النهدي، عن أبي هريرة فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1178) and Muslim (721); the wording is al-Bukhārī’s. In Muslim’s wording: “and the two rak‘ahs of Ḍuḥā.”","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah said: My close friend (the Prophet ﷺ) advised me with three things I will not abandon until I die: fasting three days every month, the Ḍuḥā prayer, and sleeping after praying Witr."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2799],"tks":"متفق عليه: رواه البخاري (1178)، ومسلم (721)، واللفظ للبخاري. وفي لفظ مسلم: (( وركعتي الضحى))."},{"num":2930,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْثًا، فَأَعْظَمُوا الْغَنِيمَةَ وَأَسْرَعُوا الكرَّة، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ! مَا رَأَيْنَا بَعْثًا قَطُّ أَسْرَعَ كرَّةً، وَلَا أَعْظَمَ مِنْهُ غنيمـةً مِنْ هَذَا الْبَعْثِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَلَا أُخْبِرُكُمْ بِأَسْرَعَ كرَّةً مِنْهُ، وَأَعْظَمَ غَنِيمَةً! رَجُلٌ تَوَضَّأَ فِي بَيْتِهِ فَأَحْسَنَ وُضُوءَهُ، ثُمَّ عمد إِلَى الْمَسْجِدِ فصلَّى فِيهِ الْغَدَاةَ،ثُمَّ عقَّب بِصَلَاةِ الضَحْوةِ، فَقَدْ أَسْرَعَ الكرَّة وَأَعْظَمَ الْغَنِيمَةَ ."],"takhrij":"حسن: رواه أبو يعلى (6528) عن أبي (وهو ابن أبي شيبة) حدثنا حاتم (ابن إسماعيل) عن حُميد بن صَخْرٍ، عن المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Abū Ya‘lā (6528); authenticated by Ibn Ḥibbān (2535).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ dispatched a detachment. They gained a great amount of booty and returned quickly. A man said: O Messenger of Allah ﷺ, we have never seen a detachment return faster or bring more booty than this one. The Messenger of Allah ﷺ said: “Shall I tell you of one who returns faster than it and gains greater booty? A man who performs wudū’ in his house and perfects it, then goes to the mosque and prays the morning prayer (al-ghadāh) there, then follows it with the Ḍuḥā prayer—he has returned faster and gained greater booty.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (6528)، وصححه ابن حبان (2535)."},{"num":2931,"demo":false,"sanad":"","matn":["عَنْ نُعَيْمِ بْنِ هَمَّارٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَقُولُ اللَّهُ عَزَّ وَجَلَّ: يَا ابْنَ آدَمَ لاَ تُعْجِزْنِي مِنْ أَرْبَعِ رَكَعَاتٍ فِي أَوَّلِ نَهَارِكَ، أَكْفِكَ آخِرَهُ."],"takhrij":"صحيح: رواه أبو داود (1289) عن داود بن رُشيد، ثنا الوليد، عن سعيد بن عبدالعزيز، عن مكحول، عن كثير بن مُرَّة، عن نُعيم بن هَمَّار فذكره.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Abū Dāwūd (1289) and Aḥmad (22470).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Nu‘aym ibn Hammār said: I heard the Messenger of Allah ﷺ say: “Allah, Mighty and Majestic, says: O son of Ādam, do not fail Me in (performing) four rak‘ahs at the beginning of your day, and I will suffice you for its end.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1289)، وأحمد (22470)."},{"num":2932,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ يَقُولُ: يَا ابْنَ آدَمَ، اكْفِنِي أَوَّلَ النَّهَارِ بِأَرْبَعِ رَكَعَاتٍ، أَكْفِكَ بِهِنَّ آخِرَ يَوْمِكَ."],"takhrij":"صحيح: رواه الإمام أحمد (17390)، وأبو يعلى (1757) كلاهما من طريق يزيد بن هارون، حدثنا أبان بن يزيد العَطَّار، عن قتادة، عن نُعيم بن هَمَّار، عن عقبة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Imām Aḥmad (17390) and Abū Ya‘lā (1757).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["‘Uqbah ibn ‘Āmir al-Juhanī reported that the Messenger of Allah ﷺ said: “Allah says: O son of Ādam, devote four rak‘ahs to Me at the beginning of the day, and I will suffice you by them for the end of your day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (17390)، وأبو يعلى (1757)."},{"num":2933,"demo":false,"sanad":"","matn":["عَنِ النَّوَّاسِ بْنِ سَمْعَانَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللَّهُ عز وجل: ابْنَ آدَمَ، لَا تَعْجِزَنَّ مِنْ أَرْبَعِ رَكَعَاتٍ فِي أَوَّلِ النَّهَارِ، أَكْفِكَ آخِرَهُ."],"takhrij":"صحيح: قال الهيثمي في المجمع (٣٤١٣): رواه الطبراني في الكبير ورجاله ثقات. إلا أني لم أقف على إسناده، وهذا الحكم مبني على قول الهيثمي، ثم وقفت على كلام العيني في عمدة القارئ (7/147) فقال: حديث النواس بن سمعان عند الطبراني في الكبير من رواية أبي إدريس الخولاني، قال: سمعت النواس بن سمعان، فذكر الحديث، وقال: إسناده صحيح.","grade":"صحيح","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Ṭabarānī in al-Kabīr (as mentioned by al-Haythamī and al-‘Aynī).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Al-Nawwās ibn Sam‘ān said: I heard the Messenger of Allah ﷺ say: “Allah, Mighty and Majestic, says: Son of Ādam, do not be incapable of (performing) four rak‘ahs at the beginning of the day; I will suffice you for its end.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير كما قال الهيثمي والعيني."},{"num":2934,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ خَرَجَ مِنْ بَيْتِهِ مُتَطَهِّرًا إِلَى صَلاَةٍ مَكْتُوبَةٍ فَأَجْرُهُ كَأَجْرِ الْحَاجِّ الْمُحْرِمِ، وَمَنْ خَرَجَ إِلَى تَسْبِيحِ الضُّحَى لاَ يُنْصِبُهُ إِلاَّ إِيَّاهُ فَأَجْرُهُ كَأَجْرِ الْمُعْتَمِرِ، وَصَلاَةٌ عَلَى أَثَرِ صَلاَةٍ لاَ لَغْوَ بَيْنَهُمَا كِتَابٌ فِي عِلِّيِّينَ."],"takhrij":"حسن: رواه أبو داود (558) وأحمد (22304) كلاهما من طريق يحيى بن الحارث، عن القاسم أبي عبدالرحمن، عن أبي أمامة فذكره. واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Abū Dāwūd (558) and Aḥmad (22304); the wording is Abū Dāwūd’s.","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah said: The Messenger of Allah ﷺ said: “Whoever leaves his home in a state of purification for an obligatory prayer, his reward is like the reward of a pilgrim in iḥrām. Whoever goes out for the glorification (prayer) of Ḍuḥā, intending nothing but it, his reward is like the reward of one performing ‘umrah. And a prayer following a prayer with no idle talk between them is recorded in ‘Illiyyīn.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1559],"tks":"حسن: رواه أبو داود (558) وأحمد (22304). واللفظ لأبي داود."},{"num":2935,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي، قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً، فَغَنِمُوا، وَأَسْرَعُوا الرَّجْعَةَ، فَتَحَدَّثَ النَّاسُ بِقُرْبِ مَغْزَاهُمْ، وَكَثْرَةِ غَنِيمَتِهِمْ، وَسُرْعَةِ رَجْعَتِهِمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أَدُلُّكُمْ عَلَى أَقْرَبَ مِنْهُ مَغْزًى، وَأَكْثَرَ غَنِيمَةً، وَأَوْشَكَ رَجْعَةً؟ مَنْ تَوَضَّأَ، ثُمَّ غَدَا إِلَى الْمَسْجِدِ لِسُبْحَةِ الضُّحَى، فَهُوَ أَقْرَبُ مَغْزًى، وَأَكْثَرُ غَنِيمَةً، وَأَوْشَكُ رَجْعَةً."],"takhrij":"حسن: رواه الإمام أحمد (6638) عن حسن، حدثنا ابن لهيعة، حدثني حُييُّ ابن عبدالله، أن أبا عبدالرحمن الحُبلِّي حدَّثه، عن عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Imām Aḥmad (6638).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["‘Abdullāh ibn ‘Amr ibn al-‘Āṣ said: The Messenger of Allah ﷺ sent out a detachment. They obtained booty and returned quickly. People spoke about how near their raid was, the abundance of their booty, and the speed of their return. The Messenger of Allah ﷺ said: “Shall I direct you to something nearer than that in ‘campaign’, with more booty, and a quicker return? Whoever performs wudū’ then goes early to the mosque for the Ḍuḥā voluntary prayer—he is nearer in ‘campaign’, has more booty, and returns sooner.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (6638)."},{"num":2936,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي مِنَ الضُّحَى."],"takhrij":"حسن: رواه الإمام أحمد (682) عن سليمان بن داود، أخبرنا شعبةُ، عن أبي إسحاق، سمع عاصم بن ضمْرة، عن علي فذكره.","grade":"حسن","chapter_ar":"باب استحباب صلاة الضُحى وأقلُها ركعتان وأكملها ثمان ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Imām Aḥmad (682), Abū Dāwūd al-Ṭayālisī in his Musnad (129), and al-Nasā’ī in al-Kubrā (471).","chapter_en":"The recommendation of the Ḍuḥā prayer: its minimum is two rak‘ahs, and its most complete form is eight rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["‘Alī ibn Abī Ṭālib said: The Messenger of Allah ﷺ used to pray the Ḍuḥā prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (682) وأبو داود الطيالسي في مسنده (129) والنسائي في الكبرى (471)."},{"num":2937,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ:  مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي سُبْحَةَ الضُّحَى قَطُّ، وَإِنِّي لَأُسَبِّحُهَا. وَإِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَدَعُ الْعَمَلَ، وَهُوَ يُحِبُّ أَنْ يَعْمَلَ بِهِ خَشْيَةَ أَنْ يَعْمَلَ بِهِ النَّاسُ فَيُفْرَضَ عَلَيْهِمْ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (29) عن ابن شهاب، عن عروة ابن الزبير، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب عدم مواظبة النبي ﷺ على صلاة الضُحى خشية أن تُفرض","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik (29), al-Bukhārī (1128), and Muslim (718).","chapter_en":"The Prophet’s ﷺ not persisting regularly in the Ḍuḥā prayer out of fear that it might become obligatory.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":2,"content":{"translation":{"en":["‘Ā’ishah said: I never saw the Messenger of Allah ﷺ pray the voluntary Ḍuḥā prayer at all, though I do pray it. And the Messenger of Allah ﷺ would sometimes leave an action even though he loved to do it, fearing that people might do it (regularly) and it would then be made obligatory upon them."]},"buhuth":{"en":["And ‘Ā’ishah’s statement, “I never saw the Messenger of Allah ﷺ pray the voluntary Ḍuḥā prayer at all,” likely means that he did not persist regularly in it; otherwise, it is established in authentic narrations that he ﷺ did pray it, but he did not maintain it consistently out of fear that it might be made obligatory."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (29) والبخاري (1128)، ومسلم (718)."},{"num":2938,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: مَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الضُّحَى قَطُّ إِلَّا مَرَّةً وَاحِدَةً."],"takhrij":"حسن: رواه الإمام أحمد (9758) عن وكيع، والبزار - كشف الأستار (696) من طريق قبيصة كلاهما عن سفيان، عن عاصم بن كليب، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب عدم مواظبة النبي ﷺ على صلاة الضُحى خشية أن تُفرض","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Imām Aḥmad (9758) and al-Bazzār (Kashf al-Astār, 696). Abū Hurayrah’s negation is understood according to what he personally knew/observed.","chapter_en":"The Prophet’s ﷺ not persisting regularly in the Ḍuḥā prayer out of fear that it might become obligatory.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah said: I did not see the Prophet ﷺ pray Ḍuḥā at all except one single time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (9758)، والبزار - كشف الأستار (696). ونفي أبي هريرة محمول على علمه."},{"num":2939,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ شَقِيقٍ قَالَ:  قُلْتُ لِعَائِشَةَ: أَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى؟ قَالَتْ: لَا، إِلَّا أَنْ يَجِيءَ مِنْ مَغِيبِهِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (717) عن يحيى بن يحيى، أخبرنا يزيد بن زُريع، عن سعيد الجُريري، عن عبدالله بن شقيق به مثله.","grade":"صحيح","chapter_ar":"باب من رأى أنَّ صلاة الضُحى إذا رجع من السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Muslim (717).","chapter_en":"Those who held that the Ḍuḥā prayer is (especially) prayed when one returns from travel.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":3,"content":{"translation":{"en":["‘Abdullāh ibn Shaqīq said: I said to ‘Ā’ishah: Did the Prophet ﷺ use to pray Ḍuḥā? She said: No—except when he returned from his absence (i.e., from travel)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (717)."},{"num":2940,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ يُصَلِّي الضُّحَى إِلَّا أَنْ يَقْدَمَ مِنْ غَيْبَةٍ."],"takhrij":"حسن: رواه ابن خزيمة (1229) عن إسحاق بن إبراهيم الصّواف، نا سالم بن نوح العطار، أخبرنا عبيدالله، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب من رأى أنَّ صلاة الضُحى إذا رجع من السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Ibn Khuzaymah (1229) and Ibn Ḥibbān (2528).","chapter_en":"Those who held that the Ḍuḥā prayer is (especially) prayed when one returns from travel.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ would not pray Ḍuḥā except when he arrived back from an absence (i.e., returned from travel)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (1229)، وابن حبان (2528)."},{"num":2941,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنَّهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ صَلَّى سُبْحَةَ الضُّحَى ثَمَانِ رَكَعَاتٍ، فَلَمَّا انْصَرَفَ قَالَ: إِنِّي صَلَّيْتُ صَلَاةَ رَغْبَةٍ وَرَهْبَةٍ، سَأَلْتُ رَبِّي ثَلَاثًا، فَأَعْطَانِي ثِنْتَيْنِ، وَمَنَعَنِي وَاحِدَةً: سَأَلْتُه أَنْ لَا يَبْتَلِيَ أُمَّتِي بِالسِّنِينَ، فَفَعَلَ. وَسَأَلْتُهُ أَنْ لَا يُظْهِرَ عَلَيْهِمْ عَدُوَّهُمْ، فَفَعَلَ، وَسَأَلْتُهُ أَنْ لَا يَلْبِسَهُمْ شِيَعًا، فَأَبَى عَلَيَّ."],"takhrij":"حسن: رواه أحمد (12486)، والنسائي في السنن الكبرى (489) كلاهما من طريق عمرو بن الحارث، عن بكير بن الأشج، أن الضحاك بن عبدالله القرشي حدَّثه، عن أنس بن مالك فذكره. وصحّحه ابن خزيمة (1228)، والحاكم (1183).","grade":"حسن","chapter_ar":"باب من رأى أنَّ صلاة الضُحى إذا رجع من السَّفر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Aḥmad (12486) and al-Nasā’ī in al-Kubrā (489); Ibn Khuzaymah authenticated it (1228).","chapter_en":"Those who held that the Ḍuḥā prayer is (especially) prayed when one returns from travel.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik said: I saw the Messenger of Allah ﷺ on a journey pray the voluntary Ḍuḥā prayer as eight rak‘ahs. When he finished, he said: “I prayed a prayer of hope and fear. I asked my Lord for three things: He granted me two and withheld one. I asked Him not to afflict my ummah with years (of drought/famine), and He did so. I asked Him not to allow their enemy to overcome them, and He did so. And I asked Him not to split them into sects, but He refused that for me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12486)، والنسائي في الكبرى (489) وصححه ابن خزيمة (1228)."},{"num":2942,"demo":false,"sanad":"","matn":["عَنْ مُوَرِّقٍ، قَالَ: قُلْتُ لاِبْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَتُصَلِّي الضُّحَى؟ قَالَ: لاَ. قُلْتُ: فَعُمَرُ. قَالَ: لاَ. قُلْتُ: فَأَبُو بَكْرٍ. قَالَ: لاَ. قُلْتُ: فَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ إِخَالُهُ."],"takhrij":"صحيح: رواه البخاري في التهجد (1175) عن مسدد، قال: حدثنا يحيى، عن شعبة، عن توبة، عن مورِّق به مثله.","grade":"صحيح","chapter_ar":"باب من لم يرَ سُنِّيَّة صلاة الضُحى أصلاً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Bukhārī (1175).","chapter_en":"Those who did not consider the Ḍuḥā prayer to be legislated at all (as a regular practice).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":4,"content":{"translation":{"en":["Mawriq said: I said to Ibn ‘Umar (may Allah be pleased with them both): Do you pray Ḍuḥā? He said: No. I said: And ‘Umar? He said: No. I said: And Abū Bakr? He said: No. I said: And the Prophet ﷺ? He said: I do not think so."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1175)."},{"num":2943,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن أَبِي بَكْرَةَ، أَنَّ أَبَاهُ رَأَى أُنَاسًا يُصَلُّونَ صَلَاةَ الضُّحَى فَقَالَ: أَمَا إنَّهم يُصَلُّونَ صَلَاةً مَا صَلَّاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا عامَّة أَصْحَابِهِ."],"takhrij":"حسن: رواه الدارمي (1463)، والنسائي في الكبرى (480) كلاهما من حديث معاذ بن معاذ، قال: حدثني شعبة، عن فُضيل بن فضالة، حدثني عبدالرحمن بن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب من لم يرَ سُنِّيَّة صلاة الضُحى أصلاً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by al-Dārimī (1463) and al-Nasā’ī in al-Kubrā (480).","chapter_en":"Those who did not consider the Ḍuḥā prayer to be legislated at all (as a regular practice).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":4,"content":{"translation":{"en":["‘Abd al-Raḥmān ibn Abī Bakrah reported that his father saw some people praying the Ḍuḥā prayer and said: Indeed, they are praying a prayer that the Messenger of Allah ﷺ did not pray, nor did the majority of his Companions."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارمي (1463)، والنسائي في الكبرى (480)."},{"num":2944,"demo":false,"sanad":"","matn":["عن زَيْدِ بن أَرْقَمَ رَأَى قَوْمًا يُصَلُّونَ مِنَ الضُّحَى فَقَالَ: أَمَا لَقَدْ عَلِمُوا أَنَّ الصَّلَاةَ فِي غَيْرِ هَذِهِ السَّاعَةِ أَفْضَلُ؟! إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: صَلَاةُ الْأَوَّابِينَ حِينَ تَرْمَضُ الْفِصَالُ.","وفي رواية: خَرَجَ رَسُولُ اللهِ صلى الله عليه وسلم عَلَى أَهْلِ قُبَاءٍَ، وَهُمْ يُصَلُّونَ. فَقَالَ: صَلَاةُ الْأَوَّابِينَ إِذَا رَمِضَتِ الْفِصَالُ .."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (748) الرواية الأولى من طريق إسماعيل بن علية، عن أيوب، عن القاسم الشيباني، عن زيد بن أرقم فذكره، والرواية الثانية من طريق يحيى بن سعيد، عن هشام بن أبي عبدالله قال: حدثنا القاسم به فذكره. والقاسم هو: ابن عوف الشيباني، قال فيه أبو حاتم: مضطرب الحديث ومحله عندي الصدق . ورآه شعبة وتركه ولم يَروِ عنه.","grade":"صحيح","chapter_ar":"باب صلاة الأوابين هي الضُحى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Muslim (748).","chapter_en":"The Prayer of the Oft-Returning (Ṣalāt al-Awwābīn) is the Ḍuḥā prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":5,"content":{"translation":{"en":["Zayd ibn Arqam saw some people praying Ḍuḥā and said: They certainly know that praying at a time other than this hour is better. The Messenger of Allah ﷺ said: “The prayer of the oft-returning (al-Awwābīn) is when the young camels’ hooves are burned by the hot sand.” In another narration: The Messenger of Allah ﷺ went out to the people of Qubā’ while they were praying and said: “The prayer of al-Awwābīn is when the young camels’ hooves are scorched.”"]},"buhuth":{"en":["His statement “al-awwāb” means: the obedient one; and it is also said: the one who repeatedly returns to obedience. “Tarmaḍu” means: to be burned/scorched (as in the verb pattern “ʿalima yaʿlam”), and “ar-ramḍā’” is the sand whose heat has become intense. “Al-fiṣāl” is the plural of “faṣīl,” meaning a young camel that has been weaned from its mother and no longer needs nursing. Meaning: when the hooves of the young camels burn because of the intense heat of the sand under the sun.","From this, they inferred that delaying the Ḍuḥā prayer until the heat becomes intense is better."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (748)."},{"num":2945,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ ، قَالَ: : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لا يُحَافِظُ عَلَى صَلاةِ الضُّحَى إِلا أَوَّابٌ. قَالَ: : وَهِيَ صَلاةُ الأَوَّابِينَ."],"takhrij":"حسن: رواه ابن خزيمة (1224) عن محمد بن يحيى، نا إسماعيل بن عبدالله بن زرارة الرقى ببغداد، ثنا خالد بن عبدالله، وحدثني محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب صلاة الأوابين هي الضُحى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Ibn Khuzaymah (1224).","chapter_en":"The Prayer of the Oft-Returning (Ṣalāt al-Awwābīn) is the Ḍuḥā prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “No one consistently maintains the Ḍuḥā prayer except one who is an awwāb.” He said: “And it is the prayer of al-Awwābīn.”"]}},"tuhfa":{},"voc":["ibnkhuzaymah",1227],"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (1224)."},{"num":2946,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ عَبَسَة السلمي قَالَ: يَا نَبِيَّ اللَّهِ، أَخْبِرْنِي عَمَّا عَلَّمَكَ اللَّهُ وَأَجْهَلُهُ، أَخْبِرْنِي عَنِ الصَّلَاةِ. قَالَ: صَلِّ صَلَاةَ الصُّبْحِ، ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ حَتَّى تَطْلُعَ الشَّمْسُ، حَتَّى تَرْتَفِعَ، فَإِنَّهَا تَطْلُعُ حِينَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ. ثُمَّ صَلِّ، فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (832) في قصة إسلام عمرو بن عبسة، وقد تقدَّم في كتاب الطهارة، باب ثواب الوضوء.","grade":"صحيح","chapter_ar":"باب ماجاء في أداء ركعتين بعد طلوع الشمس والتي يسمِّيها البعض صلاة الإشراق وهي الضحى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Muslim (832). His words “witnessed and attended” mean: the angels witness it, and the people of obedience attend it.","chapter_en":"Performing two rakʿahs after sunrise, which some call the Ishrāq prayer; it is (in essence) Ḍuḥā.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الضُحى","group_en":"Combined chapters on the Ḍuḥā (forenoon) prayer.","part_no":9,"group_no":20,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn ʿAbasah al-Sulamī said: O Prophet of Allah ﷺ, inform me of what Allah has taught you and what I do not know. Tell me about the prayer. He said: “Pray the morning prayer (Ṣalāt al-Ṣubḥ), then refrain from prayer until the sun rises and becomes elevated, for it rises when it rises between the two horns of Shayṭān, and at that time the disbelievers prostrate to it. Then pray, for the prayer is witnessed and attended.”"]},"buhuth":{"en":["And his words “until it becomes elevated” resemble the beginning time of Ḍuḥā; Shaykh Ibn Bāz (may Allah have mercy on him) affirmed that the Ishrāq prayer is the Ḍuḥā prayer at its earliest time, and that it is better to do it when the Ḍuḥā has risen higher. (Majmūʿ Fatāwā, 11/401)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (832). وقوله: مشهودة ومحضورة: أي يشهدها الملائكة، ويحضرها أهل الطاعات."},{"num":2947,"demo":false,"sanad":"","matn":["عَنْ إسحاق بْنِ عبدالله بن كِنَانَةَ قَالَ: أَرْسَلَنِي الْوَلِيدُ بْنُ عُتْبَةَ (وهو: ابْنُ أَبِي سُفْيَانَ بن حَرْبٍ وَكَانَ أَمِيرَ الْمَدِينَةِ لعمِّه معاوية) إِلَى ابْنِ عَبَّاسٍ أَسْأَلُهُ عَنْ صَلاَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الاِسْتِسْقَاءِ. فَقَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتبذِّلاً مُتَوَاضِعًا متضرِّعاً، حَتَّى أَتَى الْمُصَلَّى، فرقى الْمِنْبَرِ، فَلَمْ يَخْطُبْ خُطَبَكم هَذِهِ، وَلَكِنْ لَمْ يزلْ فِي الدُّعَاءِ وَالتَّضَرُّعِ وَالتَّكْبِيرِ، وصَلَّى رَكْعَتَيْنِ كَمَا يُصلِّي فِي الْعِيدِ."],"takhrij":"حسن: رواه أبو داود (1165)، والترمذي (558)، والنسائي (1508)، وابن ماجة (1266) كلهم من طريق هشام بن إسحاق بن عبدالله بن كِنانة، عن أبيه فذكره. وزاد ابن ماجة: متخشِّعاً مترسِّلاً .","grade":"حسن","chapter_ar":"باب التواضع والتبذل والتخشع والتضرُّع عند الخروج إلى الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Abū Dāwūd (1165), al-Tirmidhī (558), al-Nasā’ī (1508), and Ibn Mājah (1266).","chapter_en":"Humility, leaving adornment, showing خشوع (reverent submissiveness), and earnest supplication when going out for the rain prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":1,"content":{"translation":{"en":["Isḥāq ibn ʿAbdullāh ibn Kinānah said: al-Walīd ibn ʿUtbah (ʿUtbah was the son of Abū Sufyān ibn Ḥarb, and al-Walīd was the governor of Madīnah for his uncle Muʿāwiyah) sent me to Ibn ʿAbbās to ask him about the Messenger of Allah’s ﷺ prayer for rain (istisqā’). He said: The Messenger of Allah ﷺ went out leaving adornment, humble, and imploring (Allah), until he reached the prayer place. He ascended the minbar but did not deliver a sermon like this sermon of yours; rather, he continued making supplication, imploring, and saying takbīr, and he prayed two rakʿahs as he prays on ʿĪd."]},"buhuth":{"en":["Ibn Mājah added: “showing humility and proceeding in a calm, unhurried manner.” al-Tirmidhī said: “Ḥasan Ṣaḥīḥ.”","And “at-tabadhdhul” means: leaving adornment as an expression of humility.","Description of the rain prayer, and that it is performed without adhān and without iqāmah:","The majority who hold that istisqā’ is legislated did not differ that it is prayed like the ʿĪd prayer: two rakʿahs with no adhān and no iqāmah, and that it begins with the prayer before the sermon, as is established in many narrations. Some of those narrations will be mentioned later, because these narrations were cited scattered across different chapters."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1165)، والترمذي (558)، والنسائي (1508)، وابن ماجه (1266)."},{"num":2948,"demo":false,"sanad":"","matn":["عن عَبَّاد بن تَمِيمٍ، عَنْ عَمِّهِ، قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمُصَلَّى يَسْتَسْقِي، وَاسْتَقْبَلَ الْقِبْلَةَ فَصَلَّى رَكْعَتَيْنِ، وَقَلَبَ رِدَاءَهُ.","قَالَ سُفْيَانُ: فَأَخْبَرَنِي الْمَسْعُودِيُّ، عَنْ أَبِي بَكْرٍ قَالَ: \"جَعَلَ الْيَمِينَ عَلَى الشِّمَالِ\"."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1027) عن عبدالله بن محمد، ومسلم في الاستسقاء (894/2) عن يحيى بن يحيى، كلاهما عن سفيان، عن عبدالله بن أبي بكر، سمع عباد بن تميم، عن عمه فذكره. واللَّفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الصلاة قبل الخطبة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī in al-Istisqā’ (1027) and Muslim (894). The wording is al-Bukhārī’s.","chapter_en":"What has been reported that the prayer comes before the sermon.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":2,"content":{"translation":{"en":["ʿAbbād ibn Tamīm, from his uncle, said: The Prophet ﷺ went out to the prayer-place (al-muṣallā) seeking rain. He faced the qiblah and prayed two rakʿahs, and he turned his cloak around. Sufyān said: al-Masʿūdī informed me, from Abū Bakr, who said: He placed the right side over the left."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2966],"tks":"متفق عليه: رواه البخاري (1027)، ومسلم (894/2). واللفظ للبخاري."},{"num":2949,"demo":false,"sanad":"","matn":["عَنْ عَبَّادِ بْنِ تَمِيمٍ، عَنْ عَمِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ بِالنَّاسِ لِيَسْتَسْقِيَ فَصَلَّى بِهِمْ رَكْعَتَيْنِ جَهَرَ بِالْقِرَاءَةِ فِيهِمَا وَحَوَّلَ رِدَاءَهُ، وَرَفَعَ يَدَيْهِ، فَدَعَا وَاسْتَسْقَى، وَاسْتَقْبَلَ الْقِبْلَةَ."],"takhrij":"صحيح: رواه أبو داود (1161)، والترمذي (556)، وعبد الرزاق (4889)، وأحمد (16437) كلهم من حديث معمر، عن الزهري، عن عباد بن تميم، عن عمه فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء أن الصلاة قبل الخطبة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Abū Dāwūd (1161), al-Tirmidhī (556), and Aḥmad (16437). al-Tirmidhī said: “Ḥasan Ṣaḥīḥ.”","chapter_en":"What has been reported that the prayer comes before the sermon.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":2,"content":{"translation":{"en":["ʿAbbād ibn Tamīm, from his uncle, reported that the Messenger of Allah ﷺ went out with the people to seek rain. He led them in two rakʿahs, reciting aloud in them, and he turned his cloak around. He raised his hands and supplicated, seeking rain, while facing the qiblah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1161)، والترمذي (556)، وأحمد (16437) قال الترمذي: ((حسن صحيح))."},{"num":2950,"demo":false,"sanad":"","matn":["عَنْ عَبَّادِ بْنِ تَمِيمٍ، عَنْ عَمِّهِ، قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَسْقِي، فَتَوَجَّهَ إِلَى الْقِبْلَةِ، يَدْعُو، وَحَوَّلَ رِدَاءَهُ، ثُمَّ صَلَّى رَكْعَتَيْنِ جَهَرَ فِيهِمَا بِالْقِرَاءَةِ."],"takhrij":"صحيح: رواه البخاري في الاستسقاء (1024) عن أبي نعيم، حدثنا ابن","grade":"صحيح","chapter_ar":"باب الخطبة قبل الصلاة والجهر بالقراءة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Bukhārī (1024).","chapter_en":"The sermon before the prayer, and reciting aloud in it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":3,"content":{"translation":{"en":["ʿAbbād ibn Tamīm, from his uncle, said: The Prophet ﷺ went out seeking rain, turned to face the qiblah making duʿā’, and turned his cloak around, then he prayed two rakʿahs reciting aloud in them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1024)."},{"num":2951,"demo":false,"sanad":"","matn":["عن عباد بن تَمِيمٍ يَقُولُ: سَمِعْتُ عَبْدَ اللَّهِ بْنَ زَيْدٍ الْمَازِنِيَّ يَقُولُ:  خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمُصَلَّى فَاسْتَسْقَى. وَحَوَّلَ رِدَاءَهُ حِينَ اسْتَقْبَلَ الْقِبْلَةَ."],"takhrij":"متفق عليه: رواه مالك في الاستسقاء (1) عن عبدالله بن أبي بكر بن عمرو بن حزم، أنه سمع عباد بن تميم فذكره. ورواه مسلم في الاستسقاء (894) عن يحيى بن يحيى، عن مالك به مثله. ورواه البخاري في الاستسقاء (1028) من وجه آخر عن أبي بكر بن محمد، عن عباد بن تميم به نحوه.","grade":"متفق عليه","chapter_ar":"باب الخطبة قبل الصلاة والجهر بالقراءة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik (1), Muslim (894), and al-Bukhārī (1028).","chapter_en":"The sermon before the prayer, and reciting aloud in it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":3,"content":{"translation":{"en":["ʿAbbād ibn Tamīm said: I heard ʿAbdullāh ibn Zayd al-Māzinī say: The Messenger of Allah ﷺ went out to the muṣallā to seek rain, and he turned his cloak around when he faced the qiblah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1) ومسلم (894) والبخاري (1028)."},{"num":2952,"demo":false,"sanad":"","matn":["عَنْ أَبِي إِسْحَاقَ قال: خَرَجَ عَبْدُ الله بْنُ يَزِيدَ الْأَنْصَارِيُّ وَخَرَجَ مَعَهُ الْبَرَاءُ بْنُ عَازِبٍ وَزَيْدُ بْنُ أَرْقَمَ رَضِيَ اللَّهُ عَنْهُمْ فَاسْتَسْقَى، فَقَامَ بِهِمْ عَلَى رِجْلَيْهِ عَلَى غَيْرِ مِنْبَرٍ، فَاسْتَغْفَرَ، ثُمَّ صَلَّى رَكْعَتَيْنِ يَجْهَرُ بِالْقِرَاءَةِ وَلَمْ يُؤَذِّنْ وَلَمْ يُقِمْ.","قَالَ أَبُو إِسْحَاقَ: وَرَأَى عَبْدُ الله بْنُ يَزِيدَ الْأَنْصَارِيُّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"صحيح: رواه البخاري في الاستسقاء (1022) عن أبي نعيم، عن زهير، عن أبي إسحاق قال: فذكره.","grade":"صحيح","chapter_ar":"باب الخطبة قبل الصلاة والجهر بالقراءة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Bukhārī (1022).","chapter_en":"The sermon before the prayer, and reciting aloud in it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":3,"content":{"translation":{"en":["Abū Isḥāq said: ʿAbdullāh ibn Yazīd al-Anṣārī went out, and with him went al-Barā’ ibn ʿĀzib and Zayd ibn Arqam (may Allah be pleased with them). He sought rain (istisqā’), and he stood with them on his feet without a minbar. He sought forgiveness, then prayed two rakʿahs reciting aloud, and he did not call the adhān and did not establish the iqāmah.","Abū Isḥāq said: And ʿAbdullāh ibn Yazīd al-Anṣārī had seen the Prophet ﷺ."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1022)."},{"num":2953,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: شَكَى النَّاسُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُحُوطَ الْمَطَرِ! فَأَمَرَ بِمِنْبَرٍ، فَوُضِعَ لَهُ فِي الْمُصَلَّى، وَوَعَدَ النَّاسَ يَوْمًا يَخْرُجُونَ فِيهِ، قَالَتْ عَائِشَةُ: فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ بَدَا حَاجِبُ الشَّمْسِ، فَقَعَدَ عَلَى الْمِنْبَرِ، فَكَبَّرَ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَمِدَ اللَّهَ عَزَّ وَجَلَّ، ثُمَّ قَالَ: إِنَّكُمْ شَكَوْتُمْ جَدْبَ دِيَارِكُمْ، وَاسْتِئْخَارَ الْمَطَرِ عَنْ إِبَّانِ زَمَانِهِ عَنْكُمْ، وَقَدْ أَمَرَكُمُ اللَّهُ عَزَّ وَجَلَّ أَنْ تَدْعُوهُ، وَوَعَدَكُمْ أَنْ يَسْتَجِيبَ لَكُمْ. ثُمَّ قَالَ: { الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ * الرَّحْمَنِ الرَّحِيمِ * مَلِكِ يَوْمِ الدِّينِ } لاَ إِلَهَ إِلاَّ اللَّهُ، يَفْعَلُ مَا يُرِيدُ، اللَّهُمَّ! أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ، أَنْزِلْ عَلَيْنَا الْغَيْثَ، وَاجْعَلْ مَا أَنْزَلْتَ لَنَا قُوَّةً وَبَلاَغًا إِلَى حِينٍ. ثُمَّ رَفَعَ يَدَيْهِ، فَلَمْ يَزَلْ فِي الرَّفْعِ، حَتَّى بَدَا بَيَاضُ إِبْطَيْهِ، ثُمَّ حَوَّلَ عَلَى النَّاسِ ظَهْرَهُ، وَقَلَّبَ أَوْ حَوَّلَ رِدَاءَهُ وَهُوَ رَافِعٌ يَدَيْهِ، ثُمَّ أَقْبَلَ عَلَى النَّاسِ وَنَزَلَ، فَصَلَّى رَكْعَتَيْنِ، فَأَنْشَأَ اللَّهُ سَحَابَةً، فَرَعَدَتْ وَبَرَقَتْ، ثُمَّ أَمْطَرَتْ بِإِذْنِ اللَّهِ، فَلَمْ يَأْتِ مَسْجِدَهُ حَتَّى سَالَتِ السُّيُولُ، فَلَمَّا رَأَى سُرْعَتَهُمْ إِلَى الْكِنِّ ضَحِكَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ نَوَاجِذُهُ فَقَالَ: أَشْهَدُ أَنَّ اللَّهَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ، وَأَنِّي عَبْدُ اللَّهِ وَرَسُولُهُ."],"takhrij":"حسن: رواه أبو داود (1173) عن هارون بن سعيد الإيلي، حدثنا خالد ابن نِزَار، حدثني القاسم بن مبرور، عن يونس، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب من أدعية الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Abū Dāwūd (1173).","chapter_en":"From the supplications of seeking rain (istisqā’).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":4,"content":{"translation":{"en":["ʿĀ’ishah said: The people complained to the Messenger of Allah ﷺ about drought and lack of rain. So he ordered that a minbar be set up for him in the muṣallā, and he appointed a day for the people to go out. ʿĀ’ishah said: The Messenger of Allah ﷺ went out when the edge of the sun appeared, and he sat upon the minbar. He said takbīr and praised Allah, Mighty and Majestic, then said: “You have complained of the barrenness of your lands and the delay of the rain from its usual season for you, and Allah, Mighty and Majestic, has commanded you to call upon Him and promised you that He will respond to you.” Then he said: “Praise be to Allah, Lord of the worlds, the Most Compassionate, the Most Merciful, Master of the Day of Judgment. There is no deity but Allah; He does whatever He wills. O Allah, You are Allah; there is no deity but You. You are the Rich and we are the poor. Send down rain upon us, and make what You send down for us a strength and provision until a time.” Then he raised his hands and continued raising them until the whiteness of his armpits could be seen. Then he turned his back to the people and turned (or reversed) his cloak while his hands were raised. Then he faced the people again and came down, and he prayed two rakʿahs. Allah then produced a cloud, which thundered and flashed with lightning, then it rained by Allah’s permission. He did not reach the mosque before the streams began to flow. When he saw how quickly they hurried to shelter, he laughed until his molar teeth showed and said: “I bear witness that Allah is capable of all things, and that I am Allah’s servant and messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11078],"tks":"حسن: رواه أبو داود (1173)."},{"num":2954,"demo":false,"sanad":"","matn":["عَنْ شُرَحْبِيلَ بْنِ السِّمْطِ، أَنَّهُ قَالَ لِكَعْبٍ: يَا كَعْبُ بْنَ مُرَّةَ! حَدِّثْنَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاحْذَرْ. قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! اسْتَسْقِ اللَّهَ، فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ فَقَالَ: اللَّهُمَّ اسْقِنَا غَيْثًا مَرِيئًا مَرِيعًا طَبَقًا عَاجِلاً غَيْرَ رَائِثٍ، نَافِعًا غَيْرَ ضَارٍّ. قَالَ: فَمَا جَمَّعُوا حَتَّى أُجِيبُوا. قَالَ: فَأَتَوْهُ فَشَكَوْا إِلَيْهِ الْمَطَرَ، فَقَالُوا: يَا رَسُولَ اللَّهِ: تَهَدَّمَتِ الْبُيُوتُ. فَقَالَ: اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا. قَالَ: فَجَعَلَ السَّحَابُ يَنْقَطِعُ يَمِينًا وَشِمَالاً."],"takhrij":"صحيح: رواه ابن ماجة (1269) عن أبي كُريب، قال: حدثنا أبو معاوية، عن الأعمش، عن عمرو بن مُرَّة، عن سالم بن أبي الجعد، عن شُرحبيل بن السِّمْط فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من أدعية الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Ibn Mājah (1269). It was also narrated by Imām Aḥmad (18061) in a longer context, and in it: “widespread, pouring (ghadaqan).”","chapter_en":"From the supplications of seeking rain (istisqā’).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":4,"content":{"translation":{"en":["Shurayḥbīl ibn al-Simṭ said to Kaʿb ibn Murrah: “O Kaʿb ibn Murrah, narrate to us from the Messenger of Allah ﷺ, and be cautious.” He said: A man came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, ask Allah for rain for us.” So the Messenger of Allah ﷺ raised his hands and said: “O Allah, grant us rain that is wholesome and pleasant, abundant and fertile, widespread, immediate and not delayed—beneficial and not harmful.” He said: They had not yet dispersed when they were covered (by rain). Then they came to him and complained about the rain and said: “O Messenger of Allah ﷺ, the houses have collapsed.” So he said: “O Allah, around us and not upon us.” He said: Then the clouds began to break apart to the right and to the left."]},"buhuth":{"en":["Explanation of terms:","“marīʿan”: fertile, lush, bringing plentiful growth.","“ṭabaqan”: widespread, covering and filling the land like a layer or cover.","“ghadaqan”: heavy, copious rain with large drops.","“ghayra rā’ith”: not delayed and not slow in coming."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11079],"tks":"صحيح: رواه ابن ماجه (1269)، ورواه أيضا الإمام أحمد (18061) في سياق أطول، وفيه: (( طبقا غدقا ))."},{"num":2955,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَوَاكِي، فَقَالَ: اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا مَرِيعاً نَافِعًا غَيْرَ ضَارٍّ، عَاجِلاً غَيْرَ آجِلٍ. قَالَ: فَأَطْبَقَتْ عَلَيْهِمُ السَّمَاءُ."],"takhrij":"صحيح: رواه أبو داود (1169) عن ابن أبي خلف، حدثنا محمد بن عبيد، حدثنا مسعر، عن يزيد الفقير، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب من أدعية الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Abū Dāwūd (1169), and authenticated by Ibn Khuzaymah (1416) and al-Ḥākim (1/327).","chapter_en":"From the supplications of seeking rain (istisqā’).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullah said: People came to the Prophet ﷺ weeping (bawākī). So he said: “O Allah, give us rain that brings relief, wholesome and fertile—beneficial and not harmful—immediate and not delayed.” He said: Then the sky covered them (with rain)."]},"buhuth":{"en":["Explanation of the word: “bawākī” is the plural of “bākiyah” (weeping), meaning people who came weeping, or weeping women."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11080],"tks":"صحيح: رواه أبو داود (1169)، وصححه ابن خزيمة (1416)، والحاكم (1222)."},{"num":2956,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! لَقَدْ جِئْتُكَ مِنْ عِنْدِ قَوْمٍ مَا يَتَزَوَّدُ لَهُمْ رَاعٍ، وَلاَ يَخْطِرُ لَهُمْ فَحْلٌ. فَصَعِدَ الْمِنْبَرَ، فَحَمِدَ اللَّهَ ثُمَّ قَالَ: اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا طَبَقًا مَرِيعًا غَدَقًا، عَاجِلاً غَيْرَ رَائِثٍ. ثُمَّ نَزَلَ فَمَا يَأْتِيهِ أَحَدٌ مِنْ وَجْهٍ مِنَ الْوُجُوهِ إِلاَّ قَالُوا قَدْ أُحْيِينَا."],"takhrij":"صحيح: رواه ابن ماجة (1270) عن محمد بن أبي القاسم أبي الأحوص، قال: حدثنا الحسن بن الربيع، قال: حدثنا عبدالله بن إدريس، قال: حدثنا حصين، عن حبيب بن أبي ثابت، عن ابن عباس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من أدعية الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Ibn Mājah (1270).","chapter_en":"From the supplications of seeking rain (istisqā’).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbās said: A Bedouin came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, I have come to you from a people for whom no shepherd can find provision, and no breeding male (stallion) stirs (to mate).” So he ascended the pulpit, praised Allah, then said: “O Allah, grant us rain that brings relief—wholesome and fertile—copious—immediate and not delayed.” Then he descended, and no one came to him from any direction except that they said: “We have been given life again.”"]}},"tuhfa":{},"full":1,"rep":[11081],"tks":"صحيح: رواه ابن ماجه (1270)."},{"num":2957,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَسْقَى قَالَ: اللَّهُمَّ اسْقِ عِبَادَكَ وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْىِ بَلَدَكَ الْمَيِّتَ."],"takhrij":"حسن: رواه أبو داود (1176) عن سهل بن صالح، حدثنا علي بن قادم، أخبرنا سفيان، عن يحيى بن سعيد، عن عمرو بن شعيب، عن أبيه، عن جده فذكره. وهذا إسناد حسن لأجل عمرو بن شعيب.","grade":"حسن","chapter_ar":"باب من أدعية الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Abū Dāwūd (1176).","chapter_en":"From the supplications of seeking rain (istisqā’).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ said: When the Messenger of Allah ﷺ sought rain, he would say: “O Allah, give drink to Your servants and Your livestock, spread Your mercy, and revive Your dead land.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1176)."},{"num":2958,"demo":false,"sanad":"","matn":["عن عباد بن تَمِيمٍ، أَنَّ عَمَّهُ ـ وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ بِالنَّاسِ يَسْتَسْقِي لَهُمْ، فَقَامَ فَدَعَا اللَّهَ قَائِمًا، ثُمَّ تَوَجَّهَ قِبَلَ الْقِبْلَةِ، وَحَوَّلَ رِدَاءَهُ فَأُسْقُوا."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1023) ومسلم في الاستسقاء (894/4) كلاهما من حديث الزهري، قال: حدثني عباد بن تميم فذكره واللفظ للبخاري ومسلم لم يذكر موضع الشاهد منه.","grade":"متفق عليه","chapter_ar":"باب الدعاء في الاستسقاء قائماً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1023) and Muslim (894).","chapter_en":"Supplicating for rain while standing.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":5,"content":{"translation":{"en":["ʿAbbād ibn Tamīm reported that his uncle—who was among the Companions of the Messenger of Allah ﷺ—told him that the Prophet ﷺ went out with the people to seek rain for them. He stood and supplicated to Allah while standing, then he turned to face the qiblah and turned his cloak around, and they were given rain."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1023) ومسلم (894/4)."},{"num":2959,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَرْفَعُ يَدَيْهِ فِي شَىْءٍ مِنْ دُعَائِهِ إِلاَّ فِي الاِسْتِسْقَاءِ، وَإِنَّهُ يَرْفَعُ حَتَّى يُرَى بَيَاضُ إِبْطَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1031)، ومسلم في الاستسقاء (895/7) كلاهما من طريق ابن عدي، عن سعيد بن أبي عروبة، عن قتادة عن أنس فذكر الحديث واللفظ للبخاري، ولفظ مسلم مثله إلا أنه في رواية عبد الأعلى عن سعيد قال: يُرى بياض إبطه أو بياض إبطيه .","grade":"متفق عليه","chapter_ar":"باب رفع اليدين بالدعاء في الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1031) and Muslim (895).","chapter_en":"Raising the hands in supplication during istisqā’.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik said: The Prophet ﷺ did not raise his hands in any of his supplications except in istisqā’, and he would raise them so high that the whiteness of his armpits could be seen."]},"buhuth":{"en":["Commentary (al-Nawawī’s explanation):","al-Nawawī said in his commentary on Muslim: This ḥadīth, in its apparent wording, gives the impression that the Prophet ﷺ did not raise his hands except in istisqā’. But that is not the case—raising the hands in duʿā’ is authentically established in many situations other than istisqā’, too many to enumerate. Rather, this ḥadīth is interpreted to mean that he did not raise them with such an emphatic, high raising—such that the whiteness of his armpits could be seen—except in istisqā’."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10888],"tks":"متفق عليه: رواه البخاري (1031)، ومسلم (895/7)."},{"num":2960,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَادًّا يَدَيْهِ، حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ.","قَالَ سُلَيْمَانُ: ظَنَنْتُهُ يَدْعُو فِي الِاسْتِسْقَاءِ."],"takhrij":"صحيح: رواه ابن ماجه ( 1271)، وابن خزيمة (1413) كلاهما من طريق سليمان التيمي، عن بركة -وهو أبو الوليد، عن بشير بن نهيك، عن أبي هريرة فذكره. واللفظ لابن خزيمة، وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب رفع اليدين بالدعاء في الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Ibn Mājah (1271) and Ibn Khuzaymah (1413).","chapter_en":"Raising the hands in supplication during istisqā’.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah said: I saw the Messenger of Allah ﷺ stretching out his hands until I could see the whiteness of his armpits. Sulaymān said: I think he was supplicating during istisqā’."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه ابن ماجه (1271)، وابن خزيمة (1413)."},{"num":2961,"demo":false,"sanad":"","matn":["عَنْ عُمَيْرٍ، مَوْلَى آبِي اللَّحْمِ: أَنَّهُ رَأَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَسْقِي عِنْدَ أَحْجَارِ الزَّيْتِ قَرِيبًا مِنَ الزَّوْرَاءِ قَائِمًا، يَدْعُو يَسْتَسْقِي رَافِعًا كَفَّيْهِ، لَا يُجَاوِزُ بِهِمَا رَأْسَهُ مُقْبِلٌ بِبَاطِنِ كَفَّيْهِ إِلَى وَجْهِهِ."],"takhrij":"صحيح: رواه الإمام أحمد (21944) عن هارون بن معروف، قال: قال ابن وهب: أخبرنا حيوة، عن ابن الهاد، عن محمد بن إبراهيم التيمي، عن عمير فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب رفع اليدين بالدعاء في الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Imām Aḥmad (21944), and authenticated by Ibn Ḥibbān (879).","chapter_en":"Raising the hands in supplication during istisqā’.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":6,"content":{"translation":{"en":["ʿUmayr, the freedman of Abī al-Laḥm, reported that he saw the Messenger of Allah ﷺ seeking rain near Aḥjār az-Zayt, close to az-Zawrāʾ, standing and making supplication for rain. He raised his hands, not lifting them above his head, and he faced the palms of his hands toward his face."]},"buhuth":{"en":["Commentary (explaining the place-names):","“Aḥjār az-Zayt”: a location in Madinah in the ḥarrah (lava-stone area). It was called that because its stones are very dark, as if they had been coated with oil.","“Az-Zawrāʾ”: a place that used to be known near the market of Madinah—an elevated spot, like a small cave, close to the mosque. It is no longer known today, and it may have been absorbed into the later expansions of al-Masjid an-Nabawī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (21944)، وقد صححه ابن حبان (879)."},{"num":2962,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: أَتَى رَجُلٌ أَعْرَابِيٌّ مِنْ أَهْلِ الْبَدْوِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْجُمُعَةِ فَقَالَ: يَا رَسُولَ اللَّهِ، هَلَكَتِ الْمَاشِيَةُ، هَلَكَ الْعِيَالُ، هَلَكَ النَّاسُ. فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ يَدْعُو، وَرَفَعَ النَّاسُ أَيْدِيَهُمْ مَعَهُ يَدْعُونَ، قَالَ: فَمَا خَرَجْنَا مِنَ الْمَسْجِدِ حَتَّى مُطِرْنَا، فَمَا زِلْنَا نُمْطَرُ حَتَّى كَانَتِ الْجُمُعَةُ الأُخْرَى، فَأَتَى الرَّجُلُ إِلَى نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، بَشِقَ الْمُسَافِرُ، وَمُنِعَ الطَّرِيقُ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1029) قال: قال أيوب بن سليمان، حدثني أبو بكر بن أبي أويس، عن سليمان، عن بلال، قال يحيى بن سعيد: سمعت أنس بن مالك يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب رفع الأيدي في الاستسقاء مع الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1029) and Muslim (897).","chapter_en":"Raising the hands in istisqāʾ along with the imam.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":7,"content":{"translation":{"en":["Anas said: A Bedouin man came to the Messenger of Allah ﷺ on a Friday and said: “O Messenger of Allah ﷺ! The livestock have perished, the families are suffering, the people are ruined.” So the Messenger of Allah ﷺ raised his hands supplicating, and the people raised their hands with him, supplicating. Anas said: We did not even leave the mosque before we were rained upon, and it continued to rain until the next Friday. Then the man came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ! The traveler has grown weary, and the road has been cut off.”"]},"buhuth":{"en":["Commentary (word clarification):","“Bashiq” means: the traveler became tired or weary. Al-Khaṭṭābī said: rather, the word is “lāʾiq” (with lām), meaning that the road became muddy, and it is said that a garment “lathiqa” when it is dampened by rain."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1029) و مسلم (897)."},{"num":2963,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَسْقَى، فَأَشَارَ بِظَهْرِ كَفَّيْهِ إِلَى السَّمَاءِ."],"takhrij":"صحيح: رواه مسلم في الاستسقاء (896) عن عبد بن حميد، حدثنا الحسن بن موسى، حدثنا حماد بن سلمة، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب جعل ظهر الكفين إلى السماء في دعاء الاستسقاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by Muslim (896).","chapter_en":"Turning the backs of the hands toward the sky in the supplication for rain.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":8,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ sought rain, and he gestured with the backs of his hands toward the sky."]},"buhuth":{"en":["Commentary (al-Nawawī’s explanation):","al-Nawawī said in his commentary on Muslim: A group of our scholars and others said: the Sunnah in every supplication intended to remove a calamity—such as drought and the like—is to raise the hands and turn the backs of the hands toward the sky. But when making duʿāʾ to ask for something and attain it, one turns the palms toward the sky. They used this ḥadīth as evidence."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (896)."},{"num":2964,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! هَلَكَتِ الْمَوَاشِي، وَتَقَطَّعَتِ السُّبُلُ، فَادْعُ اللَّهَ. فَدَعَا اللَّهَ، فَمُطِرْنَا مِنَ الْجُمُعَةِ إِلَى الْجُمُعَةِ، فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، تَهَدَّمَتِ الْبُيُوتُ، وَتَقَطَّعَتِ السُّبُلُ، وَهَلَكَتِ الْمَوَاشِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ عَلَى ظُهُورِ الْجِبَالِ وَالآكَامِ، وَبُطُونِ الأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ.","قَالَ: فَانْجَابَتْ عَنِ الْمَدِينَةِ انْجِيَابَ الثَّوْبِ.","وفي رواية: عَنْ أَنَسِ أَنَّ رَجُلاً دَخَلَ الْمَسْجِدَ يَوْمَ جُمُعَةٍ مِنْ بَابٍ كَانَ نَحْوَ باب دَارِ الْقَضَاءِ - وَرَسُولُ اللَّهِ صلى الله عليه وسلم قَائِمٌ يَخْطُبُ- فَاسْتَقْبَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم قَائِمًا ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ! هَلَكَتِ الأَمْوَالُ، وَانْقَطَعَتِ السُّبُلُ، فَادْعُ اللَّهَ يُغِيثُنَا. فَرَفَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَيْهِ ثُمَّ قَالَ: اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا ..","قَالَ أَنَسٌ: وَلاَ وَاللَّهِ مَا نَرَى فِي السَّمَاءِ مِنْ سَحَابٍ وَلاَ قَزَعَةً، ما بَيْنَنَا وَبَيْنَ سَلْعٍ مِنْ بَيْتٍ وَلاَ دَارٍ. قَالَ: فَطَلَعَتْ مِنْ وَرَائِهِ سَحَابَةٌ مِثْلُ التُّرْسِ، فَلَمَّا تَوَسَّطَتِ السَّمَاءَ انقشرتْ، ثُمَّ أَمْطَرَتْ، فَلاَ وَاللَّهِ مَا رَأَيْنَا الشَّمْسَ سِتًّا، ثُمَّ دَخَلَ رَجُلٌ مِنْ ذَلِكَ الْبَابِ فِي الْجُمُعَةِ - وَرَسُولُ اللَّهِ صلى الله عليه وسلم قَائِمٌ يَخْطُبُ -فَاسْتَقْبَلَهُ قَائِمًا فَقَالَ: يَا رَسُولَ اللَّهِ! هَلَكَتِ الأَمْوَالُ، وَانْقَطَعَتِ السُّبُلُ فَادْعُ اللَّهَ يُمْسِكْهَا عَنَّا. قَالَ: فَرَفَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَيْهِ ثُمَّ قَالَ: اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا... .."],"takhrij":"متفق عليه: الرواية الأولى رواها مالك في الاستسقاء (3) عن شريك بن","grade":"متفق عليه","chapter_ar":"باب دعاء الاستسقاء في خطبة الجمعة من غير استقبال القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: the first narration is in Mālik and al-Bukhārī (1016). The second narration is in al-Bukhārī (1014) and Muslim (897).","chapter_en":"Supplication for rain during the Friday sermon without facing the qiblah.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Mālik said: A man came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ! The livestock have perished and the roads have been cut off, so supplicate to Allah.” So the Messenger of Allah ﷺ supplicated, and we were rained upon from one Friday to the next Friday. Then a man came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ! The houses have collapsed, the roads are cut off, and the livestock are ruined.” So the Messenger of Allah ﷺ said: “O Allah, (let it fall) upon the tops of the mountains and hills, into the valleys, and upon the places where trees grow.”","Anas said: Then it cleared away from Madinah like a garment being pulled aside.","In another narration: A man entered the mosque on a Friday through a door near the door of the courthouse, while the Messenger of Allah ﷺ was standing delivering the sermon. The man faced him while standing and said: “O Messenger of Allah ﷺ! Wealth has been destroyed and the roads have been cut off—supplicate to Allah to give us rain.” So the Messenger of Allah ﷺ raised his hands and said: “O Allah, send us rain! O Allah, send us rain! O Allah, send us rain!” Anas said: By Allah, we did not see in the sky any clouds—not even scattered patches—and there was no house or building between us and (Mount) Salʿ.","He said: Then a cloud rose from behind it like a shield; when it reached the middle of the sky it spread out, and then it rained. By Allah, we did not see the sun for six days. Then a man entered from that same door on the next Friday while the Messenger of Allah ﷺ was standing delivering the sermon. He faced him while standing and said: “O Messenger of Allah ﷺ! Wealth has been destroyed and the roads have been cut off—supplicate to Allah to hold it back from us.” So the Messenger of Allah ﷺ raised his hands and said: “O Allah, around us and not upon us…”"]},"buhuth":{"en":["“Dār al-Qaḍāʾ”: This was the house of ʿUmar ibn al-Khaṭṭāb. It was called “Dār al-Qaḍāʾ” because it was sold to repay a debt he owed. People used to say, “the house used to repay ʿUmar’s debt,” and over time it was shortened to “Dār al-Qaḍāʾ.” Whoever explains it as the governor’s house (Dār al-Imārah) is mistaken.","“Six (ستًّا)”: Meaning, “we did not see the sun for six days.” But in most narrations it is “Sabtan (سبتًا)”, the name of a weekday—meaning, “we did not see the sun for a full week.” Al-Nawawī said: it can also mean “a stretch of time,” since the original sense of “sabt” is “cutting.”","“O Allah, around us (اللهم حوالينا)”: Meaning, divert the rain away from buildings and homes.","“O Allah, upon the hills (اللهم على الآكام)”: “Ākām” is the plural of “akmah” (a raised mound/hill). The hamzah is usually read with kasrah, though it may also be read with fatḥah and lengthening. Al-Khaṭṭābī said it refers to a large hillock; others said a small mountain, and the intent matches the meaning of “around us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: الرواية الأولى رواها مالك (3) والبخاري (1016)."},{"num":2965,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: أَصَابَتِ النَّاسَ سَنَةٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى الْمِنْبَرِ يَوْمَ الْجُمُعَةِ، قَامَ أَعْرَابِيٌّ فَقَالَ: يَا رَسُولَ اللَّهِ، هَلَكَ الْمَالُ، وَجَاعَ الْعِيَالُ، فَادْعُ اللَّهَ لَنَا أَنْ يَسْقِيَنَا. قَالَ: فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ، وَمَا فِي السَّمَاءِ قَزَعَةٌ، قَالَ: فَثَارَ سَحَابٌ أَمْثَالُ الْجِبَالِ، ثُمَّ لَمْ يَنْزِلْ عَنْ مِنْبَرِهِ حَتَّى رَأَيْتُ الْمَطَرَ يَتَحَادَرُ عَلَى لِحْيَتِهِ، قَالَ: فَمُطِرْنَا يَوْمَنَا ذَلِكَ، وَفِي الْغَدِ، وَمِنْ بَعْدِ الْغَدِ، وَالَّذِي يَلِيهِ إِلَى الْجُمُعَةِ الأُخْرَى، فَقَامَ ذَلِكَ الأَعْرَابِيُّ، أَوْ رَجُلٌ غَيْرُهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، تَهَدَّمَ الْبِنَاءُ، وَغَرِقَ الْمَالُ، فَادْعُ اللَّهَ لَنَا. فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ وَقَالَ: اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا. قَالَ فَمَا جَعَلَ يُشِيرُ بِيَدِهِ إِلَى نَاحِيَةٍ مِنَ السَّمَاءِ إِلاَّ تَفَرَّجَتْ، حَتَّى صَارَتِ الْمَدِينَةُ فِي مِثْلِ الْجَوْبَةِ، حَتَّى سَالَ الْوَادِي ـ وَادِي قَنَاةَ ـ شَهْرًا. قَالَ: فَلَمْ يَجِئْ أَحَدٌ مِنْ نَاحِيَةٍ إِلاَّ حَدَّثَ بِالْجَوْدِ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1033)، ومسلم في الاستسقاء (897/9) كلاهما من طريق الأوزاعي قال: حدثنا إسحاق بن عبدالله بن أبي طلحة الأنصاري، قال: حدثني أنس بن مالك فذكره واللفظ للبخاري. ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب دعاء الاستسقاء في خطبة الجمعة من غير استقبال القبلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1033) and Muslim (897), and the wording is al-Bukhārī’s.","chapter_en":"Supplication for rain during the Friday sermon without facing the qiblah.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":9,"content":{"translation":{"en":["Anas said: The people were struck by a year of drought in the time of the Messenger of Allah ﷺ. While the Messenger of Allah ﷺ was delivering the Friday sermon on the pulpit, a Bedouin stood and said: “O Messenger of Allah ﷺ! Wealth has perished and families have gone hungry—supplicate to Allah to give us rain.” So the Messenger of Allah ﷺ raised his hands, and there was not a single patch of cloud in the sky. Then clouds rose like mountains, and he did not step down from his pulpit before I saw rain pouring down upon his beard. We were given rain that day, the next day, the day after that, and the one after it—until the following Friday. Then that Bedouin, or another man, stood and said: “O Messenger of Allah ﷺ! Buildings have collapsed and wealth has been drowned—supplicate to Allah for us.” So the Messenger of Allah ﷺ raised his hands and said: “O Allah, around us and not upon us.” And he did not point with his hand toward any direction in the sky except that it opened up, until Madinah became like a hollow opening, and the valley—Wādī Qanāh—flowed for a month. No one came from any direction except that he spoke of the abundant rain."]},"buhuth":{"en":["In a narration in Muslim: People stood and cried out: “O Prophet of Allah ﷺ! Rain has ceased, the trees have turned reddish (i.e., dried), and the livestock have perished…” and the narration continues. It also mentions: the clouds cleared away from over Madinah and began raining around it, without a single drop falling on Madinah, so I looked at Madinah and it was like a crown-ring surrounded by rain.","In another narration: I saw the clouds tearing apart like a large sheet or cloth when it is folded.","In another narration: The Messenger of Allah ﷺ uncovered part of his garment until the rain touched him. We said: “O Messenger of Allah ﷺ, why did you do that?” He said: “Because it is freshly from its Lord (newly sent by Allah).”","Commentary (vocabulary and clarifications):","“Rain pouring down on his beard”: indicates the roof was made from palm fronds (so rain could come through).","“Like the jawbah (الجوبة)”: a wide, round hollow/opening—here meaning a gap in the clouds. Al-Khaṭṭābī said it can mean a shield (round shape). Al-Nawawī said it means the clouds parted away from Madinah and formed a ring around it, leaving it clear.","“Wādī Qanāh”: a valley of Madinah with cultivated land; it is among Madinah’s well-known valleys."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9700,10973],"tks":"متفق عليه: رواه البخاري (1033)، ومسلم (897/9) واللفظ للبخاري."},{"num":2966,"demo":false,"sanad":"","matn":["عن عَبَّاد بن تَمِيمٍ، عَنْ عَمِّهِ، قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمُصَلَّى يَسْتَسْقِي، وَاسْتَقْبَلَ الْقِبْلَةَ، فَصَلَّى رَكْعَتَيْنِ، وَقَلَبَ رِدَاءَهُ.","قَالَ سُفْيَانُ: فَأَخْبَرَنِي الْمَسْعُودِيُّ، عَنْ أَبِي بَكْرٍ قَالَ: جَعَلَ الْيَمِينَ عَلَى الشِّمَالِ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1027)، ومسلم في الاستسقاء (894/2) كلاهما من طريق سفيان، عن عبدالله بن أبي بكر، سمع عباد بن تميم عن عمه فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحويل الرداء للإمام والمأمومين وصفته","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1027) and Muslim (894), and the wording is al-Bukhārī’s.","chapter_en":"What has been reported about turning the cloak (ridāʾ) for the imam and the congregation, and its manner.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":10,"content":{"translation":{"en":["ʿAbbād ibn Tamīm, from his uncle, said: The Prophet ﷺ went out to the prayer-ground to perform the prayer for rain, faced the qiblah, prayed two rakʿahs, and turned his cloak (ridāʾ). Sufyān said: Al-Masʿūdī informed me, from Abū Bakr, that he said: He placed the right side over the left."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2948],"tks":"متفق عليه: رواه البخاري (1027)، ومسلم (894/2) واللفظ للبخاري."},{"num":2967,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ - وَكَانَ أَحَدَ رَهْطِهِ - وَكَانَ عَبْدُ اللَّهِ بْنُ زَيْدٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ شَهِدَ مَعَهُ أُحُدًا، قَالَ: قَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ اسْتَسْقَى لَنَا أَطَالَ الدُّعَاءَ، وَأَكْثَرَ الْمَسْأَلَةَ، قَالَ: ثُمَّ تَحَوَّلَ إِلَى الْقِبْلَةِ، وَحَوَّلَ رِدَاءَهُ فَقَلَبَهُ ظَهْرًا لِبَطْنٍ، وَتَحَوَّلَ النَّاسُ مَعَهُ."],"takhrij":"حسن: رواه الإمام أحمد (16465) عن يعقوب، قال: حدثنا أبي، عن ابن إسحاق، قال: حدثني عبدالله بن أبي بكر، عن عباد بن تميم الأنصاري، ثم المازني، عن عبدالله بن زيد بن عاصم، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحويل الرداء للإمام والمأمومين وصفته","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Imām Aḥmad (16465).","chapter_en":"What has been reported about turning the cloak (ridāʾ) for the imam and the congregation, and its manner.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Zayd ibn ʿĀṣim—who was from his clan, and ʿAbdullāh ibn Zayd was among the Companions of the Prophet ﷺ and had witnessed Uḥud with him—said: I saw the Messenger of Allah ﷺ when he prayed for rain for us: he lengthened the supplication and increased his earnest asking. Then he turned toward the qiblah, and turned his cloak, flipping it so that its outer side became the inner side, and the people turned with him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16465)."},{"num":2968,"demo":false,"sanad":"","matn":["عَنْ عَبَّادِ بْنِ تَمِيمٍ، الْمَازِنِيُّ ، أَنَّهُ سَمِعَ عَمَّهُ يَقُولُ: وَحَوَّلَ (رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ) رِدَاءَهُ، فَجَعَلَ عِطَافَهُ الْأَيْمَنَ عَلَى عَاتِقِهِ الْأَيْسَرِ، ، وَجَعَلَ عِطَافَهُ الْأَيْسَرَ عَلَى عَاتِقِهِ الْأَيْمَنِ، ، ثُمَّ دَعَا اللَّهَ عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه أبو داود (1163) عن محمد بن عوف، قال: قرأتُ في كتاب عمرو بن الحارث -يعني الحمصي- عن عبدالله بن سالم، عن الزبيدي، عن محمد بن مسلم (ثم أحال أبو داود على الإسناد السابق وقال: ولم يذكر الصلاة يعني عباد بن تميم المازني، عن عمه) فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحويل الرداء للإمام والمأمومين وصفته","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan by corroborating reports: narrated by Abū Dāwūd (1163).","chapter_en":"What has been reported about turning the cloak (ridāʾ) for the imam and the congregation, and its manner.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":10,"content":{"translation":{"en":["ʿAbbād ibn Tamīm, from his uncle, said: The Messenger of Allah ﷺ turned his cloak, placing its right side (ʿiṭāf) over his left shoulder, and placing its left side over his right shoulder, then he supplicated Allah, the Mighty and Majestic."]},"buhuth":{"en":["His statement “al-ʿiṭāf”: Al-Khaṭṭābī said: The word “ʿiṭāf” in its original usage refers to the cloak/ridāʾ itself. It is mentioned here with reference to the ridāʾ because what is meant is one of the two sides/ends of the cloak—what is on a person’s right and what is on the left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1163)."},{"num":2969,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن زَيْدٍ قَالَ: اسْتَسْقَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ خَمِيصَةٌ سَوْدَاءُ، فَأَرَادَ أَنْ يَأْخُذَ بِأَسْفَلِهَا فَيَجْعَلَهُ أَعْلاَهَا، فَلَمَّا ثقُلتْ قَلَبَها عَلَى عَاتِقِهِ."],"takhrij":"حسن: رواه أبو داود (1164)، والنسائي (1507) كلاهما عن قتيبة بن سعيد، حدثنا عبد العزيز، عن عُمارة بن غَزِيَّة، عن عباد بن تميم، عن عبدالله ابن زيد فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحويل الرداء للإمام والمأمومين وصفته","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Abū Dāwūd (1164) and al-Nasāʾī (1507); Ibn Khuzaymah authenticated it (1415).","chapter_en":"What has been reported about turning the cloak (ridāʾ) for the imam and the congregation, and its manner.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Zayd said: The Messenger of Allah ﷺ prayed for rain while wearing a black khamīṣah. He wanted to take its lower part and make it the upper part, but when it felt heavy, he turned it over upon his shoulder."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1164)، والنسائي (1507)، وصححه ابن خزيمة ( 1415)."},{"num":2970,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ كَانَ إِذَا قَحَطُوا اسْتَسْقَى بِالْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ فَقَالَ: اللَّهُمَّ إِنَّا كُنَّا نَتَوَسَّلُ إِلَيْكَ بِنَبِيِّنَا فَتَسْقِينَا، وَإِنَّا نَتَوَسَّلُ إِلَيْكَ بِعَمِّ نَبِيِّنَا فَاسْقِنَا. قَالَ: فَيُسْقَوْنَ."],"takhrij":"صحيح: رواه البخاري في الاستسقاء (1010) عن الحسن بن محمد، حدثنا محمد بن عبدالله الأنصاري، قال: حدثني أبي عبدالله بن المثنَّى، عن ثُمامة بن عبدالله بن أنس، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الاستسقاء ببعض قرابة النبي ﷺ من ذوي الصلاح","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Bukhārī (1010).","chapter_en":"The recommendation of seeking rain through (the duʿāʾ of) some of the Prophet’s ﷺ righteous relatives.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Mālik al-Anṣārī reported that ʿUmar ibn al-Khaṭṭāb, when the people faced drought, would seek rain by asking al-ʿAbbās ibn ʿAbd al-Muṭṭalib to supplicate. He would say: “O Allah, we used to seek a means to You by (the duʿāʾ of) our Prophet ﷺ, and You would give us rain; and now we seek a means to You by (the duʿāʾ of) the uncle of our Prophet ﷺ, so grant us rain.” He said: Then they would be given rain."]}},"tuhfa":{},"full":1,"rep":[10974],"tks":"صحيح: رواه البخاري ( 1010)."},{"num":2971,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ قَالَ: إن قُرَيْشًا لَمَّا اسْتَعْصَوْا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَعَا عَلَيْهِمْ بِسِنِينَ كَسِنيِّ يُوسُفَ، فَأَصَابَهُمْ قحطٌ وجَهْدٌ حَتَّى أَكَلُوا الْعِظَامَ، فَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى مَا بَيْنَهُ وَبَيْنَهَا كَهَيْئَةِ الدُّخَانِ مِنَ الجَهْد، فَأَنْزَلَ اللَّهُ تَعَالَى: ﴿فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ (10) يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ (11)﴾ [سورة الدُّخَانِ: 10-11] قَالَ: فَأُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقِيلَ: يَا رَسُولَ اللَّهِ! اسْتسْقِ اللَّهَ لِمُضَرَ، فَإِنَّهَا قَدْ هَلَكَتْ، قَالَ: لِمُضَرَ؟ إِنَّكَ لَجَرِيءٌ فَاسْتَسْقَى فَسُقُوا. فَنَزَلَتْ: إِنَّكُمْ عَائِدُونَ فَلَمَّا أَصَابَتْهُمُ الرَّفَاهِيَةُ عَادُوا إِلَى حَالِهِمْ حِينَ أَصَابَتْهُمُ الرَّفَاهِيَةُ، فَأَنْزَلَ اللَّهُ عـز وجـل: ﴿يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ﴾ [سورة الدخان: 16] قَالَ: يَعْنِي يَوْمَ بَدْرٍ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4821)، ومسلم في صفات المنافقين (2798/40) كلاهما من طريق أبي معاوية، عن الأعمش، عن مسلم ابن صُبيح، عن مسروق، عن ابن مسعود فذكره واللفظ للبخاري، ولفظ مسلم نحوه باختلاف يسير.","grade":"متفق عليه","chapter_ar":"باب إذا استشفع المشركون بالمسلمين عند القحط","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (4821) and Muslim (2798), and the wording is al-Bukhārī’s.","chapter_en":"When the polytheists seek intercession from the Muslims during drought.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":12,"content":{"translation":{"en":["Ibn Masʿūd said: When Quraysh persisted in stubborn refusal against the Prophet ﷺ, he supplicated against them for years (of hardship) like the years of Yūsuf. They were struck by drought and severe hardship until they ate bones. A man would look up to the sky and see between himself and it something like smoke due to the intensity of hunger and hardship. So Allah the Exalted revealed: “So watch for the Day when the sky will bring forth a visible smoke, covering the people—this is a painful punishment.” (Sūrat al-Dukhān 44:10–11) Then the Messenger of Allah ﷺ was approached and it was said: “O Messenger of Allah ﷺ, ask Allah to send rain for Muḍar, for it has perished.” He said: “For Muḍar? You are indeed bold!” Then he prayed for rain, and they were given rain. Then it was revealed: “Indeed, you will return.” (Sūrat al-Dukhān 44:15) When ease and comfort came to them, they returned to their previous ways, so Allah the Mighty and Majestic revealed: “The Day We seize with the greatest seizure—indeed We are the Avenger.” (Sūrat al-Dukhān 44:16) He said: meaning the Day of Badr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4821)، ومسلم (2798/40) واللفظ للبخاري."},{"num":2972,"demo":false,"sanad":"","matn":["عن عَبْدِ الله بنِ دِينَارٍ قَالَ: سَمِعْتُ ابْنَ عُمَرَ يَتَمَثَّلُ بِشِعْرِ أَبِي طَالِبٍ:","وَأَبْيَضَ يُسْتَسْقَى الْغَمَامُ بِوَجْهِهِ ثِمَالُ الْيَتَامَى عِصْمَةٌ لِلْأَرَامِلِ.","وَقَالَ عُمَرُ بْنُ حَمْزَةَ، حَدَّثَنَا سَالِمٌ، عَنْ أَبِيهِ: رُبَّمَا ذَكَرْتُ قَوْلَ الشَّاعِرِ، وَأَنَا أَنْظُرُ إِلَى وَجْهِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَسْقِي فَمَا يَنْزِلُ حَتَّى يَجِيشَ كُلُّ مِيزَابٍ.","وَأَبْيَضَ يُسْتَسْقَى الْغَمَامُ بِوَجْهِهِ - ثِمَالُ الْيَتَامَى عِصْمَةٌ لِلْأَرَامِلِ."],"takhrij":"صحيح: رواه البخاري في الاستسقاء (1008، 1009) عن عمرو بن علي قال حدثنا أبو قتيبة قال حدثنا عبد الرحمن بن عبد الله بن دينار عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب إذا استشفع المشركون بالمسلمين عند القحط","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (1008, 1009).","chapter_en":"When the polytheists seek intercession from the Muslims during drought.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستسقاء","group_en":"Combined chapters on the prayer for rain (Istisqā’)","part_no":9,"group_no":21,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn Dīnār said: I heard Ibn ʿUmar quoting lines of Abū Ṭālib’s poetry: “And a radiant one by whose face the rain-clouds are sought;","A refuge for orphans, a protection for widows.” And ʿUmar ibn Ḥamzah said: Sālim narrated to us from his father: I would sometimes recall the poet’s words while looking at the Prophet’s face as he was praying for rain, and it would not descend until every waterspout was pouring:","“And a radiant one by whose face the rain-clouds are sought;","A refuge for orphans, a protection for widows.”"]},"buhuth":{"en":["(Commentary)","His phrase “thimāl” (with the “th” sound) means a main support and a place of refuge.","His phrase “a protection for widows” means he shields them from what would harm them. “Widows” is the plural of “widow,” meaning a woman without a husband, and it may also be used figuratively for men."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1009 ،1008)."},{"num":2973,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ البدري قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ الشَّمْسَ وَالْقَمَرَ لاَ يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ مِنَ النَّاسِ، وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ، فَإِذَا رَأَيْتُمُوهُمَا فَقُومُوا فَصَلُّوا ."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1041،1057) وفي بدءِ الخلق (3204)، ومسلم في الكسوف (911) من طرق عن إسماعيل (هو ابن أبي خالد) عن قيس (هو ابن أبي حازم) عن أبي مسعود الأنصاري فذكره.","grade":"متفق عليه","chapter_ar":"باب الأمر بالصّلاة عند الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1041, 1057) and Muslim (911).","chapter_en":"The command to pray at the time of an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":1,"content":{"translation":{"en":["Abū Masʿūd al-Badrī reported that the Prophet ﷺ said: “The sun and the moon do not eclipse because of the death of anyone among people. Rather, they are two signs from the signs of Allah, Mighty and Majestic. If you see them, then stand and pray.”"]},"buhuth":{"en":["In another wording: “The sun eclipsed on the day Ibrāhīm died, and people said: ‘It eclipsed because of Ibrāhīm’s death.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1041،1057)، ومسلم (911)."},{"num":2974,"demo":false,"sanad":"","matn":["عن الْمُغِيرَةِ بن شُعْبَةَ يَقُولُ: انْكَسَفَتِ الشَّمْسُ يَوْمَ مَاتَ إِبْرَاهِيمُ، فَقَالَ النَّاسُ: انْكَسَفَتْ لِمَوْتِ إِبْرَاهِيمَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمُوهُمَا فَادْعُوا اللَّهَ، وَصَلُّوا حَتَّى يَنْجَلِيَ."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1060) وفي الأدب bukhari(6199) مختصراً، ومسلم في الكسوف (915) كلاهما من طريق زائدة قال: حدثنا زياد بن عِلاقة، قال: سمعتُ المغيرة بن شعبة فذكر الحديث واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الأمر بالصّلاة عند الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1060) and Muslim (915), and the wording is al-Bukhārī’s.","chapter_en":"The command to pray at the time of an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":1,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: The sun eclipsed on the day Ibrāhīm died, so people said: “It eclipsed because of Ibrāhīm’s death.” The Messenger of Allah ﷺ said: “The sun and the moon are two signs from the signs of Allah. They do not eclipse due to anyone’s death or life. If you see it, then supplicate to Allah and pray until it clears.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1060)، ومسلم (915) واللفظ للبخاري."},{"num":2975,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ كَانَ يُخْبِرُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. إِنَّ الشَّمْسَ وَالْقَمَرَ لاَ يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ، فَإِذَا رَأَيْتُمُوهَا فَصَلُّوا."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1042)، ومسلم في الكسوف (914) كلاهما من طريق ابن وهب، قال: أخبرني عمرو بن الحارث، أن عبدالرحمن بن القاسم حدَّثه عن أبيه القاسم بن محمد بن أبي بكر الصديق، عن عبدالله بن عمر فذكر الحديث، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب الأمر بالصّلاة عند الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1042) and Muslim (914).","chapter_en":"The command to pray at the time of an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar reported from the Prophet ﷺ: “The sun and the moon do not eclipse due to anyone’s death or life. Rather, they are two signs from the signs of Allah. If you see them, then pray.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1042)، ومسلم (914)."},{"num":2976,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ:  خَسَفَتِ الشَّمْسُ فِي زَمَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ فَزِعًا يَخْشَى أَنْ تَكُونَ السَّاعَةُ. حَتَّى أَتَى الْمَسْجِدَ، فَقَامَ يُصَلِّي بِأَطْوَلِ قِيَامٍ وَرُكُوعٍ وَسُجُودٍ، مَا رَأَيْتُهُ يَفْعَلُهُ فِي صَلَاةٍ قَطُّ، ثُمَّ قَالَ: إِنَّ هَذِهِ الْآيَاتِ الَّتِي يُرْسِلُ اللَّهُ، لَا تَكُونُ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، وَلَكِنَّ اللَّهَ يُرْسِلُهَا يُخَوِّفُ بِهَا عِبَادَهُ، فَإِذَا رَأَيْتُمْ مِنْهَا شَيْئًا، فَافْزَعُوا إِلَى ذِكْرِهِ وَدُعَائِهِ وَاسْتِغْفَارِهِ."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1059)، ومسلم في الكسوف (912) كلاهما عن محمد بن العلاء، قال: حدثنا أبو أسامة، عن بُريد بن عبدالله، عن أبي بردة، عن أبي موسى فذكره ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب الأمر بالصّلاة عند الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1059) and Muslim (912).","chapter_en":"The command to pray at the time of an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":1,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī said: The sun eclipsed during the time of the Messenger of Allah ﷺ. He stood up alarmed, fearing it might be the Hour, until he reached the mosque. He began praying with the longest standing, bowing, and prostration I had ever seen him do in any prayer. Then he said: “These signs that Allah sends are not for the death of anyone or their life. Rather, Allah sends them to instill fear in His servants. If you see anything of them, then rush to His remembrance, supplication, and seeking forgiveness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1059)، ومسلم (912)."},{"num":2977,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ قَالَ: لَمَّا كُسِفتِ الشَّمْسُ عَلَى عهـد رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نُودِيَ: إنَّ الصَّلاَةَ جَامِعَةٌ. فَرَكَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ فِي سَجْدَةٍ، ثُمَّ قَامَ فَرَكَعَ رَكْعَتَيْنِ فِي سَجْدَةٍ، ثُمَّ جَلَسَ، ثُمَّ جُلِّي عَنِ الشَّمْسِ.","قال: وقالت عائشة: ما سجدتُ سجوداً قط كان أطول منها، كذا في البخاري، وفي مسلم: ما ركعت ركوعاً قط ولا سجدتُ سجوداً قط كان أطول منه."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1051)، ومسلم في الكسوف (910) كلاهما من طريق أبي معاوية (وهو شيبان النحوي) عن يحيى بن أبي كثير، عن أبي سلمة، عن عبدالله بن عمرو فذكره.","grade":"متفق عليه","chapter_ar":"باب النداء:  الصلاة جامعة  في الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1051) and Muslim (910).","chapter_en":"Calling out “Prayer is to be gathered for” during an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ said: When the sun eclipsed during the time of the Messenger of Allah ﷺ, it was called out: “Prayer is to be gathered for.” The Prophet ﷺ performed two bowings in the first rakʿah, then he stood and performed two bowings in the second rakʿah, then he sat, and then the eclipse cleared. He said: ʿĀʾishah said: I have never performed any prostration longer than that.","This wording is in al-Bukhārī; in Muslim: I have never performed any bowing nor any prostration longer than it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1051)، ومسلم (910)."},{"num":2978,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: خَسَفَتِ الشَّمْسُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فصلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ، فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ، فَأَطَالَ الرُّكُوعَ، ثُمَّ قَامَ، فَأَطَالَ الْقِيَامَ، وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ، فَأَطَالَ الرُّكُوعَ، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ. ثُمَّ رَفَعَ فَسَجَدَ، ثُمَّ فَعَلَ فِي الرَّكْعَةِ الآخِرة مِثْلَ ذَلِكَ، ثُمَّ انْصَرَفَ وَقَدِ تجلَّتِ الشَّمْسُ. فَخَطَبَ النَّاسَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ: إنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَخْسِفَانِ لِمَوْتِ أَحَدٍ، وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَادْعُوا اللَّهَ، وَكَبِّرُوا وَتَصَدَّقُوا ثُمَّ قَالَ: يَا أُمَّةَ مُحَمَّدٍ! وَاللَّهِ مَا مِنْ أَحَدٍ أَغْيَرُ مِنَ اللَّهِ أَنْ يَزْنِيَ عَبْدُهُ، أَوْ تَزْنِيَ أَمَتُهُ، يَا أُمَّةَ مُحَمَّدٍ! وَاللَّهِ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلاً وَلَبَكَيْتُمْ كَثِيرًا ."],"takhrij":"متفق عليه: رواه مالك في صلاة الكسوف (1) عن هشام بن عروة، عن أبيه، عن عائشة قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب أن صلاة الكسوف أربع ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik (1), al-Bukhārī (1044), and Muslim (901).","chapter_en":"The eclipse prayer consists of four bowings (rukūʿ) within two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":3,"content":{"translation":{"en":["ʿĀʾishah said: The sun eclipsed during the time of the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ led the people in prayer. He stood and prolonged the standing, then bowed and prolonged the bowing. Then he stood again and prolonged the standing, but it was shorter than the first standing. Then he bowed and prolonged the bowing, but it was shorter than the first bowing. Then he raised up and prostrated. He then did the same in the second unit, and then he finished when the sun had cleared. He then addressed the people: he praised Allah and extolled Him, and said: “Indeed, the sun and the moon are two signs from the signs of Allah. They do not eclipse for the death of anyone nor for their life. If you see that, then supplicate to Allah, say takbīr, and give charity.” Then he said: “O Ummah of Muhammad! By Allah, none is more jealous than Allah that His servant should commit fornication, or that His female servant should commit fornication. O Ummah of Muhammad! By Allah, if you knew what I know, you would laugh little and weep much.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1) والبخاري (1044)، ومسلم (901)."},{"num":2979,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، قَالَ: انْخَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ قِيَامًا طَوِيلاً نَحْوًا مِنْ قِرَاءَةِ سُورَةِ الْبَقَرَةِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلاً، وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ سَجَدَ، ثُمَّ قَامَ قِيَامًا طَوِيلاً، وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلاً، وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ سَجَدَ، ثُمَّ انْصَرَفَ وَقَدْ تَجَلَّتِ الشَّمْسُ، فَقَالَ: صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَخْسِفَانِ لِمَوْتِ أَحَدٍ، وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَاذْكُرُوا اللَّهَ. قَالُوا: يَا رَسُولَ اللَّهِ، رَأَيْنَاكَ تَنَاوَلْتَ شَيْئًا فِي مَقَامِكَ، ثُمَّ رَأَيْنَاكَ كَعْكَعْتَ. قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي رَأَيْتُ الْجَنَّةَ، فَتَنَاوَلْتُ عُنْقُودًا، وَلَوْ أَصَبْتُهُ لأَكَلْتُمْ مِنْهُ مَا بَقِيَتِ الدُّنْيَا، وَأُرِيتُ النَّارَ، فَلَمْ أَرَ مَنْظَرًا كَالْيَوْمِ قَطُّ أَفْظَعَ، وَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ. قَالُوا: بِمَ يَا رَسُولَ اللَّهِ؟ قَالَ: بِكُفْرِهِنَّ. قِيلَ: يَكْفُرْنَ بِاللَّهِ؟ قَالَ: يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ كُلَّهُ، ثُمَّ رَأَتْ مِنْكَ شَيْئًا قَالَتْ: مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ."],"takhrij":"متفق عليه: رواه مالك في الكسوف (2) عن زيد بن أسلم، عن عطاء بن يسار، عن عبدالله بن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب أن صلاة الكسوف أربع ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik in the Eclipse chapter (2), al-Bukhārī (1052), and Muslim (907).","chapter_en":"The eclipse prayer consists of four bowings (rukūʿ) within two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: The sun eclipsed during the time of the Messenger of Allah ﷺ. The Messenger of Allah ﷺ prayed and stood for a long standing—about the length of reciting Sūrat al-Baqarah—then bowed for a long bowing. Then he raised and stood for a long standing, but it was shorter than the first. Then he bowed for a long bowing, but it was shorter than the first bowing. Then he prostrated. Then he stood for a long standing, but it was shorter than the first standing. Then he bowed for a long bowing, but it was shorter than the first bowing. Then he raised and stood for a long standing, but it was shorter than the first. Then he bowed for a long bowing, but it was shorter than the first bowing. Then he prostrated. Then he finished, and the sun had cleared. He said: “Indeed, the sun and the moon are two signs from the signs of Allah. They do not eclipse for the death of anyone, nor for their life. If you see that, then remember Allah.” They said: “O Messenger of Allah ﷺ! We saw you reaching for something in your place, then we saw you draw back.” He said: “I was shown Paradise, and I reached for a cluster of grapes. If I had taken it, you would have eaten from it as long as the world remains. And I was shown the Fire, and I have never seen a more dreadful sight than today, and I saw that most of its inhabitants were women.” They said: “Why, O Messenger of Allah ﷺ?” He said: “Because of their kufr.” It was said: “Do they disbelieve in Allah?” He said: “They are ungrateful to their husbands and ungrateful for kindness. Even if you were to treat one of them well for an entire lifetime, then she saw something from you, she would say: ‘I have never seen any good from you at all.’”"]},"buhuth":{"en":["And “kankʿaʿta / كعكعت” comes from takʿakʿaʿa, meaning: to stop, hesitate, and draw back."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2) والبخاري (1052) ومسلم (907)."},{"num":2980,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ قَالَ: لَمَّا كَسَفَتِ الشَّمْسُ عَلَى عهـد رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نُودى: إنَّ الصَّلاَةَ جَامِعَةٌ فَرَكَعَ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ فِي سَجْدَةٍ، ثُمَّ قَامَ، فَرَكَعَ رَكْعَتَيْنِ فِي سَجْدَةٍ، ثُمَّ جلسَ حَتَّى جُلِّي عَنِ الشَّمْسِ."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1051)، ومسلم في الكسوف (910) كلاهما من طريق أبي معاوية عن يحيى بن أبي كثير، عن أبي سلمة، عن عبدالله بن عمرو بن العاص فذكره، وسبق تخريجه.","grade":"متفق عليه","chapter_ar":"باب أن صلاة الكسوف أربع ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1051) and Muslim (910).","chapter_en":"The eclipse prayer consists of four bowings (rukūʿ) within two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ said: When the sun eclipsed during the time of the Messenger of Allah ﷺ, it was called out: “Prayer is to be gathered for.” The Prophet ﷺ bowed twice in one unit, then stood and bowed twice in the next unit, then sat until the sun cleared."]},"buhuth":{"en":["His phrase “two units within one prostration sequence” means: in each rakʿah there are two rukūʿs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1051)، ومسلم (910)."},{"num":2981,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ:  كَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي يَوْمٍ شَدِيدِ الْحَرِّ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَصْحَابِهِ، فَأَطَالَ الْقِيَامَ، حَتَّى جَعَلُوا يَخِرُّونَ، ثُمَّ رَكَعَ فَأَطَالَ، ثُمَّ رَفَعَ فَأَطَالَ، ثُمَّ رَكَعَ فَأَطَالَ، ثُمَّ رَفَعَ فَأَطَالَ، ثُمَّ سَجَدَ سَجْدَتَيْنِ. ثُمَّ قَامَ فَصَنَعَ نَحْوًا مِنْ ذَاكَ. فَكَانَتْ أَرْبَعَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ. ثُمَّ قَالَ: إِنَّهُ عُرِضَ عَلَيَّ كُلُّ شَيْءٍ تُولَجُونَهُ. فَعُرِضَتْ عَلَيَّ الْجَنَّةُ، حَتَّى لَوْ تَنَاوَلْتُ مِنْهَا قِطْفًا أَخَذْتُهُ - أَوْ قَالَ تَنَاوَلْتُ مِنْهَا قِطْفًا - فَقَصُرَتْ يَدِي عَنْهُ، وَعُرِضَتْ عَلَيَّ النَّارُ، فَرَأَيْتُ فِيهَا امْرَأَةً مِنْ بَنِي إِسْرَائِيلَ تُعَذَّبُ فِي هِرَّةٍ لَهَا، رَبَطَتْهَا فَلَمْ تُطْعِمْهَا، وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ، وَرَأَيْتُ أَبَا ثُمَامَةَ عَمْرَو بْنَ مَالِكٍ يَجُرُّ قُصْبَهُ فِي النَّارِ، وَإِنَّهُمْ كَانُوا يَقُولُونَ: إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَخْسِفَانِ إِلَّا لِمَوْتِ عَظِيمٍ. وَإِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ يُرِيكُمُوهُمَا، فَإِذَا خَسَفَا فَصَلُّوا حَتَّى تَنْجَلِيَ."],"takhrij":"صحيح: رواه مسلم في الكسوف (904) عن يعقوب بن إبراهيم الدورقي، حدثنا إسماعيل بن علية، عن هشام الدستوائي، قال: حدثنا أبو الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب أن صلاة الكسوف أربع ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (904).","chapter_en":"The eclipse prayer consists of four bowings (rukūʿ) within two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdillāh said: The sun eclipsed during the time of the Messenger of Allah ﷺ on a day of intense heat. The Messenger of Allah ﷺ prayed with his companions. He prolonged the standing until they began to fall down. Then he bowed and prolonged it, then raised and prolonged it, then bowed again and prolonged it, then raised and prolonged it. Then he performed two prostrations, then stood and did something similar. Thus it was four bowings and four prostrations. Then he said: “Everything you will enter was shown to me. Paradise was shown to me—such that if I had taken a cluster from it, I would have taken it (or he said: I reached for a cluster from it), but my hand fell short of it. And the Fire was shown to me, and I saw in it a woman from the Children of Israel being punished because of a cat: she tied it up, so she neither fed it nor let it eat from the creatures of the earth. And I saw Abū Thumāmah ʿAmr ibn Mālik dragging his intestines in the Fire. And they used to say: the sun and the moon only eclipse for the death of a great person. But they are two signs from the signs of Allah that He shows you; so when they eclipse, pray until it clears.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (904)."},{"num":2982,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ فَصَلَّى لِلنَّاسِ، فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ وَهُوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ وَهُوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ، ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ وَهُوَ دُونَ السُّجُودِ الأَوَّلِ، ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ، وَفَعَلَ فِيهِمَا مِثْلَ ذَلِكَ ثُمَّ سَجَدَ سَجْدَتَيْنِ يَفْعَلُ فِيهِمَا مِثْلَ ذَلِكَ حَتَّى فَرَغَ مِنْ صَلاَتِهِ، ثُمَّ قَالَ: إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ وَإِنَّهُمَا لاَ يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَافْزَعُوا إِلَى ذِكْرِ اللَّهِ عَزَّ وَجَلَّ وَإِلَى الصَّلاَةِ."],"takhrij":"حسن: رواه النسائي (1483) عن محمد بن عبيدالله بن عبد العظيم، قال: حدثني إبراهيم سَبَلان، قال: حدثنا عباد بن عبادٍ المُهلبي، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب أن صلاة الكسوف أربع ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasā’ī (1483).","chapter_en":"The eclipse prayer consists of four bowings (rukūʿ) within two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah said: The sun eclipsed during the time of the Messenger of Allah ﷺ. He stood and prayed for the people. He prolonged the standing, then bowed and prolonged the bowing. Then he stood and prolonged the standing, but it was less than the first standing. Then he bowed and prolonged the bowing, but it was less than the first bowing. Then he prostrated and prolonged the prostration, then he raised up and prostrated again and prolonged it, but it was less than the first prostration. Then he stood and prayed two units, doing the same in them; then he performed two prostrations, doing the same in them, until he finished his prayer. Then he said: “Indeed, the sun and the moon are two signs from the signs of Allah. They do not eclipse for the death of anyone nor for their life. So when you see that, hasten to the remembrance of Allah, the Mighty and Majestic, and to prayer.”"]},"buhuth":{"en":["His statement “he prayed two units” means that in each unit there were two bowings (i.e., two rukūʿs)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1483)."},{"num":2983,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَانْكَسَفَتِ الشَّمْسُ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجُرُّ رِدَاءَهُ حَتَّى دَخَلَ الْمَسْجِدَ، فَدَخَلْنَا، فَصَلَّى بِنَا رَكْعَتَيْنِ، حَتَّى انْجَلَتِ الشَّمْسُ، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الشَّمْسَ وَالْقَمَرَ لاَ يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ، فَإِذَا رَأَيْتُمُوهُمَا فَصَلُّوا، وَادْعُوا، حَتَّى يُكْشَفَ مَا بِكُمْ."],"takhrij":"صحيح: رواه البخاري في الكسوف (1040) عن عمرو بن عون، قال: حدثنا خالد، عن يونس، عن الحسن، عن أبي بكرة فذكره.","grade":"صحيح","chapter_ar":"باب أن صلاة الكسوف أربع ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (1040). He also narrated it (1048), with the addition: “Rather, Allah the Exalted uses them to frighten His servants.”","chapter_en":"The eclipse prayer consists of four bowings (rukūʿ) within two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":3,"content":{"translation":{"en":["Abū Bakrah said: We were with the Messenger of Allah ﷺ when the sun eclipsed. The Prophet ﷺ stood up dragging his cloak until he entered the mosque. We entered as well, and he led us in two units of prayer until the sun cleared. Then the Messenger of Allah ﷺ said: “Indeed, the sun and the moon do not eclipse for the death of anyone. So when you see them, pray and supplicate until what is afflicting you is removed.”"]},"buhuth":{"en":["His phrase “he led us in two units” means: the eclipse prayer is two rakʿahs, but with four rukūʿs in total (two rukūʿs in each rakʿah), as established in the earlier reports."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1040). ورواه أيضا bukhari(1048)، وزاد فيه: ((ولكن الله تعالى يخوف بها عباده ))."},{"num":2984,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن سَمُرَةَ قَالَ: بَيْنَمَا أَنَا أَرْمِي بأَسْهُمي فِي حَيَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذِ انْكَسَفَتِ الشَّمْسُ فنبذتُهنَّ، وَقُلْتُ: لَأَنْظُرَنَّ إِلَى مَا يَحْدُثُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي انْكِسَافِ الشَّمْسِ الْيَوْمَ، فَانْتَهَيْتُ إِلَيْهِ وَهُوَ رَافِعٌ يَدَيْهِ، يَدْعُو ويُكبِّر وَيَحْمَدُ ويُهلِّل. حَتَّى جُلِّي عَنِ الشَّمْسِ، فَقَرَأَ سُورَتَيْنِ، وَرَكَعَ رَكْعَتَيْنِ.","وفي رواية: فَأَتَيْتُهُ وَهُوَ قَائِمٌ فِي الصَّلَاةِ رَافِعٌ يَدَيْهِ، فَجَعَلَ يُسَبِّحُ وَيَحْمَدُ وَيُهَلِّلُ وَيُكَبِّرُ وَيَدْعُو. حَتَّى حُسِرَ عَنْهَا، قَالَ: فَلَمَّا حُسِرَ عَنْهَا قَرَأَ سُورَتَيْنِ، وَصَلَّى رَكْعَتَيْنِ."],"takhrij":"صحيح: رواه مسلم في الكسوف (913) من طرق عن الجُريري، عن أبي العلاء حيان بن عُمير، عن عبدالرحمن بن سمرة، وكان من أصحاب رسول الله صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب أن صلاة الكسوف أربع ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (913).","chapter_en":"The eclipse prayer consists of four bowings (rukūʿ) within two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":3,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Samurah said: While I was shooting my arrows during the lifetime of the Messenger of Allah ﷺ, the sun eclipsed. I threw them down and said: “I will surely see what happens with the Messenger of Allah ﷺ during the eclipse today.” I reached him while he was raising his hands, supplicating, saying takbīr, praising Allah, and saying tahlīl until the sun cleared. Then he recited two sūrahs and prayed two rakʿahs. In another narration: I came to him while he was standing in prayer with his hands raised, and he was saying tasbīḥ, praising Allah, saying tahlīl and takbīr, and making duʿā’, until it cleared. When it cleared, he recited two sūrahs and prayed two units."]},"buhuth":{"en":["His phrase “he prayed two rakʿahs” is understood in light of the earlier narrations: each rakʿah contains two rukūʿs. Since the eclipse prayer was performed only on that occasion, this general wording is understood in light of the detailed reports."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (913)."},{"num":2985,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ. قَالَ:  انْكَسَفَتِ الشَّمْسُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. يَوْمَ مَاتَ إِبْرَاهِيمُ ابْنُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ النَّاسُ: إِنَّمَا انْكَسَفَتْ لِمَوْتِ إِبْرَاهِيمَ. فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِالنَّاسِ سِتَّ رَكَعَاتٍ بِأَرْبَعِ سَجَدَاتٍ، بَدَأَ فَكَبَّرَ، ثُمَّ قَرَأَ فَأَطَالَ الْقِرَاءَةَ، ثُمَّ رَكَعَ نَحْوًا مِمَّا قَامَ، ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ، فَقَرَأَ قِرَاءَةً دُونَ الْقِرَاءَةِ الْأُولَى، ثُمَّ رَكَعَ نَحْوًا مِمَّا قَامَ، ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَقَرَأَ قِرَاءَةً دُونَ الْقِرَاءَةِ الثَّانِيَةِ، ثُمَّ رَكَعَ نَحْوًا مِمَّا قَامَ، ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ، ثُمَّ انْحَدَرَ بِالسُّجُودِ فَسَجَدَ سَجْدَتَيْنِ، ثُمَّ قَامَ فَرَكَعَ أَيْضًا ثَلَاثَ رَكَعَاتٍ، لَيْسَ فِيهَا رَكْعَةٌ إِلَّا الَّتِي قَبْلَهَا أَطْوَلُ مِنَ الَّتِي بَعْدَهَا، وَرُكُوعُهُ نَحْوًا مِنْ سُجُودِهِ، ثُمَّ تَأَخَّرَ وَتَأَخَّرَتِ الصُّفُوفُ خَلْفَهُ، حَتَّى انْتَهَيْنَا. (وَقَالَ أَبُو بَكْرٍ: حَتَّى انْتَهَى إِلَى النِّسَاءِ)، ثُمَّ تَقَدَّمَ وَتَقَدَّمَ النَّاسُ مَعَهُ. حَتَّى قَامَ فِي مَقَامِهِ، فَانْصَرَفَ حِينَ انْصَرَفَ، وَقَدْ آضَتِ الشَّمْسُ. فَقَالَ: يَا أَيُّهَا النَّاسُ إِنَّمَا الشَّمْسُ وَالْقَمَرُ آيَتَانِ مِنْ آيَاتِ اللَّهِ. وَإِنَّهُمَا لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ مِنَ النَّاسِ (وَقَالَ أَبُو بَكْرٍ: لِمَوْتِ بَشَرٍ)، فَإِذَا رَأَيْتُمْ شَيْئًا مِنْ ذَلِكَ فَصَلُّوا حَتَّى تَنْجَلِيَ، مَا مِنْ شَيْءٍ تُوعَدُونَهُ إِلَّا قَدْ رَأَيْتُهُ فِي صَلَاتِي هَذِهِ، لَقَدْ جِيءَ بِالنَّارِ. وَذَلِكُمْ حِينَ رَأَيْتُمُونِي تَأَخَّرْتُ مَخَافَةَ أَنْ يُصِيبَنِي مِنْ لَفْحِهَا. وَحَتَّى رَأَيْتُ فِيهَا صَاحِبَ الْمِحْجَنِ يَجُرُّ قُصْبَهُ فِي النَّارِ. كَانَ يَسْرِقُ الْحَاجَّ بِمِحْجَنِهِ. فَإِنْ فُطِنَ لَهُ قَالَ: إِنَّمَا تَعَلَّقَ بِمِحْجَنِي. وَإِنْ غُفِلَ عَنْهُ ذَهَبَ بِهِ، وَحَتَّى رَأَيْتُ فِيهَا صَاحِبَةَ الْهِرَّةِ الَّتِي رَبَطَتْهَا فَلَمْ تُطْعِمْهَا، وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ. حَتَّى مَاتَتْ جُوعًا، ثُمَّ جِيءَ بِالْجَنَّةِ، وَذَلِكُمْ حِينَ رَأَيْتُمُونِي تَقَدَّمْتُ حَتَّى قُمْتُ فِي مَقَامِي، وَلَقَدْ مَدَدْتُ يَدِي وَأَنَا أُرِيدُ أَنْ أَتَنَاوَلَ مِنْ ثَمَرِهَا لِتَنْظُرُوا إِلَيْهِ، ثُمَّ بَدَا لِي أَنْ لَا أَفْعَلَ، فَمَا مِنْ شَيْءٍ تُوعَدُونَهُ إِلَّا قَدْ رَأَيْتُهُ فِي صَلَاتِي هَذِهِ."],"takhrij":"صحيح: رواه مسلم في الكسوف (904/10) من طرقٍ عن عبدالله بن نُمير، حدثنا عبد الملك، عن عطاء، عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما رُويَ أنَّ صلاةَ الكسوف ستّة ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (904). However, the wording “he prayed with the people six bowings and four prostrations” is shādhdh (irregular), because what is correctly preserved from Jābir is that the eclipse prayer was four bowings and four prostrations.","chapter_en":"What has been narrated that the eclipse prayer is six bowings (rukūʿ) in two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":4,"content":{"translation":{"en":["Jābir said: The sun eclipsed during the time of the Messenger of Allah ﷺ on the day Ibrāhīm, the son of the Messenger of Allah ﷺ, died. People said, “It eclipsed because of Ibrāhīm’s death.” So the Prophet ﷺ stood and led the people in an eclipse prayer with six bowings and four prostrations. He began by saying takbīr, then recited and prolonged the recitation, then bowed for a duration close to his standing. Then he raised his head from bowing and recited again, shorter than the first recitation; then bowed again for a duration close to his standing. Then he raised his head and recited again, shorter than the second; then bowed again for a duration close to his standing, then raised his head. Then he went down into prostration and made two prostrations. Then he stood and again performed three bowings, with each one shorter than the one before it, and his bowing was close in length to his prostration. Then he stepped back and the rows behind him stepped back until we reached the rear. (Abū Bakr said: until he reached the women.) Then he moved forward and the people moved forward with him until he returned to his place. He finished when he finished, and the sun had returned to normal. Then he said: “O people! The sun and the moon are two signs from the signs of Allah, and they do not eclipse for the death of anyone among people (Abū Bakr said: for the death of any human). So when you see something of that, pray until it clears. There is nothing you are promised except that I have seen it in this prayer of mine. The Fire was brought near—this was when you saw me step back, fearing that some of its heat might reach me. And I saw in it the man with the hooked staff dragging his intestines in the Fire; he used to steal from pilgrims with his hooked staff—if he was noticed he would say, ‘It only got caught on my hook,’ and if he was not noticed he would leave with it. And I saw in it the woman who owned the cat who tied up her cat and did not feed it, nor did she let it eat from the vermin of the earth until it died of hunger. Then Paradise was brought near—this was when you saw me step forward until I stood in my place. I stretched out my hand wanting to take some of its fruit so you could see it, then it occurred to me not to do so. There is nothing you are promised except that I have seen it in this prayer of mine.”"]},"buhuth":{"en":["His phrase “and the sun had returned (آضَتِ الشمس)” means it returned to its normal state before the eclipse."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (904/10). إلا قوله: “فصلى بالناس ست ركعات بأربع سجدات” فهو شاذ لأن الصحيح المحفوظ عن جابر: “أن صلاته ﷺ كانت أربع ركعات وأربع سجدات”."},{"num":2986,"demo":false,"sanad":"","matn":["عن عطاء يَقُولُ: سَمِعْتُ عُبَيْدَ بْنَ عُمَيْرٍ يَقُولُ: حَدَّثَنِي مَنْ أُصَدِّقُ - حَسِبْتُهُ يُرِيدُ عَائِشَةَ -  أَنَّ الشَّمْسَ انْكَسَفَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَامَ قِيَامًا شَدِيدًا. يَقُومُ قَائِمًا ثُمَّ يَرْكَعُ، ثُمَّ يَقُومُ، ثُمَّ يَرْكَعُ، ثُمَّ يَقُومُ، ثُمَّ يَرْكَعُ، رَكْعَتَيْنِ فِي ثَلَاثِ رَكَعَاتٍ، وَأَرْبَعِ سَجَدَاتٍ. فَانْصَرَفَ، وَقَدْ تَجَلَّتِ الشَّمْسُ. وَكَانَ إِذَا رَكَعَ قَالَ: اللَّهُ أَكْبَرُ ثُمَّ يَرْكَعُ. وَإِذَا رَفَعَ رَأْسَهُ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقَامَ فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ. ثُمَّ قَالَ: إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَكْسِفَانِ لِمَوْتِ أَحَدٍ، وَلَا لِحَيَاتِهِ، وَلَكِنَّهُمَا مِنْ آيَاتِ اللَّهِ يُخَوِّفُ اللهُ بِهِمَا عِبَادَهُ، فَإِذَا رَأَيْتُمْ كُسُوفًا، فَاذْكُرُوا اللهَ حَتَّى يَنْجَلِيَا."],"takhrij":"صحيح: رواه مسلم في الكسوف (901) عن إسحاق بن إبراهيم، أخبرنا محمد بن بكر، أخبرنا ابن جريج، قال: سمعت عطاءً فذكره.","grade":"صحيح","chapter_ar":"باب ما رُويَ أنَّ صلاةَ الكسوف ستّة ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (901). However, the wording “three bowings” is shādhdh (irregular) and contradicts what is authentically established: that the Prophet ﷺ prayed two rakʿahs, with two bowings in each rakʿah.","chapter_en":"What has been narrated that the eclipse prayer is six bowings (rukūʿ) in two units (rakʿahs).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":4,"content":{"translation":{"en":["ʿAṭā’ said: I heard ʿUbayd ibn ʿUmayr say: Someone I trust narrated to me—he thought it was ʿĀ’ishah—that the sun eclipsed during the time of the Messenger of Allah ﷺ. He stood for a very long standing: he would stand then bow, then stand then bow, then stand then bow—two rakʿahs with three bowings, and four prostrations. He finished and the sun had cleared. When he bowed he would say “Allāhu Akbar,” and when he raised his head he would say “Samiʿa Allāhu liman ḥamidah,” then he would stand praising Allah and extolling Him, then he said: “The sun and the moon do not eclipse for the death of anyone nor for their life; rather they are among the signs of Allah by which Allah frightens His servants. So when you see an eclipse, remember Allah until they clear.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (901) إلا قوله: “ثلاث ركعات” فهو شاذ مخالف لما صح أنه ﷺ صلى ركعتين، وركع في كل ركعة ركوعين."},{"num":2987,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَنَّهُ صَلَّى فِي كُسُوفٍ، قَرَأَ ثُمَّ رَكَعَ، ثُمَّ قَرَأَ ثُمَّ رَكَعَ، ثُمَّ قَرَأَ ثُمَّ رَكَعَ، ثُمَّ قَرَأَ ثُمَّ رَكَعَ، ثُمَّ سَجَدَ، قَالَ: وَالْأُخْرَى مِثْلُهَا.","وفي رواية: صلى رسول الله صلى الله عليه وسلم حين كسفتِ الشمسُ ثماني ركعات في أربع سجدات، وعن عليٍّ مثل ذلك."],"takhrij":"صحيح: رواه مسلم في الكسوف (909) من طريق يحيى، عن سفيان، قال: حدثنا حبيب، عن طاوس، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما رُويَ أن صلاة الكسوف ثمانية ركوعات في ركعتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (908) and (909). However, the wording “eight bowings with four prostrations” is shādhdh (irregular).","chapter_en":"What has been narrated that the eclipse prayer is eight bowings in two rakʿahs.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās narrated from the Prophet ﷺ that he prayed during an eclipse: he recited then bowed; then recited then bowed; then recited then bowed; then recited then bowed; then he prostrated— and he said: and the other (rakʿah) was the same. In another narration: The Messenger of Allah ﷺ prayed when the sun eclipsed eight bowings with four prostrations, and from ʿAlī likewise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (909) ،(909). إلا قوله: ((ثماني ركعات في أربع سجدات) فهو شاذ."},{"num":2988,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا جَهَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلاَةِ الْخُسُوفِ بِقِرَاءَتِهِ، فَإِذَا فَرَغَ مِنْ قِرَاءَتِهِ كَبَّرَ فَرَكَعَ، وَإِذَا رَفَعَ مِنَ الرَّكْعَةِ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ. ثُمَّ يُعَاوِدُ الْقِرَاءَةَ فِي صَلاَةِ الْكُسُوفِ، أَرْبَعَ رَكَعَاتٍ فِي رَكْعَتَيْنِ، وَأَرْبَعَ سَجَدَاتٍ."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1065)، ومسلم في الكسوف (901/5) كلاهما عن محمد بن مهران، قال: حدثنا الوليد، قال: أخبرنا ابن نمر، سمع ابن شهاب، عن عروة، عن عائشة فذكرته واللفظ للبخاري ولفظ مسلم مختصرٌ.","grade":"متفق عليه","chapter_ar":"باب الجهر بالقراءة في الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1065) and Muslim (901), with the wording from al-Bukhārī.","chapter_en":"Reciting aloud in the eclipse prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":6,"content":{"translation":{"en":["ʿĀ’ishah said: The Prophet ﷺ recited aloud in the eclipse prayer. When he finished his recitation he said takbīr and bowed. When he rose from bowing he said: “Samiʿa Allāhu liman ḥamidah; our Lord, to You belongs all praise.” Then he resumed recitation. In the eclipse prayer there are four bowings in two rakʿahs, and four prostrations."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1065)، ومسلم (901/5) واللفظ للبخاري."},{"num":2989,"demo":false,"sanad":"","matn":["عَنْ مَحْمُودِ بْنِ لَبِيدٍ، قَالَ: كَسَفَتِ الشَّمْسُ يَوْمَ مَاتَ إِبْرَاهِيمُ ابْنُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: كَسَفَتِ الشَّمْسُ لِمَوْتِ إِبْرَاهِيمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، أَلَا وَإِنَّهُمَا لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمُوهُمَا كَذَلِكَ فَافْزَعُوا إِلَى الْمَسَاجِدِ ثُمَّ قَامَ فَقَرَأَ فِيمَا نَرَى بَعْضَ ﴿الر كِتَابٌ﴾، [إبراهيم: ١] ثُمَّ رَكَعَ، ثُمَّ اعْتَدَلَ، ثُمَّ سَجَدَ سَجْدَتَيْنِ، ثُمَّ قَامَ فَفَعَلَ مِثْلَ مَا فَعَلَ فِي الْأُولَى."],"takhrij":"حسن: رواه الإمام أحمد (23629) عن يحيى بن آدم، حدثنا عبدالرحمن ابن سليمان بن الغَسيل، عن عاصم بن عمر بن قتادة، عن محمود بن لَبِيد فذكره.","grade":"حسن","chapter_ar":"باب الجهر بالقراءة في الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Aḥmad (23629). The phrase “then he bowed, then rose, then made two prostrations” is mentioned in a shortened form here; what is authentically established is that he bowed two bowings in a single rakʿah.","chapter_en":"Reciting aloud in the eclipse prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":6,"content":{"translation":{"en":["Maḥmūd ibn Labīd said: The sun eclipsed on the day Ibrāhīm, the son of the Messenger of Allah ﷺ, died. People said, “The sun eclipsed because of Ibrāhīm’s death.” The Messenger of Allah ﷺ said: “Indeed the sun and the moon are two signs from the signs of Allah. Truly, they do not eclipse for the death of anyone nor for their life. So when you see them like that, rush to the mosques.” Then he stood and recited—according to what we think—part of the verse: “Grievous is the word that comes out of their mouths…” (al-Kahf 18:5), then he bowed, then rose upright, then made two prostrations, then stood and did the same in the second (rakʿah) as he did in the first."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (23629). وقوله: “ثم ركع، ثم اعتدل، ثم سجد سجدتين”، هكذا ذكره مختصرا، والصحيح الثابت أنه ركع ركوعين في ركعة واحدة."},{"num":2990,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ قَالَ: انْخَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فصلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ طَوِيلاً نَحْوًا مِنْ قِرَاءَةِ سُورَةِ الْبَقَرَةِ فِي حَدِيثِ طَوِيلٍ."],"takhrij":"متفق عليه: رواه مالك في الكسوف (2) عن زيد بن أسلم عن عطاء بن يسار، عن عبدالله بن عباس فذكره في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب من قال: لا يجهر في صلاة الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik (2), al-Bukhārī (1052), and Muslim (907).","chapter_en":"Those who said: One does not recite aloud in the eclipse prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: The sun eclipsed during the time of the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ prayed. He stood for a long time—about the length of reciting Sūrat al-Baqarah—in a longer narration."]},"buhuth":{"en":["This does not prove that the recitation was silent."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2) ورواه البخاري (1052)، ومسلم (907)."},{"num":2991,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كُسِفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِالنَّاسِ فَقَامَ فَحَزَرْتُ قِرَاءَتَهُ، فَرَأَيْتُ أَنَّهُ قَرَأَ بِسُورَةِ الْبَقَرَةِ، - وَسَاقَ الْحَدِيثَ، - ثُمَّ سَجَدَ سَجْدَتَيْنِ، ثُمَّ قَامَ فَأَطَالَ الْقِرَاءَةَ، فَحَزَرْتُ قِرَاءَتَهُ فَرَأَيْتُ أَنَّهُ قَرَأَ بِسُورَةِ آلِ عِمْرَانَ."],"takhrij":"حسن: رواه أبو داود (1187) عن عبيدالله بن سعد، حدثنا عمي، حدثنا أبي، عن محمد بن إسحاق، حدثني هشام بن عروة وعبدالله بن أبي سلمة، عن سليمان بن يسار، كلهم قد حدثني عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب من قال: لا يجهر في صلاة الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan: narrated by Abū Dāwūd (1187). When weighing evidence, what is in the two Ṣaḥīḥs from her is given precedence.","chapter_en":"Those who said: One does not recite aloud in the eclipse prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":7,"content":{"translation":{"en":["ʿĀ’ishah said: The sun eclipsed during the time of the Messenger of Allah ﷺ. The Messenger of Allah ﷺ went out and stood (in prayer). I estimated his recitation and thought that he recited Sūrat al-Baqarah. The narration continues: then he made two prostrations, then he stood and prolonged the recitation. I estimated his recitation and thought that he recited Sūrat Āl ʿImrān."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1187). في حالة الترجيح يقدم ما في الصحيحين من حديثها."},{"num":2992,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ ، أَنَّهَا قَالَتْ: : فَزِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا ، قَالَتْ : تَعْنِي يَوْمَ كَسَفَتِ الشَّمْسُ ، فَأَخَذَ دِرْعًا حَتَّى أُدْرِكَ بِرِدَائِهِ، ، فَقَامَ لِلنَّاسِ قِيَامًا طَوِيلًا، ، لَوْ أَنَّ إِنْسَانًا أَتَى لَمْ يَشْعُرْ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكَعَ مَا حَدَّثَ أَنَّهُ رَكَعَ مِنْ طُولِ الْقِيَامِ.","وفي رواية: وَقَالَ : قِيَامًا طَوِيلًا يَقُومُ ، ثُمَّ يَرْكَعُ ، وَزَادَ : فَجَعَلْتُ أَنْظُرُ إِلَى الْمَرْأَةِ أَسَنَّ مِنِّي ، وَإِلَى الْأُخْرَى هِيَ أَسْقَمُ مِنِّي.","وفي رواية: فَقَضَيْتُ حَاجَتِي ، ثُمَّ جِئْتُ وَدَخَلْتُ الْمَسْجِدَ ، فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمًا ، فَقُمْتُ مَعَهُ فَأَطَالَ الْقِيَامَ حَتَّى رَأَيْتُنِي أُرِيدُ أَنْ أَجْلِسَ ، ثُمَّ أَلْتَفِتُ إِلَى الْمَرْأَةِ الضَّعِيفَةِ ، فَأَقُولُ : هَذِهِ أَضْعَفُ مِنِّي فَأَقُومُ ، فَرَكَعَ فَأَطَالَ الرُّكُوعَ ، ثُمَّ رَفَعَ رَأْسَهُ فَأَطَالَ الْقِيَامَ ، حَتَّى لَوْ أَنَّ رَجُلًا جَاءَ خُيِّلَ إِلَيْهِ أَنَّهُ لَمْ يَرْكَعْ."],"takhrij":"صحيح: هذه الروايات كلها رواها مسلم في الكسوف (906/14،15،16) من طرق عن منصور بن عبدالرحمن، عن أمه صفية بنت شيبة، عن أسماء بنت أبي بكر فذكرتها.","grade":"صحيح","chapter_ar":"باب طول القيام في الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: all of these narrations are in Muslim (906).","chapter_en":"The lengthening of standing in the eclipse prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":8,"content":{"translation":{"en":["Asmā’ bint Abī Bakr said: The Prophet ﷺ was alarmed one day—she meant the day the sun eclipsed—so, in his haste, he took an outer garment until his own cloak was brought to him, then he stood for the people in a very long standing. If someone had come, he would not have realized that the Prophet ﷺ had bowed—she did not mention that he bowed—because of the length of the standing. In another narration: He stood for a long standing, standing and then bowing; and she added: I began looking at a woman older than me, and another who was sicker than me (to draw strength from them).","In another narration: I took care of my need, then came and entered the mosque and saw the Messenger of Allah ﷺ standing, so I stood with him. He prolonged the standing until I felt I wanted to sit. Then I would look toward a weak woman and say, “She is weaker than me,” so I would keep standing. Then he bowed and prolonged the bowing, then raised his head and prolonged the standing—so much that if a man had arrived, he might have thought that he had not bowed yet."]}},"tuhfa":{},"voc":["muslim",2106],"full":1,"tks":"صحيح: هذه الروايات كلها رواها مسلم (14،15،16/906)."},{"num":2993,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهَا قَالَتْ: أَتَيْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ خَسَفَتِ الشَّمْسُ، فَإِذَا النَّاسُ قِيَامٌ يُصَلُّونَ، وَإِذَا هِيَ قَائِمَةٌ تُصَلِّي، فَقُلْتُ: مَا لِلنَّاسِ؟ فَأَشَارَتْ بِيَدِهَا إِلَى السَّمَاءِ، وَقَالَتْ: سُبْحَانَ اللَّهِ. فَقُلْتُ: آيَةٌ؟ فَأَشَارَتْ: أَىْ نَعَمْ. قَالَتْ: فَقُمْتُ حَتَّى تَجَلاَّنِي الْغَشْىُ، فَجَعَلْتُ أَصُبُّ فَوْقَ رَأْسِي الْمَاءَ، فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: مَا مِنْ شَىْءٍ كُنْتُ لَمْ أَرَهُ إِلاَّ قَدْ رَأَيْتُهُ فِي مَقَامِي هَذَا، حَتَّى الْجَنَّةَ وَالنَّارَ، وَلَقَدْ أُوحِيَ إِلَىَّ أَنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ مِثْلَ ـ أَوْ قَرِيبًا مِنْ ـ فِتْنَةِ الدَّجَّالِ، ـ لاَ أَدْرِي أَيَّتَهُمَا قَالَتْ أَسْمَاءُ، ـ يُؤْتَى أَحَدُكُمْ فَيُقَالُ لَهُ: مَا عِلْمُكَ بِهَذَا الرَّجُلِ؟، فَأَمَّا الْمُؤْمِنُ، ـ أَوِ الْمُوقِنُ، لاَ أَدْرِي أَىَّ ذَلِكَ قَالَتْ أَسْمَاءُ، ـ فَيَقُولُ: مُحَمَّدٌ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، جَاءَنَا بِالْبَيِّنَاتِ وَالْهُدَى، فَأَجَبْنَا وَآمَنَّا وَاتَّبَعْنَا. فَيُقَالُ لَهُ: نَمْ صَالِحًا، فَقَدْ عَلِمْنَا إِنْ كُنْتَ لَمُوقِنًا. وَأَمَّا الْمُنَافِقُ، ـ أَوِ الْمُرْتَابُ لاَ أَدْرِي أَيَّتَهُمَا قَالَتْ أَسْمَاءُ ـ فَيَقُولُ: لاَ أَدْرِي، سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ."],"takhrij":"متفق عليه: رواه مالك في الكسوف (4) عن هشام بن عروة، عن فاطمة بنت المنذر، عن أسماء بنت أبي بكر فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما عُرض على النبي ﷺ في صلاة الكسوف من أمر الجنة والنار","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik (4), al-Bukhārī (1053), and Muslim (905). In it: the Messenger of Allah ﷺ prolonged the standing greatly until faintness occurred.","chapter_en":"What was shown to the Prophet ﷺ during the eclipse prayer regarding Paradise and the Fire.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":9,"content":{"translation":{"en":["Asmā’ bint Abī Bakr (may Allah be pleased with them both) said: I came to ʿĀ’ishah (may Allah be pleased with her), the wife of the Prophet ﷺ, at the time when the sun eclipsed. The people were standing, praying, and she was standing, praying. I said: What is the matter with the people? She pointed with her hand toward the sky and said: “Subḥānallāh.” I said: A sign? She gestured: “Yes.” She said: So I stood until faintness (al-ghashī) overcame me, and I began pouring water over my head. When the Messenger of Allah ﷺ finished, he praised Allah and exalted Him, then said: “There is nothing I had not been shown except that I have been shown it in this place of mine—even Paradise and the Fire. And it has been revealed to me that you will be tried in your graves like—or close to—the trial of the Dajjāl.” I do not know which of the two Asmā’ said. “One of you will be brought and it will be said to him: What do you know about this man? As for the believer—or the one who is certain—I do not know which Asmā’ said, he will say: Muḥammad is the Messenger of Allah. He came to us with clear proofs and guidance, so we responded, believed, and followed. It will be said to him: Sleep as a righteous one; we knew you were truly certain. And as for the hypocrite—or the doubter—I do not know which of the two Asmā’ said, he will say: I do not know; I heard people saying something, so I said it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4) والبخاري (1053) ومسلم (905) وفيه: فأطال رسول الله ﷺ القيام جدا حتى تجلاني الغشي."},{"num":2994,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعَتَاقَةِ فِي كُسُوفِ الشَّمْسِ."],"takhrij":"صحيح: رواه البخاري في الكسوف (1054) وفي العتق (2519) من طريق زائدة بن قدامة، عن هشام، عن فاطمة بنت المنذر، عن أسماء فذكرته.","grade":"صحيح","chapter_ar":"باب استحباب الصدقة في الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Bukhārī (1054).","chapter_en":"The recommendation of charity during an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":10,"content":{"translation":{"en":["Asmā’ bint Abī Bakr said: The Prophet ﷺ ordered emancipation (ʿitāqah) during the solar eclipse."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1054)."},{"num":2995,"demo":false,"sanad":"","matn":["عن عائشة قالت: خَسَفَتْ الشَّمْسُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ، وفيه... ثُمَّ قَالَ: إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ، فَادْعُوا اللَّهَ، وَكَبِّرُوا، وَتَصَدَّقُوا...  الحديث."],"takhrij":"متفق عليه: رواه مالك في الكسوف (1) عن هشام بن عروة، عن أبيه، عن عائشة.","grade":"متفق عليه","chapter_ar":"باب استحباب الصدقة في الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik in al-Kusūf (1) (wording is his), and by al-Bukhārī (1044) and Muslim (901).","chapter_en":"The recommendation of charity during an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":10,"content":{"translation":{"en":["ʿĀ’ishah said: The sun eclipsed during the time of the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ led the people in prayer… then he said: “Indeed the sun and the moon are two signs from the signs of Allah. They do not eclipse for the death of anyone nor for his life. So when you see that, then call upon Allah, say takbīr, and give charity…” (the ḥadīth)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1) واللفظ له، والبخاري (1044)، ومسلم (901)."},{"num":2996,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ يَهُودِيَّةً جَاءَتْ تَسْأَلُهَا، فَقَالَتْ: أعاذَكِ اللَّهُ مِنْ عَذَابِ الْقَبْرِ، فَسَأَلَتْ عَائِشَةُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أيُعَذَّبُ النَّاسُ فِي قُبُورِهِمْ؟ فقـــــال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، عَائِذًا بِاللَّهِ مِنْ ذَلِكَ، ثُمَّ ركبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، ذَاتَ غَدَاةٍ، مَرْكَبًا، فخسَفَتِ الشَّمْسُ، فَرَجَعَ ضُحّى، فمرَّ بَيْنَ ظهراني الْحُجَرِ، ثُمَّ قَامَ يُصلِّي وَقَامَ النَّاسُ وَرَاءَهُ، فَقَامَ قِياماً طَوِيلاً، ثُمَّ ركعَ رُكُوعاً طَوِيلاً ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلاً وَهْوَ دونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً وَهْوَ دونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ رَفَعَ فَسَجَدَ، ثُمَّ قَامَ قِيَامًا طَوِيلاً وَهْوَ دونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ رُكُوعًا طَوِيلاً وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ ثُمَّ رَفَعَ فَقَامَ قِيَامًا طَوِيلاً وَهْوَ دونَ الْقِيَامِ الأوَّل، ثُمَّ رَكَعَ ركُوعاً طَوِيلاً وهُوَ دُونَ الرُّكُوعِ الأوَّل، ثُمَّ رَفَعَ، ثُمَّ سَجَدَ ثُمَّ انْصَرفَ فَقَالَ مَا شاءَ اللَّهُ أَنْ يقُولَ، ثُمَّ أَمَرَهُمْ أَنْ يتَعَوذُوا مِنْ عَذَابِ القَبْرِ."],"takhrij":"متفق عليه: رواه مالك في الكسوف (3) عن يحيى بن سعيد، عن عمرة بنت عبدالرحمن، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب التّعوذ من عذاب القبر في الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Mālik (3), al-Bukhārī (1049), and Muslim (903).","chapter_en":"Seeking refuge from the punishment of the grave during an eclipse.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, said: A Jewish woman came asking her (something) and said: “May Allah protect you from the punishment of the grave.” So ʿĀ’ishah asked the Messenger of Allah ﷺ: “Are people punished in their graves?” The Messenger of Allah ﷺ said, seeking refuge with Allah from that. Then, one morning, the Messenger of Allah ﷺ rode out, and the sun eclipsed. He returned in the forenoon, passed through the area between the dwellings (al-ḥijr), then stood to pray and the people stood behind him. He stood a long standing, then bowed a long bowing, then rose and stood a long standing, shorter than the first standing; then bowed a long bowing, shorter than the first bowing; then rose and prostrated. Then he stood a long standing, shorter than the first standing; then bowed a long bowing, shorter than the first bowing; then rose and stood a long standing, shorter than the first standing; then bowed a long bowing, shorter than the first bowing; then rose, then prostrated; then he finished and said what Allah willed him to say, then he commanded them to seek refuge from the punishment of the grave."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (3) والبخاري (1049) ومسلم (903)."},{"num":2997,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: خَسَفَتِ الشَّمْسُ فِي حَيَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَخَرَجَ إِلَى الْمَسْجِدِ، فَصَفَّ النَّاسُ وَرَاءَهُ، فكبَّر فَاقْتَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِرَاءَةً طَوِيلَةً، ثُمَّ كبَّر فَرَكَعَ رُكُوعًا طَوِيلاً. ثُمَّ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقَامَ وَلَمْ يَسْجُدْ وَقَرَأَ قِرَاءَةً طَوِيلَةً، هِيَ أَدْنَى مِنَ الْقِرَاءَةِ الْأُولَى، ثُمَّ كبَّر وَرَكَعَ رُكُوعًا طَوِيلاً، وَهْوَ أَدْنَى مِنَ الرُّكُوعِ الأَوَّلِ، ثُمَّ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ ثُمَّ سَجَدَ، ثُمَّ قَالَ فِي الرَّكْعَةِ الآخِرَةِ مِثْلَ ذَلِكَ، فَاسْتَكْمَلَ أَرْبَعَ رَكَعَاتٍ فِي أَرْبَعِ سَجَدَاتٍ، وَانْجَلَتِ الشَّمْسُ قَبْلَ أَنْ يَنْصَرِفَ. ثُمَّ قَامَ فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ: هُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمُوهُمَا فانزعوا إِلَى الصَّلاَةِ ."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1046) مسلم في الكسوف (901/3) كلاهما من طريق ابن شهاب، حدثني عروة، عن عائشة، فذكرته، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب خطبة الإمام بعد صلاة الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1046) and Muslim (3/901); wording is al-Bukhārī’s.","chapter_en":"The imam’s sermon after the eclipse prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah said: The sun eclipsed during the lifetime of the Prophet ﷺ. He went out to the mosque and the people formed rows behind him. He said takbīr, and the Messenger of Allah ﷺ recited a long recitation, then said takbīr and bowed a long bowing. Then he said: “Allah hears the one who praises Him,” and he stood without prostrating, and recited a long recitation, shorter than the first recitation. Then he said takbīr and bowed a long bowing, shorter than the first bowing. Then he said: “Allah hears the one who praises Him; our Lord, to You belongs all praise,” then he prostrated. Then in the second rakʿah he did the same. Thus he completed four bowings and four prostrations, and the sun cleared before he finished. Then he stood and praised Allah as He deserves, then said: “They are two signs from the signs of Allah. They do not eclipse for the death of anyone nor for his life. So when you see them, hasten to the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1046) ومسلم (901/3)، واللفظ للبخاري."},{"num":2998,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ قَالَتْ: فَانْصَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ تَجَلَّتِ الشَّمْسُ، فَخَطَبَ فَحَمِدَ اللَّهَ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ: أَمَّا بَعْدُ ."],"takhrij":"متفق عليه: رواه البخاري في الكسوف (1061) مُعَلَّقاً قائلاً: وقال أبو أسامة، حدثنا هشام، قال: أخبرتني فاطمة بنت المنذر، عن أسماء فذكرته هكذا مختصراً.","grade":"متفق عليه","chapter_ar":"باب خطبة الإمام بعد صلاة الكسوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1061, 922) and Muslim (905).","chapter_en":"The imam’s sermon after the eclipse prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الكسوف","group_en":"Collected chapters on the eclipse prayer.","part_no":9,"group_no":22,"chapter_no":12,"content":{"translation":{"en":["Asmā’ bint Abī Bakr said: The Messenger of Allah ﷺ finished while the sun had cleared, then he delivered a sermon, praising Allah as He deserves, then he said: “As for what follows…”"]},"buhuth":{"en":["Fiqh of the Eclipse Chapter — This contains several issues:","Ruling of the eclipse prayer: It is a highly emphasized Sunnah for both men and women.","How the eclipse prayer is performed: According to the strongest view among the scholars, it is recommended to pray it as in the ḥadīth of ʿĀ’ishah and others: two bowings in each rakʿah, meaning four bowings and four prostrations in total.","What if the prayer ends before the eclipse clears: If one finishes the prayer before the eclipse clears, he does not repeat it; rather he continues with remembrance of Allah and supplication, based on the Prophet’s ﷺ instruction: “When you see that, then call upon Allah, say takbīr, and give charity.” Because the intent during an eclipse includes both prayer and duʿā’—sometimes one of them alone achieves what is sought, sometimes not; when it clears, the purpose has been fulfilled.","What if the eclipse clears during the prayer: He does not cut the prayer; rather he completes it lightly.","When is the sermon: The sermon is after the eclipse prayer, and it is recommended according to the majority of scholars in their strongest view."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1061 و922) ومسلم (905)."},{"num":2999,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله قال: كان رسولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعلِّمُنا الاستخارةَ في الأمُور كما يُعلِّمنا السورة منَ القرآنِ يَقولُ: إذا همَّ أحدُكم بالأمرِ فلْيَركعْ رَكعتَين من غَيرِ الفريضةِ، ثمَّ لِيَقُلْ: اللَّهُمَّ إني أستخيرُكَ بعِلمكَ، وأستَقْدِرُكَ بقُدرَتِكَ،وأسأَلُكَ من فضلِكَ العظيمِ، فإنَّكَ تَقدِرُ ولا أقدِرُ، وتَعلَمُ ولا أعلَمُ وأنت علاَّمُ الغُيوب، اللهُمَّ إن كنتَ تعلمُ أنَّ هذا الأمرَ خيرٌ لي فِي دِيني ومَعاشي وعاقِبةِ أمري -أو قال: عاجل أمري وآجِلِه- فاقدُرْهُ لِي، ويَسِّرْهُ لي، ثمَّ باركْ لي فيه، وإن كنتَ تَعلمُ أنَّ هذا الأمرَ شَرٌّ لي في دِيني ومَعاشي وعاقبةِ أمري -أو قال: في عاجل أمري وآجلهِ- فاصرِفهُ عَنِّي واصرفني عنهُ، واقدُرْ لي الخيرَ حيثُ كان، ثمَّ أرضِني، قال: ويُسمِّي حاجَتَهُ ."],"takhrij":"صحيح: رواه البخاري في التهجد (1162) عن قتيبة قال: حدثنا عبدالرحمن بن أبي الموالِ، عن محمد بن المنكدر، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"صلاة الاستخارة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: narrated by al-Bukhārī (1162).","chapter_en":"The Prayer of Istikhārah.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الاستخارة، وصلاة المريض، والصلاة في السفينة، وصلاة الحاجة","group_en":"Collections of chapters: the Prayer of Istikhārah, the Prayer of the sick person, praying on a ship, and the Prayer of need.","part_no":9,"group_no":23,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Messenger of Allah ﷺ used to teach us istikhārah in matters just as he would teach us a sūrah from the Qur’an. He said: “If one of you is about to undertake a matter, let him pray two rakʿahs other than the obligatory prayer, then let him say: O Allah, I seek Your guidance by Your knowledge, and I seek ability by Your power, and I ask You from Your immense bounty. For You are able and I am not able; You know and I do not know; and You are the Knower of the unseen. O Allah, if You know that this matter is good for me in my religion, my livelihood, and the outcome of my affair—or he said: in the immediate and later part of my affair—then decree it for me, make it easy for me, then bless it for me. And if You know that this matter is bad for me in my religion, my livelihood, and the outcome of my affair—or he said: in the immediate and later part of my affair—then turn it away from me and turn me away from it, and decree for me the good wherever it may be, then make me satisfied with it.” He said: “And he should name his need.”"]},"intro_majmu":{"ar":["١- صلاة الاستخارة"],"en":["1 — The Prayer of Istikhārah."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1162)."}]);